window.__D("text/torat-chaim/c026",{"p":[[2300540854,"שישמחנו כימות עניתנו<sup data-n=\"11416\">696</sup> כו', וזהו פרזות תשב ירושלים (כמשי\"ת).\n<b>ומעתה</b> י\"ל שרש ענין ש\"ת והוש\"ר<sup data-n=\"11417\">697</sup>. הנה מ\"ש צפ\"ר הוא פרזונו ממש כפשוטו, אך הנה כתי' פרזות תשב ירושלים כו', וי\"ל מהו הרבותא והמעלה כאשר תהי' ישיבת ירושלים בלא [היקף] חומה כלל כערי הפרזות והלא עיקר<sup data-n=\"11418\">698</sup> [ה]מוקפת חומה משובח הרבה<sup data-n=\"11419\">699</sup> יותר ובפרט [ל]ענין המלחמה שהחומה מגינה עלי' מכל אויב כידוע. הנה הוא בא לומר בזה ב' דברים, א' שירושלים דלע\"ל לא תהי' צריכה לחומה כלל, כי עיקר ענין היקף החומה הוא לשמירה מן האויב לבד שלא יוכל לגשת אל העיר. אבל לע\"ל לא יהי' שום אויב ומנגד כלל לבחי' הקדושה האלקי' כי רוח הטומאה יעבור מן הארץ לגמרי, [וגם] כל ע\"ש דנוגה יהפכו לקדושה האלקי' כמ\"ש אז אהפוך אל עמים כו' כנ\"ל, כי יגלה כבוד ה' וראו כ\"ב כו'. ומאחר שאין מנגד כלל שיצטרך שמירה לפניו ע\"כ לא יצטרך אז לחומה לשמור לירושלים לכך א' פרזות תשב ירושלים. משא\"כ עכשיו [ש]יש בחי' מנגד לסט' דקדושה שהן ע\"ש דקליפת נוגה ע\"כ א' על חומותיך ירושלים הפקדתי שומרים<sup data-n=\"11420\">700</sup> כו', שצריך לחומה לירושלים שלמעלה והופקדו שומרים על החומה לבל יקרבו זרים שם לקבל יניקה מאור האלקי השוכן בירושלים, כך הוא בירושלים שלמטה שהן המזכירים את ה' לבל ישלטו אויבים בירושלים כו'. וזהו עיקר ענין החומה המקפת לעיר דהיינו ענין הב' לבד השמירה מאויב שלא יכנס למלחמה אלא גם משאר זרים שלא יכנסו לעיר ירושלים לקבל מקדושתה, והחומה הוא ענין הגבלה שמגבלת תחום העיר ויושביה בהיקף סביב לה מכל צד בב' ענינים. א' הגבלת אור הקדושה שבה שמוגבלת עד החומה כידוע ביו\"ד קדושות<sup data-n=\"11421\">701</sup> שבירושלים הי' הקדושה האחרונה החיל והחומה לענין מעשר וכמה דברים. והב' בהגבלת החיצוני' שעומדים מחוץ לירושלים שיגבל להם החומה כמו התחום שניתן להם לגבול ומדה לומר עד פה תבוא ותו לא כמו תחום שבת וכה\"ג, [וזהו] על חומותיך ירושלים הפקדתי שומרים כו'. ושמירה זו היא בשביל זרים שהן החיצוני' שלא יקבלו יניקה מן הקדושה כו' (והוא ע\"י <span data-k=\"pg\">שלט</span> ּ השומרים העומדים על השערים ששומרים אותו<sup data-n=\"11422\">703</sup> בלילה<sup data-n=\"11423\">702</sup> והופקדו שומרים על השערים בלילה דוקא, אבל ביום השערים פתוחים לכל יוצא ובא בשערי ירושלים כו', כך הוא בשערי ג\"ע כמ\"ש בזהר דתרעי דג\"ע אסתימו בלילה<sup data-n=\"11424\">704</sup> כו'. והענין הוא לפי שבאמת עיקר",[["11416","696","<b>שישמחנו כימות עניתנו</b>: תהלים צ, טו."],["11417","697","<b>ש\"ת והוש\"ר</b>: ח: שמחת תורה והושענא רבה."],["11418","698","<b>עיקר</b>: דח: עיר. ט: ליתא."],["11419","699","<b>הרבה</b>: דח: ומפואר."],["11420","700","<b>על חומותיך ירושלים הפקדתי שומרים</b>: ישעי' סב, ו."],["11421","701","<b>ביו\"ד קדושות</b>: ראה כלים פ\"א, מ\"ו. שע\"ת פב, ג ובהערה 90. וראה גם מאמרי אדה\"א במדבר ח\"ג ע' תתקמח."],["11422","703","<b>ששומרים אותו</b>: חט: שסוגרים אותם."],["11423","702","<b>ירושלים. . שסוגרים אותם בלילה</b>: ראה ערובין ו, ב."],["11424","704","<b>דתרעי דג\"ע אסתימו בלילה</b>: ראה גם לעיל פ' וארא מט, ד. וש\"נ."]]],[2300540863,"הגבלה דקדושה זאת היא בבחי' הפנימי דוקא שהוא מבחי' גילוי שכינה שבהיכל ק\"ק בבהמ\"ק והר הבית עד חומת ירושלים שהוא בחי' מל' שבמל'<sup data-n=\"11425\">705</sup> ושם נעשה הגבלה זה בהיקף של שמירה כנ\"ל, אבל חיצוני' השפע נמשך [מ]ירושלים שלמעלה לכל העולם גם [ל]ע\"ש דנוגה אחר הפסק החומה והוא ביום דוקא, לפי שחסד אל כל היום<sup data-n=\"11426\">706</sup> לכל העולמות הרוחני' העליוני' שיש שם ג\"כ פנימי' וחיצוני' כמלאכים ונשמות [ו]נוגה הנק' חשמ\"ל כו') כמו שהי' נמשך מעשן המערכה של הקרבנות לכל העולם כולו<sup data-n=\"11427\">707</sup>, אך בלילה שנפסק אור החסד ומדה\"ד שליט צריך שמירה לסגור שערי ג\"ע שלא יכנסו זרים כלל כמו שסוגרין היכל המלך ומעמידי' שומרים סביב השערי' כידוע (שז\"[ש] סביב רשעים יתהלכון<sup data-n=\"11428\">708</sup> כו' שבלילה דוקא ילכו רשעים דק\"נ סביב בגניבה למצוא טרף לנפשם ונק' שודדי לילה<sup data-n=\"11429\">709</sup> כו' כמ\"ש במ\"א וד\"ל).\n<b>וזהו</b> ענין החותם שבהוש\"ר<sup data-n=\"11430\">710</sup> דוקא כי הנה ידוע בענין חומ\"ת שזהו אותיות תחום ואותיות חותם<sup data-n=\"11431\">711</sup> והכל ענין א' הוא, והענין הוא כידוע דגם החותם נעשה לשמירה ולהגביל הדבר כמו שחותמים דבר מה בשעוה באותיות החקוקים בחותם טבעת שאז לא יוכל זר ליקח מה שבתוך הכלי (כמו שהי' פך א' שמן<sup data-n=\"11432\">712</sup> חתום בחותמו של כה\"ג שלא נטמא ביד זרים, וכן יין שבחביות שחותמין אותו לבל יגע בו נכרי, וכה\"ג בכל דבר הצרור וחתום הנשלח לשומרו משליטת יד זרים, וכן מה שחותמין המכתב הנשלח כידוע, וכן לענין שליטת המזיקים ושדים שאין להם שליטה בכל מידי דצייר וחתים<sup data-n=\"11433\">713</sup> כו'. וגם הוא ענין הגבלה בדבר שניתן בו מדה שלא יוסיף ולא יגרע חותמין בחותם וכמו שהתחום הוא המגביל מדת הארץ וגבול שבין שדות וכרמים הוא כחומה המגבלת גבול ומדה לעיר כנ\"ל, וע\"כ אותיות א' לחותם עם תחום וחומת כו'). וכ\"ז יובן למעלה בבחי' חותם העליון כמ\"ש חותמו של הקב\"ה אמת<sup data-n=\"11434\">714</sup> שזהו בחי' הגבול ומדה לאור הקדושה שנק' אמת בבחי' הפנימי' שלא ישלטו ולא יקבלו אותם הזרים שאינם ראוים אליה, כמו שחותמין דבר מה לבלי יגע בו איש זר כמו יין הטוב דרזין<sup data-n=\"11435\">716</sup> דאורייתא<sup data-n=\"11436\">715</sup> [נחתם בחותם] שנק'",[["11425","705","<b>חומת ירושלים. . מל' שבמל'</b>: ראה גם מאמרי אדה\"א במדבר שבהערה 701."],["11426","706","<b>שחסד אל כל היום</b>: תהלים נב, ג."],["11427","707","<b>מעשן המערכה. . לכל העולם כולו</b>: ראה גם מאמרי אדה\"א במדבר ח\"ג ע' תתקנא. הנסמן לעיל פ' בא קכז, א הערה 660."],["11428","708","<b>סביב רשעים יתהלכון</b>: תהלים יב, ט."],["11429","709","<b>שודדי לילה</b>: עובדי' א, ה. ראה גם ש\"א פז, א ובהערה 17."],["11430","710","<b>החותם שבהוש\"ר</b>: ראה פע\"ח ומאמרי אדה\"ז שבהערה הבאה. משנת חסידים מסכת ימי מצוה וסוכה פ\"ט, מ\"א. מ\"ב. שע\"ת פג, ג."],["11431","711","<b>חומ\"ת. . תחום. . חותם</b>: ראה פע\"ח (שער הלולב) שכ\"ט, פ\"ד. הנסמן במאמרי אדה\"ז תקס\"ה כאן (ע' תתקצח). סידור שחרית סב, ג. לקמן רמד, ד."],["11432","712","<b>פך א' שמן</b>: שבת כא, ב."],["11433","713","<b>בכל מידי דצייר וחתים</b>: ראה תוד\"ה אלא תענית ח, ב. חולין קה, ב."],["11434","714","<b>חותמו של הקב\"ה אמת</b>: שבת נה, א."],["11435","716","<b>דרזין דאורייתא</b>: נסמן לעיל קסז, א."],["11436","715","<b>יין. . דרזין דאורייתא</b>: נסמן לעיל צו, א הערה 455."]]],[2300540872,"גושפנקא<sup data-n=\"11437\">717</sup> לבל יקבלו החיצונים, וכן כל אוצר דח\"ע וח\"ת דתושב\"כ ותושבע\"פ דכתיב חתום תורה<sup data-n=\"11438\">718</sup> כו'. וזהו שהתורה נק' ג\"כ חומה כמ\"ש אני חומה זו תורה<sup data-n=\"11439\">719</sup> (כמשי\"ת), וכמו חומת ירושלים שלמעלה שמגביל מבחוץ ומבפנים שאין שליטה לחיצונים במידי דצייר וחתים ע\"כ אין מקטרג יוכל לקרב בהיכל דתורה [כ]תרעין דג\"ע דאסתימו בלילה כנ\"ל וד\"ל.\n<b>וזהו</b> ענין החותם שנעשה בהוש\"ר דוקא, שחותם זה הוא כולל ענין הנ\"ל בתחום וחומת וחותם שהכל ענין א' הוא להגביל האור דקדושה [ה]אלקי' הפנימי' ולשמרו משליטת <span data-k=\"pg\">680</span> ּ זרים כחומה המגבלת ומשמרת מה שבתוך גבולה כנ\"ל (והוא בחי' המקיף שנק' שומר<sup data-n=\"11440\">720</sup> כידוע וכמ\"ש על חומותיך ירושלים הפקדתי שומרים כו'), וכחותם הניתן לשמירה כך ניתן חותם העליון בהוש\"ר להגביל אורות [ה]עליונים ולשמרם בבחי' מקיף לבלתי יקרבו זרים שהן ע\"ש דק\"נ כתחום המגביל כו'. והטעם שבהוש\"ר דוקא, הנה ידוע שבחי' חותם הוא שנעשה בנעילה דיו\"כ<sup data-n=\"11441\">721</sup> למעלה מעלה והוא בחי' ההבדלה הפנימי' בין קדש לחול כנ\"ל שהוא הבירור העליון שנק' ספר החיים<sup data-n=\"11442\">722</sup>, כמו שאומרים חתמנו בסה\"ח<sup data-n=\"11443\">723</sup> שצדיקים נכתבים ונחתמים לאלתר לחיים<sup data-n=\"11444\">724</sup> כו' וברשעים א' ימחו מסה\"ח<sup data-n=\"11445\">725</sup> כו' (ומש\"א<sup data-n=\"11446\">726</sup> משה ואם אין מחני נא מספרך אשר כתבת<sup data-n=\"11447\">727</sup> כמ\"ש במ\"א עמ\"ש ובבואה לפני המלך שהוא בר\"ה<sup data-n=\"11448\">728</sup> אז אמר עם הספר<sup data-n=\"11449\">729</sup> כו'). והענין הוא כידוע שבר\"ה הוא שאומרים תקעו<sup data-n=\"11450\">730</sup> בחדש שופר בכסא ליום חגינו כס א'<sup data-n=\"11451\">731</sup> שהוא עליות נש\"י במל' דא\"ס עצמו שנק' מלך הקדוש ובנעילה דיו\"כ נבחרו שם דוקא בקבלת התו\"מ לחיי הנשמות למעלה ולמטה כו'. וזהו כי חק לישראל הוא<sup data-n=\"11452\">732</sup> דוקא שנמשך חוק ומשפט לישראל וליעקב, וזהו ע\"י המשכת י\"ג מדה\"ר דא\"א שהן בחי' מקיפים עליונים שנמשך ביוכ\"פ מבחי' רדכ\"ר ע\"י כה\"ג וע\"י [ה'] עינויים<sup data-n=\"11453\">733</sup> ווידויים<sup data-n=\"11454\">734</sup> [ו]תשובה כו' כמ\"ש כי ביום הזה יכפר עליכם [דוקא] כו' לפני הוי' תטהרו כו'. וזהו בכסא דר\"ה ליום חגינו שהן ז' ימי הסוכות<sup data-n=\"11455\">735</sup> שנק' [יום] חגינו דוקא, שנמשכו המקיפים דז' ימים העליונים בצל הסכך, ולולב ואתרוג נמשך ללב והוא בחי' השמחה שבחג שנמשך",[["11437","717","<b>בחותם] שנק' גושפנקא</b>: ראה תרגום אסתר ג, י. יב. ברכות ו, א. גיטין סח, א."],["11438","718","<b>חתום תורה </b>[ח: ניתוסף: בלימודי]: ישעי' ח, טז."],["11439","719","<b>אני חומה זו תורה</b>: שה\"ש ח, י. פסחים פז, א. ראה לקמן רלה, ד."],["11440","720","<b>המקיף שנק' שומר</b>: ראה לעיל פ' וארא נח, ד. מאמרי אדה\"א נ\"ך ע' ל ובהנסמן שם."],["11441","721","<b>חותם. . בנעילה דיו\"כ</b>: נסמן לעיל קעד, ג."],["11442","722","<b>ספר החיים</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' תב ואילך. ע' תח ואילך וע' תיא. מאמרי אדה\"א נ\"ך ע' תצג. ע' תצו. ע' תצט ואילך. הנסמן לעיל פ' שמות יב, ד הערה 579."],["11443","723","<b>שאומרים חתמנו בסה\"ח</b>: בתפלת נעילה."],["11444","724","<b>שצדיקים. . לאלתר לחיים</b>: ר\"ה טז, ב."],["11445","725","<b>ימחו מסה\"ח </b>[ח: מספר חיים]: תהלים סט, כט."],["11446","726","<b>ומש\"א</b>: דחט: וכמ\"ש."],["11447","727","<b>ואם אין. . כתבת</b>: תשא לב, לב."],["11448","728","<b>ובבואה. . שהוא בר\"ה</b>: ראה גם מאמרי אדה\"א נ\"ך שבהערה 722. מאמרי אדה\"ז תקס\"ה שם."],["11449","729","<b>ובבואה לפני המלך. . אמר עם הספר</b>: אסתר ט, כה."],["11450","730","<b>שבר\"ה הוא שאומרים תקעו</b>: במוסף וקידוש. תהלים פא, ד."],["11451","731","<b>בכסא. . כס א'</b>: ראה ביצה טז, א. שאילתות פ' בא שאילתא מו. יל\"ש ישעי' טז, א (רמז תיט). ירמי' ח, א (רמז, רעח). ת\"ז בהקדמה (טו, ב). מאמרי אדה\"א דברים ח\"ג ע' תשצב. וש\"נ. ח\"ד ע' א'שעד. וש\"נ. שמות ח\"ב ע' תקלד. וש\"נ. נ\"ך ע' תכ. סה\"מ תרל\"ג ס\"ע תקיג ואילך ובשולי הגליון שם."],["11452","732","<b>כי חק לישראל הוא</b>: תהלים פא, ה."],["11453","733","<b>[ה'] עינויים</b>: יומא עג, ב (במשנה)."],["11454","734","<b>[ה']. . ווידויים</b>: ראה גם מאמרי אדה\"א נ\"ך ע' תנא. וש\"נ."],["11455","735","<b>ליום חגינו. . הסוכות</b>: ראה סידור שער ר\"ה רלה, ב. רלו, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380912\" data-slug=\"likkutei-torah\" data-id=\"4001380912\">לקו\"ת נצבים מח, סע\"ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380938\" data-slug=\"likkutei-torah\" data-id=\"4001380938\">ר\"ה נד, רע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381052\" data-slug=\"likkutei-torah\" data-id=\"4001381052\">סוכות פב, א</a>. עט\"ר נז, א. מאמרי אדה\"א דברים ח\"ג ע' תתיא. ע' תתנד. ע' א'ה. ח\"ד ע' א'תקיג."]]],[2300540881,"מיוהכ\"פ. ואמנם מאחר שנמשך [ב]בחי' מקיפים דימי החג ובצל הסכך וכה\"ג אעפ\"י שהן בבחי' מקיפי' להגן כמו ענני כבוד<sup data-n=\"11456\">736</sup> שבמדבר כמ\"ש כי בסוכות הושבתי<sup data-n=\"11457\">737</sup> את בנ\"י כו' כידוע, מ\"מ יכולים גם הזרים לקבל יניקה מזה כידוע שבעת השמחה שבאה [ב]בחי' מקיף יכולים הכל לקבל מפני שנמשך לכל כו'. וזהו ענין ע' פרי החג שמקריבין בז' ימי הסוכות דוקא שנמשך האור והשפע [ה]אלקי' גם לע\"ש<sup data-n=\"11458\">738</sup> דנוגה דעשי' כמ\"ש הללו [את ה'] כל גוים כו' (כמו שיהי' לע\"ל שיהופך אל עמים כו'), והוא לפי שגבר עלינו חסדו<sup data-n=\"11459\">739</sup> חסד [ה]עליון שבמקיפים העליונים שגבר עלינו דוקא והוא ביוכ\"פ שנתגלה למעלה, אך בסוכות הן יורדים למטה וע\"כ יכולים גם החיצונים לקבל מותרות השפע מע' פרי החג שמקריבים בשבילם כו'. אך מטעם זה עצמו צ\"ל בחי' החותם בהו\"ר דוקא, שהוא להגביל ולהבדיל האור הפנימי' מן החיצוני' שלא יוכלו לקבל גם הם<sup data-n=\"11460\">740</sup> משם, וכתיב וכבודי לאחר לא אתן<sup data-n=\"11461\">741</sup> כו' וכמ\"ש ואמת ה'<sup data-n=\"11462\">742</sup> כו' אמיתי' אור ה' דהיינו חוק ומשפט דתו\"מ לישראל דוקא ולא יקרב אליהם זר בש\"ע, שהוא רק בחי' המשכה הפנימי' והעצמי' לבנ\"י לבד ע\"כ מקריבים רק פר א'<sup data-n=\"11463\">743</sup> שזהו לישראל שנק' גוי א' בארץ למהוי אחד באחד כו' כמ\"ש בזהר כמשל האב<sup data-n=\"11464\">744</sup> שעושה סעודה ביחוד לברי' יחידאה כו', (וכידוע דבש\"ע וש\"ת הוא שנמשך [תמצית] השפע הפנימי'<sup data-n=\"11465\">745</sup> דמ\"ד דתו\"מ לנש\"י בשביל חיי הנשמות של כל השנה כו', וע\"כ ניתן החותם בהוש\"ר דוקא בשביל שמירה והגבלה בין הקדש והחול לבלתי יקרב זר <span data-k=\"pg\">שמ</span> ּ לקבל גם הוא וכענין על חומותיך כו' הפקדתי שומרי\"ם כו' כנ\"ל בענין החותם וד\"ל.\n<b>אך</b> הנה מעתה י\"ל מ\"ש פרזות תשב ירושלים כו' בלא היקף חומה ושמירה כלל שסותר לענין הנ\"ל, ואעפ\"י שמבואר למעלה שלע\"ל לא יהי' בחי' מנגד כלל שנצטרך לשמירה כו', אך הלא צ\"ל הבדלה בין הקדש והחול בין פנימי' לחיצוני' עכ\"פ כנ\"ל בענין החותם דהוש\"ר כו' (ועוד הרי היקף החומה הוא למעלה יתירה שהוא בחי' מקיף העליון (כהיקף שמים [ל]ארץ וכה\"ג). וראי' מענין ערי הפרזי לענין קריאת המגילה<sup data-n=\"11466\">746</sup> שקורין רק בי\"ד וכל המוקף חומה מימ[ות] יהושע בן נון קורין שם בט\"ו כו' כמ\"ש הטעם במ\"א). אך הנה ארז\"ל עתידה ירושלים שתתפשט בכל א\"י וא\"י תתפשט בכל העולם כולו, וזהו פלא",[["11456","736","<b>הסוכות. . ענני כבוד</b>: ראה שו\"ע אדה\"ז הל' סוכה סתרכ\"ה. מאמרי אדה\"א דברים ח\"ד ע' א'שסב וע' א'שפג. וש\"נ."],["11457","737","<b>כי בסוכות הושבתי</b>: אמור כג, מג."],["11458","738","<b>ע' פרי החג. . לע\"ש</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תפט. ע' א'שנו. וש\"נ."],["11459","739","<b>שגבר עלינו חסדו</b>: תהלים קיז, ב. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שצז ואילך."],["11460","740","<b>הם</b>: חט: ליתא."],["11461","741","<b>וכבודי לאחר לא אתן</b>: ישעי' מב, ח. מח, יא."],["11462","742","<b>ואמת ה'</b>: המשך הכתוב שגבר עלינו חסדו."],["11463","743","<b>בש\"ע. . פר א'</b>: פינחס לה, לו."],["11464","744","<b>בזהר כמשל האב</b>: ראה זהר נח סד, ב. סוכה נה, ב. מאמרי אדה\"א דברים ח\"ד ע' א'שנו וע' א'תק."],["11465","745","<b>דבש\"ע. . השפע הפנימי'</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'שנה ואילך. וש\"נ."],["11466","746","<b>לענין קריאת המגילה</b>: מגילה ב, א. ראה מאמרי אדה\"א נ\"ך ע' תסג ואילך ובהנסמן בריש המאמר שם."]]],[2300540890,"דבשלמא א\"י שייך בה זה הענין כמו [ש]גם עכשיו נק' ארץ טובה ורחב\"ה<sup data-n=\"11467\">747</sup> וכמו<sup data-n=\"11468\">748</sup> ביעקב ופרצת ימה [וקדמה] וצפונה ונגבה<sup data-n=\"11469\">749</sup> כו' וה[ו]א לע\"ל שתקרא ארץ חפץ<sup data-n=\"11470\">750</sup> כו' שתתפשט בלי שיעור לצפון ודרום מזרח ומערב ונק' נחלה בלי מצרים כידוע בענין נחלת יעקב<sup data-n=\"11471\">751</sup> כו' וד\"ל, אבל ענין התפשטות ירושלים בכל א\"י דעכשיו זהו פלא איך מתפשט עיר א[חת] בישוב גדול כזה משך ת\"פ<sup data-n=\"11472\">752</sup> ויותר. אך י\"ל מארז\"ל ע\"פ גדול ה' ומהולל מאד בעיר אלקינו הר קדשו אימתי גדול<sup data-n=\"11473\">753</sup> ומהולל מאד כשהוא בעיר אלקינו ה\"ק דוקא, וזהו פלא לכאורה למה לא נק' גדול כו' רק בעיר אלקינו דוקא והלא מכה\"כ וממזרח שמש<sup data-n=\"11474\">754</sup> כו', אך הכוונה הוא על מ\"ש גדול ומהולל מאד שהוא בבחי' א\"ס ממש שזהו דוקא בעיר אלקינו. והענין הוא כידוע שבחי' עיר אלקינו זהו בחי' ירושלים של מעלה<sup data-n=\"11475\">755</sup> שהן בחי' צירופי אותיות הקדושים שנמשכו מבחי' המל' שנק' אלקינו, והוא בכלל ק\"ך צירופים דשם אלקים<sup data-n=\"11476\">756</sup> כמ\"ש בס\"י דה' אבנים בונים ק\"ך בתים [כו'] ומתחלקים לצירופי' רבים ושונים כמו עד\"מ שבונים בתים רבים מריבוי האבנים ביותר. כי האותיות נק' אבנים<sup data-n=\"11477\">757</sup> כידוע, וכללות כל האותיות נק' אבן א' גדולה והוא א' ב\"ן<sup data-n=\"11478\">758</sup> כמ\"ש אבן מאסו הבונים<sup data-n=\"11479\">759</sup> כו' ויעקב אמר והאבן הזאת<sup data-n=\"11480\">760</sup> כו' כמ\"ש בזהר ולע\"ל יבנה ירושלים ממנו ונק' אבן הראשה<sup data-n=\"11481\">761</sup> כו', שהוא ענין התפשטות וריבוי הצירופי' דאותיות ושמות העליונים כו' (כמ\"ש לכו חזו מפעלות אלקי'<sup data-n=\"11482\">762</sup> אשר שם שמות בארץ כו') עד אין שיעור וגבול כמ\"ש בס\"י המליך אות ה\"א<sup data-n=\"11483\">763</sup> כו', מכאן ואילך [צא וחשוב<sup data-n=\"11484\">764</sup> כו'] עד אין שיעור כלל ואין קץ כו'. והיינו ריבוי אופני המשכת החיות ואור האלקי בבחי' פנימי' השפע באו\"כ לאין שיעור כלל וכלל, ולא כמו עכשיו שניתן שיעור ומדה וגבול בהמשכת האותיות וצירופים העליונים להוות הנשמות ומלאכים<sup data-n=\"11485\">765</sup> ועולמות עד עוה\"ז השפל בחיצוני' השפע בחי' שם שד\"י<sup data-n=\"11486\">766</sup> הכל עפ\"י מאמר קו המדה כמא' שא' לעולמו די, אבל לע\"ל לא יהי' בחי'<sup data-n=\"11487\">767</sup> שיעור ומדה בצירופי' [בחי' שם הוי'] דאותיות [ה]עליונים בבחי' פנימי' השפע שהוא הנק' ירושלים ש\"מ שהוא בחי' עיר אלקינו הר קדשו דוקא. וע\"כ אמר גדול ה' ומהולל מאד <span data-k=\"pg\">682</span> ּ במלאכים ונשמות שבעיר אלקינו דוקא בבחי' א\"ס ממש, וז\"ש רז\"ל אימתי גדול כו' כשהוא בעיר אלקינו דוקא והיינו לע\"ל דוקא כנ\"ל וד\"ל.",[["11467","747","<b>ארץ טובה ורחב\"ה</b>: שמות ג, ח."],["11468","748","<b>וכמו</b>: חט: וכתיב."],["11469","749","<b>ופרצת. . ונגבה</b>: ויצא כח, יד."],["11470","750","<b>ארץ חפץ</b>: ראה מלאכי ג, יב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670294\" data-slug=\"torat-chaim\" data-id=\"2300670294\">תו\"ח לך פד, ב</a> ובהערה 18."],["11471","751","<b>נחלה בלי מצרים. . נחלת יעקב</b>: ישעי' נח, יד. שבת קיח, סע\"א. ראה מאמרי אדה\"א במדבר ח\"ג ע' א'קח ואילך."],["11472","752","<b>ת\"פ</b>: ט: ת' פרסא."],["11473","753","<b>אימתי גדול</b>: ראה גם לעיל פ' וארא ס, א. וש\"נ."],["11474","754","<b>וממזרח שמש</b>: תהלים קיג, ג."],["11475","755","<b>עיר אלקינו. . ירושלים של מעלה</b>: ראה גם (תרגום ומפרשים עה\"פ). תו\"ח ויצא קעו, א. מאמרי אדה\"א במדבר ח\"ג ע' תתקמח."],["11476","756","<b>ק\"ך צירופים דשם אלקים</b>: נסמן לעיל פ' שמות כ, א."],["11477","757","<b>האותיות נק' אבנים</b>: ראה ס\"י פ\"ד, מי\"ב."],["11478","758","<b>א' ב\"ן</b>: נסמן לעיל פ' בא קטו, ג."],["11479","759","<b>אבן מאסו הבונים</b>: תהלים קיח, כב."],["11480","760","<b>והאבן הזאת</b>: ויצא כח, כב."],["11481","761","<b>אבן הראשה</b>: נסמן לעיל פ' בא קטו, ג."],["11482","762","<b>לכו חזו מפעלות אלקי'</b>: ראה גם לעיל ס, ד. וש\"נ."],["11483","763","<b>המליך אות ה\"א</b>: ס\"י פ\"ה, מ\"ב."],["11484","764","<b>מכאן ואילך [צא וחשוב</b>: ס\"י פ\"ד, מי\"ב."],["11485","765","<b>להוות הנשמות ומלאכים</b>: דחט: להיות מלאכים ונשמות."],["11486","766","<b>בחי' שם שד\"י</b>: שם: ליתא."],["11487","767","<b>בחי'</b>: שם: ליתא."]]],[2300540899,"<b>אך</b> י\"ל [מ]היכן יהי' הכח הריבוי הזה לאין שיעור כלל באותיות וצירופי' עליונים שהן באים בבחי' מדה והתחלקות במדה ושיעור ע\"פ ה\"ג מנצפ\"ך<sup data-n=\"11488\">768</sup> דבינה שמחלקת אותיות המח' וכמו\"כ באותיות הדבור, וכידוע דאבא יסד ברתא<sup data-n=\"11489\">769</sup> שאותיות הדבור נמשכים מן החכ' שבראש שיש לה שיעור וגבול בעצם וממילא נגבלו במח' ובדיבור כו', וא\"כ איך יתרבו הצירופי' דאותיות שנק' אבנים מאבן א' שהוא א' ב\"ן דחכ' הכללית שאין בפרט אלא מה שבכלל כידוע כו'. אך הענין הוא<sup data-n=\"11490\">770</sup> ממ\"ש והנצח זו בנין ירושלים כנ\"ל שבנין ירושלים דלע\"ל יהי' נצחי בזמן בלי הפסק כלל, והיינו לפי שבחי' מלכות דוד ומשיח לע\"ל יהי' ג\"כ נצחי כמ\"ש להכין אותה כו' מעתה ועד עולם<sup data-n=\"11491\">771</sup> כמ\"ש דוד מלך ישראל חי וקיים, וכידוע במ\"ש חיים נתת לו בבחי' חיים נצחי' דא\"ס ממש, לפי שיאיר בו מבחי' מל' דא\"ס עצמו שע\"ז אמר ה' ימלוך לע\"ו בחי'<sup data-n=\"11492\">772</sup> עולם הנצחי ממש. ואעפ\"י שעכשיו הרי בא אור אלקי' בבחי' מל' דאצי' בבי\"ע בהגבלה דזמן עבר הוה עתיד מלך מלך ימלוך<sup data-n=\"11493\">773</sup> והן וא\"ש דהוי עלמא<sup data-n=\"11494\">774</sup> כידוע דעיקר הגבול דזמן הוא במל'<sup data-n=\"11495\">775</sup> דוקא, אך ידוע שיאיר מעצמות אוא\"ס שלמעלה גם ממקום וזמן<sup data-n=\"11496\">776</sup> בבחי' הזמן דמל' דוקא ע\"כ גם בחי' התחלקות הזמן יהי' נצחי בלי הפסק כלל שנק' חיי עולם כנ\"ל וד\"ל. ומזה יובן ג\"כ בענין ריבוי הצירופי' דמל' בבחי' בנין ירושלים ש\"מ שנק' עיר אלקינו שיהי' לע\"ל בלי שיעור וגבול כלל, כי יאיר באותיות הדבור מלמעלה ממקור התחלקות המדות והחו\"ב שמאירים באותיות הדיבור עכשיו בגבול וע\"כ יהי' בבחי' אותיות בלי גבול, והוא ענין הריבוי של התפשטות הבתים בעיר אלקינו למעלה וכך יהי' למטה בירושלים ש\"מ<sup data-n=\"11497\">777</sup>. ואעפ\"י שאין בפרט אלא מה שבכלל, זהו כשאותיות הדיבור מקבלים מחו\"ב דוקא. משא\"כ לע\"ל נא' אב\"ן מאסו הבונים שהן חו\"ב<sup data-n=\"11498\">778</sup>, היתה כו' שתעלה למעלה מעלה מחו\"ב, וגם למעלה מן הכת\"ר שנק' רצון ותענוג שבחו\"ב שמקבל גם הוא כו' והוא מעצמות המאציל בבחי' עצמות התענוג ורצה\"פ שלמעלה מע\"ס דכח\"ב וחג\"ת כו') שהוא בחי' הנצח דוקא כנ\"ל וד\"ל. וראי' לד\"ז<sup data-n=\"11499\">779</sup> ממה שיהי' גם מספר בנ\"י לע\"ל כחול הים שלא ימד ולא יספר כלל כמ\"ש והי' מספר בנ\"י<sup data-n=\"11500\">780</sup> כו', ואעפ\"י שבמספר יש גבול ושיעור בהכרח אבל מאחר שיאיר [ב]מספר עצמו מלמעלה מן המספר, ע\"כ גם המספר יהי' בלי גבול כלל כנ\"ל בענין נצחי' דהתחלקות הזמן כו' כמ\"ש במ\"א.",[["11488","768","<b>ה\"ג מנצפ\"ך</b>: נסמן לעיל קמד, ג."],["11489","769","<b>דאבא יסד ברתא</b>: נסמן לעיל פ' שמות מז, ב."],["11490","770","<b>הוא</b>: חט: יובן."],["11491","771","<b>להכין אותה. . עולם</b>: ישעי' ט, ו."],["11492","772","<b>בחי'</b>: ד: בחיי. ח: בחיים."],["11493","773","<b>מלך מלך ימלוך</b>: ראה זהר בראשית לד, א."],["11494","774","<b>וא\"ש דהוי עלמא</b>: ר\"ה לא, א. ראה הנסמן במאמרי אדה\"א בראשית ע' נג."],["11495","775","<b>דזמן הוא במל'</b>: ראה שער היחוה\"א פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"א ע' קלה. ח\"ג ע' תשצד. לקמן רמב, ד."],["11496","776","<b>ממקום וזמן</b>: חט: ממקור הזמן."],["11497","777","<b>ש\"מ</b>: שם: ליתא."],["11498","778","<b>הבונים שהן חו\"ב</b>: ראה גם לקמן פ' ויקהל תב, ד. מאמרי אדה\"ז תקס\"ה ח\"א ע' קלב. מאמרי אדה\"א בראשית ע' שנט. שמות ח\"א ע' צב. במדבר ח\"ג ר\"ע א'מח. ע' א'סא. תו\"ח ויצא קסד, ב."],["11499","779","<b>לד\"ז</b>: ח: לדבר זה."],["11500","780","<b>והי' מספר בנ\"י</b>: הושע ב, א. ראה מאמרי אדה\"א במדבר ח\"א ע' קיג ואילך ובהנסמן בריש המאמר שם. דברים ח\"ג ע' תתכב."]]],[2300540906,"<b>והוא</b> כאשר ישראל עושין רש\"מ שלמעלה מן החכ' בחי' כשב\"כ<sup data-n=\"11501\">781</sup> כנ\"ל, שיעלו למעלה משרשם במדות דז\"א שמקבלים מאו\"א דאצי', אלא בעצמות א\"ס ממש שלמעלה מהחכ' ומדות דאצי', שע\"ז א' לפני אחד מה אתה סופר<sup data-n=\"11502\">782</sup> דלאו דאית בי' מכא\"מ כלל שיוכל להאציל עד אין שיעור כנ\"ל בענין אוצרות עליונים כנ\"ל וד\"ל.\n<b>וז\"ש</b> עתידה ירושלים שתתפשט <span data-k=\"pg\">שמא</span> ּ בכל א\"י כו' להיות ידוע בענין עש\"נ<sup data-n=\"11503\">783</sup> דהכל כא' בא, דאם בחי' הזמן שנק' שנה והאור והחיות דאותיות אלקים באים בבחי' שיעור וגבול, גם בחי' המקום שהוא שטח העולם בו\"ק כו' שנק' עולם גם הוא בא בבחי' גבול ומדה, כמו אתה הצבת כל גבולות ארץ<sup data-n=\"11504\">784</sup> צפון וימין אתה בראתם<sup data-n=\"11505\">785</sup> כו'. אבל אם בחי' שנה ונ[פש] הן בלי גבול ומדה כלל כנ\"ל בענין וע\"ד<sup data-n=\"11506\">786</sup> כו' אז גם בחי' המקום שנק' עולם בלתי מוגבל שתתפשט בלי שיעור וגבול כלל, שהרי אמר לעולמו די לפי שהי' מתפשט בלי שיעור וגבול דצו\"ד<sup data-n=\"11507\">787</sup> כו' (מאחר שכח הפב\"נ<sup data-n=\"11508\">788</sup> גם הנפעל ממנו בלתי מוגבל). וכידוע במה שאמרו הוא מקומו ש\"ע<sup data-n=\"11509\">789</sup> בגדר הגבלה דו\"ק כו' אבל אין העולם מקומו, וע\"ז<sup data-n=\"11510\">790</sup> א' ברוך המקום<sup data-n=\"11511\">791</sup> כו' שמתצמצם בבחי' מקום, כי אור עצמות אלקות אינו נתפס בבחי' מקום וגבול, כי גם השמים ושה\"ש שהן בבחי' מקיפים לא יכלכלוהו<sup data-n=\"11512\">792</sup> כו'. וז\"ש הנה מקום אתי<sup data-n=\"11513\">793</sup> שמקומו העצמי הוא בלתי מוגבל כלל, ולכך אמר ברוך כו' ממקומו<sup data-n=\"11514\">794</sup> דוקא כידוע. אך עכ\"ז הרי בק\"ש עיקר היחו\"ע [הוא שתמליכוהו] בשו\"א וד' רוחות<sup data-n=\"11515\">795</sup> העולם כו' שהוא בגדר מקום ו\"ק מעלה ומטה כו', והיינו שיומשך מלמעלה מבחי' המקום דעולם להיות מלך העולם, וזהו תמליכהו שזהו הוי' אחד שהוא היחו\"ע [ד]מדות דאצי' בבחי' מקיף דו\"ק דמעלה ומטה כו' בהתכללות די\"ב ג\"א<sup data-n=\"11516\">796</sup> כו', שבא גם הוא במדה בהיקף המוגבל בד' רוחות דשו\"א כו'. והיינו אחר הביטול דו\"ק וחו\"ב במאציל עצמו כו' ואח\"כ בשכמל\"ו<sup data-n=\"11517\">797</sup> בבחי' ממלא דהיינו הצמצום דעש\"נ בתוך הנבראים מאין ליש ממש כידוע שהוא בג' עולמות דבי\"ע (כמו ענין השמים ושה\"ש למעלה מעלה שזה בטה\"ע וטה\"ת והוא מה ששיער בעצמו בכח מה שעתיד להיות בפועל שגם המקיף הכללי מוגבל בהגבלה דו\"ק למטה בשו\"א וד' רוחות כו', אבל לע\"ל יתגלה בחי' מל' דא\"ס שנק' מלך יחיד<sup data-n=\"11518\">798</sup> לבדו מלך הקדוש כמו שהוא קודם צמצום הראשון ששיער בעצמו כו' דגם שה\"ש",[["11501","781","<b>כשב\"כ</b>: ח: כתר שבכתר."],["11502","782","<b>לפני אחד מה אתה סופר</b>: נסמן לעיל פ' שמות יז, ב."],["11503","783","<b>עש\"נ</b>: ח: עולם שנה נפש — נסמן לעיל פ' וארא נג, ב."],["11504","784","<b>אתה הצבת כל גבולות ארץ</b>: תהלים עד, יז."],["11505","785","<b>צפון וימין אתה בראתם</b>: שם פט, ג."],["11506","786","<b>כנ\"ל בענין וע\"ד</b>: לע\"ע לא נתברר לאיזה מאמר כוונתו."],["11507","787","<b>דצו\"ד</b>: חט: לצפון ודרום."],["11508","788","<b>שכח הפב\"נ </b>[ט: הפועל בנפעל]: נסמן לעיל פ' וארא עה, א."],["11509","789","<b>הוא מקומו ש\"ע</b>: נסמן לעיל קנ, ד."],["11510","790","<b>וע\"ז</b>: דחט: וע\"כ."],["11511","791","<b>ברוך המקום</b>: מדות ספ\"ה. הגש\"פ (פיסקא זו). ראה גם לקמן פ' תצוה שנא, ד."],["11512","792","<b>השמים ושה\"ש. . לא יכלכלוהו</b>: מל\"א ח, כז. ועד\"ז דהי\"ב ו, יח [ושם: יכלכלוך — ראה לקמן פ' פקודי תנב, ב. מאמרי אדה\"א בראשית ע' קנח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680383\" data-slug=\"torat-chaim\" data-id=\"2300680383\">תו\"ח מקץ רכב, א</a> הערה 11]."],["11513","793","<b>הנה מקום אתי</b>: תשא לג, כא."],["11514","794","<b>ברוך כו' ממקומו</b>: יחזקאל ג, יב."],["11515","795","<b>שתמליכוהו] בשו\"א וד' רוחות</b>: נסמן לעיל פ' וארא עה, ד."],["11516","796","<b>די\"ב ג\"א</b>: נסמן לעיל פ' בא קכז, ד."],["11517","797","<b>בשכמל\"ו</b>: פסחים נו, א."],["11518","798","<b>מלך יחיד</b>: נוסח ברכת ישתבח."]]],[2300540913,"לא כו' ששם הוא בחי' מקומו העצמי שאין העולם בכללות מקומו כלל והוא מ\"ש אנת הוא חד ולא בחושבן י\"ס כלל דלפני אחד כו', דיחוד ע\"ס בנאצלים<sup data-n=\"11519\">799</sup> נק' אחד המנוי<sup data-n=\"11520\">800</sup> וכיחוד המדות בחכ' באדם באו\"כ כו', אבל יחוד העצמי הוא למעלה מיחוד והתכללו' דע\"ס ונק' אחה\"פ בתכלית כו' (שלמעלה גם מבחי' אדם דתו\"מ) כידוע ששם לא שייך לומר גם ענין חיבור מעלה ומטה כו', מאחר שהוא למעלה מבחי' מקיף בכלל שאין בו אף בחי' מו\"מ<sup data-n=\"11521\">801</sup> כלל וד\"ל).\n<b>וזהו</b> פרזות תשב ירושלים כו', דהנה היקף החומה לירושלים אעפ\"י שיש בזה מעלה להגביל אור הקדושה הפנימי' וגם להגן מן המנגד כו', זהו דוקא כשיש מנגד ויש קצבה וגבול לאור ושפע הפנימי' כמו שהי' בבנין ירושלים בב\"ר ובב\"ש, לפי שהי' שרש ענין דגילוי שכינה בהיכל ק\"ק ג\"כ במדה ושיעור שצמצם א\"ע במקום וגבול בארון ולוחות וכה\"ג, לפי שזהו ביחו\"ע בע\"ס דאצי' שבחכ' וכתר שבא במדה כמו בבחי' אדם בתו\"מ כדי לברר לז\"מ דתהו שהי' שם השבירה<sup data-n=\"11522\">802</sup> בבחי' ס\"ג<sup data-n=\"11523\">803</sup> כידוע ובחכ' דוקא אתברירו<sup data-n=\"11524\">804</sup> בבחי' יחוד והתכללות דאדם דתיקון (וע\"כ <span data-k=\"pg\">684</span> ּ יש קץ וגבול לאור הקדושה הפנימי' להבדיל מן החיצוני' כנ\"ל וצריך מקיף לשמירה והוא בחי' החותם ותחום וחומת הנ\"ל). אבל לע\"ל יהי' בחי' גילוי אור העצמו' דא\"ס בבהמ\"ק וירושלים דלע\"ל (שלמעלה מהגבלה דו\"ק מעלה ומטה כנ\"ל בבחי' עש\"נ שיתפשט בלי מדה (וגם התו\"מ יהי' בלי גבול כתוה\"ק<sup data-n=\"11525\">805</sup> שאמר בה ארוכה מארץ מדה<sup data-n=\"11526\">806</sup> כו') למעלה מבחי' קו המדה מטעם הנ\"ל ע\"כ לא יהי' בחי' מקיף כלל, כי בחי' הפנימי' דאור הקדושה [י]תפשט אז בבחי' בלי גבול כלל ולא יבא לכלל הגבלה להגביל בין פנימי' לחיצוני' ולז\"א<sup data-n=\"11527\">807</sup> פרזות תשב כו', כי המקיף<sup data-n=\"11528\">808</sup> החומה מגביל ליושביה שלא יתפשטו יותר וכמו המקיף הכללי שמגביל לכל העולמות מבחוץ כו', ובאמת גם שה\"ש כו' שאין העולם מקומו כלל כנ\"ל וזה[ו] שתתפשט ירושלים ביש[ו]בה בכל א\"י דעכשיו שהוא ת\"פ (כמו געה\"ת שגדול כא\"י ונק' ירושלים ש\"מ כו'). אך א\"כ גם העולם יתפשט בלי שיעור מטעם הנ\"ל כמו שהי' קודם שאמר לעולמו די כו' כנ\"ל, רק שעכ\"ז יהי' הבדל בין פנימי' לחיצוני'. כי גם לע\"ל יהי' עליות המדריגו' שתתפשט קדושת ירושלים על א\"י וא\"י על כל העולם אבל יהי' התפשטות של א\"י כמו כל העולם דעכשיו בד' רוחות המוגבל (שהרי אליהו טס זה העולם בד' פריחות<sup data-n=\"11529\">809</sup> עכ\"פ כו'), וקדושת ירושלים תהי'",[["11519","799","<b>בנאצלים</b>: דח: במאציל."],["11520","800","<b>אחד המנוי</b>: ראה חובת הלבבות שער היחוד פ\"ח. פרדס (שער עצמות וכלים) ש\"ד, פ\"ה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670250\" data-slug=\"torat-chaim\" data-id=\"2300670250\">תו\"ח נח סז, א</a> ובהערה 1."],["11521","801","<b>מו\"מ</b>: חט: מעלה ומטה."],["11522","802","<b>דתהו שהי' שם השבירה</b>: ראה ע\"ח (שער דרושי הנקודות) ש\"ח, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670078\" data-slug=\"torat-chaim\" data-id=\"2300670078\">תו\"ח נח סד, ב</a> הערה 10."],["11523","803","<b>השבירה בבחי' ס\"ג</b>: נסמן לעיל פ' וארא פה, ג."],["11524","804","<b>ובחכ'. . אתברירו</b>: נסמן לעיל י, ג."],["11525","805","<b>כתוה\"ק</b>: ח: בתורה הקדומה."],["11526","806","<b>ארוכה מארץ מדה</b>: ראה גם לעיל קעג, ב. וש\"נ."],["11527","807","<b>ולז\"א</b>: דחט: ולזאת."],["11528","808","<b>המקיף</b>: שם: היקף."],["11529","809","<b>אליהו. . בד' פריחות</b>: ברכות ד, סע\"ב."]]],[2300540920,"שתתפשט כמו כל א\"י למעלה מקדושת א\"י, וקדושת א\"י לע\"ל למעלה משאר העולם. אבל יהי' בבחי' בלתי מוגבל ומדה בדו\"צ ומזרח ומערב כו' כי גם בחי' המקום הגשמי יתפשט בלי גבול כלל בחיצוניות שהרי אמר צפון וימין אתה בראתם כו', וא\"כ הרי יהי' גם לע\"ל הגבלה בין פנימי' לחיצוני' רק שיהי' במדה גדולה מפני שיתברר אז מכל ע\"ש דק\"נ שהרי א' יצב גבולות עמים<sup data-n=\"11530\">810</sup> למספר בנ\"י, ולע\"ל יהי' בחי' גילוי אלקות גם על כל העמים כמ\"ש אז אהפוך אל עמים שפה ברורה כי רוח הטומאה יעביר מן הארץ. אך עכ\"ז [יהי'] בנ\"י בבחי' פנימי' ואוה\"ע בבחי' חיצוני' וכמ\"ש ועמדו זרים ורעו צאנכם<sup data-n=\"11531\">811</sup> כו' וכתי' כל הנותר בציון<sup data-n=\"11532\">812</sup> קדוש יאמר לו כמאמר עתידים צדיקי' שיאמרו לפניהם קדוש<sup data-n=\"11533\">813</sup> כו'. ומפני שבירור זה יהי' למעלה מבחי' גבול ומדה דבחי' התיקון דשם מ\"ה דאדם ע\"כ יהי' בבלתי גבול ומדה בין בפנימי' ובין בחיצוניות דנש\"י נבדל ביניהם ולא ע\"י חומה כלל (אלא כמ\"ש ואני אהי' לה חומת אש סביב<sup data-n=\"11534\">814</sup> (כמשי\"ת) וד\"ל).\n<b>ובכ\"ז</b> יובן שרש ענין שמ\"ע וש\"ת בב' אופנים, הא' כנ\"ל בבחי' החותם דהו\"ר שהוא גמר של החותם דיוכ\"פ בנעילה שהוא רק להבדיל הפנימי' מן החיצוני' כמ\"ש יבחר לנו את נחלתינו<sup data-n=\"11535\">815</sup> כו', בבחירה עליונה שלמעלה מן הרצון וחכ' כנ\"ל בענין הגורלות דיוכ\"פ<sup data-n=\"11536\">816</sup> כו'. והוא ע\"י בחי' העליות דנש\"י [בתשובה שלימה בר\"ה עד עומק כל העומקים שנק' סדכ\"ס כו' שזהו בכס\"א כס א'] בפנימי' הכתר, והוא בחי' חשמ\"ל העליון דישת חשך סתרו כעיגול הסמך [ש]מקיף ומלביש לאור העצמו' ממש שנק' ערפל או כ\"ע<sup data-n=\"11537\">817</sup>, וביו\"כ הוא שמתלבש בענן הקטרת שנברר מי\"א סממני' שהן היפך הרע די\"א ארורים<sup data-n=\"11538\">818</sup> שנהפך עי\"ז חשך העליון לאור. וז\"ש כי בענ\"ן זה דוקא אראה על<sup data-n=\"11539\">819</sup> כו' וממנו <span data-k=\"pg\">שמב</span> ּ נמשך כללות<sup data-n=\"11540\">820</sup> המקיפים בסוכות כנ\"ל שנק' מקיפים דא\"י<sup data-n=\"11541\">821</sup> והוא מ\"ם מרובע כידוע בענין מ\"ם וסמ\"ך דאפרסמו\"ן<sup data-n=\"11542\">822</sup> וזהו ה' צלך<sup data-n=\"11543\">823</sup> כו', וזהו בכס\"א ליום חגינ\"ו כו'. ובהו\"ר נחתם אור המקיפים שלא ילך לע\"ש רק בחי' החיצוני' כמו בע' פרי החג כנ\"ל ובשמ\"ע נקלט אור הפנימי' בנש\"י לבד כמ\"ש כי חק לישראל הוא דוקא כנ\"ל. וכ\"ז הוא רק בבחי' הבירורי' דז\"מ דתהו ששרשן בצמצום הראשון דחשך העליון וע\"י תשובה ומע\"ט נבררו ונהפך חשך העליון לאור כידוע, ועי\"ז יורד ונמשך בחי' החסדים דמקיפים דאו\"י בסוכות",[["11530","810","<b>יצב גבולות עמים</b>: האזינו לב, ח."],["11531","811","<b>ועמדו זרים ורעו צאנכם</b>: ישעי' סא, ה."],["11532","812","<b>כל הנותר בציון </b>[ט: בירושלים]: ישעי' ד, ג [ושם: והי' הנשאר בציון והנותר בירושלים — ראה לעיל רכח, ג. לקמן פ' תצוה של, ג [ושם: בציון כו' קדוש]. מאמרי אדה\"א דברים ח\"ד ע' א'שצח־ נ\"ך ע' שצו ובהנסמן בהנ\"ל]."],["11533","813","<b>עתידים צדיקי' שיאמרו לפניהם קדוש</b>: ראה ב\"ב עה, ב."],["11534","814","<b>ואני אהי' לה חומת אש סביב</b>: נסמן לקמן הערה 847."],["11535","815","<b>יבחר לנו את נחלתינו</b>: תהלים מז, ה."],["11536","816","<b>כנ\"ל בענין הגורלות דיוכ\"פ</b>: לע\"ע לא נתברר לאיזה מאמר כוונתו — ראה גם מאמרי אדה\"א נ\"ך ע' שסז ואילך. וש\"נ."],["11537","817","<b>כ\"ע</b>: כתר עליון. דחט: סת\"ר עליון."],["11538","818","<b>מי\"א סממני'. . די\"א ארורים</b>: נסמן לעיל פ' שמות ח, ג."],["11539","819","<b>כי בענ\"ן. . אראה על</b>: אחרי טז, ב."],["11540","820","<b>כללות</b>: חט: בחי'."],["11541","821","<b>דא\"י</b>: דח: דאימא."],["11542","822","<b>מ\"ם וסמ\"ך דאפרסמו\"ן</b>: ראה זהר תרומה קכז, א ואילך. מאמרי אדה\"ז תקס\"ב ח\"א ע' קנז ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'רכח. וש\"נ."],["11543","823","<b>ה' צלך</b>: תהלים קכא, ה."]]],[2300540927,"וש\"ע מלמעלה למטה כנ\"ל, דלפי\"ז יש בכ\"ז ענין עליות וירידות עכ\"פ כמו בקוין שבתוך עיגול הגדול שעולים בו עד עליונו של עיגול ואח\"כ יורדים בו למטה מטה כו', שזהו עליות דנש\"י בר\"ה עד מקור כל המקיפים בטה\"ע וביו\"כ וסוכות הוא עצמו נמשך למטה מטה כנ\"ל.\n<b>אבל</b> אופן הב' בענין ש\"ע וש\"ת הוא כמו שיהי' לע\"ל בימוהמ\"ש ותח\"ה ועוה\"ב שלא יהי' בחי' עלי[ו]' ויריד[ות] כלל כנ\"ל, מצד ש[י]הי' התגלות אור העצמי דא\"ס ב\"ה למטה ממש כמו שהוא קודם הצמצום בקו\"ח כו' שלמעלה ממקור דע\"ס שאין בו בחי' מעומ\"ט כלל אף לא בבחי' כלל ופרט כמו בחי' טה\"ע שנק' שה\"ש כו', לפי שהוא אור עצמותו ממש מפני זה נמצא למטה כמו למעלה ממש בשוה, וא\"כ לא יתכן שם ענין עליות וירידות כלל וכמ\"ש הנה אלקינו זה לנוכח כו'. וע\"כ גם בזמן ומקום יהי' בלי גבול כלל כמבואר למעלה שזהו ענין והנצח זו בנין ירושלים בבחי' נצחיות דזמן ופרזות תשב ירושלים שתתפשט במקום בלי גבול כלל, וגם לפי שלא יהי' בחי' מנגד כלל לפי שיהופך אל עמים כו' ע\"כ א\"צ לחומה ושמירה כלל כו', רק שא\"כ לא יהי' לע\"ל בחי' חותם כלל והרי מ\"ש יבחר לנו את נחלתינו קאי לע\"ל דוקא דכל העמים תקעו כף כו'. אמנם מבואר למעלה שגם לע\"ל יהי' הבדלה בין פנימי' לחיצוני' שגם קדושת א\"י תהי' למעלה משאר הארץ כו' זהו יבחר לנו כו', אך לא יהי' הבדלה זאת בשביל שמירה שיצטרך לחומה כמ\"ש פרזות תשב כו', ומרומז בזה שלא יבא האור העליון בדרך השתל' עו\"ע מקיף ופנימי כלל, כי גם בחי' סדכ\"ס יתגלה למטה ממש כמו שהוא למעלה שזהו בחי' [ד\"ע] שהוא מיש ליש בלי ממוצע כלל דהיינו העצמי<sup data-n=\"11544\">824</sup> בחי' יש האמיתי יתגלה למטה בבחי' יש גמור כמ\"ש להנחיל אוהבי יש אמיתי בלי ביטול מאין ליש כמו שהי' במשה כו'. וראי' לזה ממה שישפוך רוחו על כל בשר כו' (שנק' צדקת פרזונו כנ\"ל שזהו בזבוז האוצרות חיים העליונים דסדכ\"ס כו' וכמשי\"ת בסמוך). וגם ראי' ממה שהארץ תוציא צמחה וכל מזון ולחם מכח עצמה בלי זריעה וגשמים כלל כמאמר שתוציא גלוסקאות<sup data-n=\"11545\">825</sup> כו' ונק' לחם פנג<sup data-n=\"11546\">826</sup> כו' כמו בחריש ובקציר תשבות<sup data-n=\"11547\">827</sup> כו' (והוא בעוה\"ב דוקא שנק' ארץ החיים<sup data-n=\"11548\">828</sup> ארץ חפץ כו'. וז\"ש ושבתה הארץ<sup data-n=\"11549\">829</sup> כו' באלף הז' כו'. אבל בימוהמ\"ש יזרעו הארץ ויקצרו כמו ועמדו זרים כו' רק שתטהר מכל סיג כמו קודם החטא ולא כמו בגעה\"ת וכה\"ג). וזהו אהי' כטל<sup data-n=\"11550\">830</sup> [לישראל] כו' וכן אמר והי' כו' אשר לא יקוה לאיש<sup data-n=\"11551\">831</sup> שלא תצטרך הארץ למשפיע דלא כעכשיו דמ\"ה <span data-k=\"pg\">686</span> ּ מברר לב\"ן כו' כמ\"ש במ\"א",[["11544","824","<b>העצמי</b>: דח: שמרחב העצמי. ט: שאור העצמי."],["11545","825","<b>שתוציא גלוסקאות</b>: ראה גם לעיל פ' שמות כג, ב. וש\"נ."],["11546","826","<b>לחם פנג</b>: נסמן לעיל שם."],["11547","827","<b>בחריש ובקציר תשבות</b>: נסמן לעיל קנט, ג."],["11548","828","<b>ארץ החיים</b>: ראה גם הנסמן לעיל פ' שמות ז, א."],["11549","829","<b>ושבתה הארץ</b>: בהר כה, ב. ראה גם לעיל רטו, ד. לקמן פ' משפטים רצב, ד."],["11550","830","<b>אהי' כטל [לישראל]</b>: הושע יד, ו."],["11551","831","<b>והי'. . לאיש</b>: מיכה ה, ו. ראה גם לעיל פ' שמות טז, ג."]]],[2300540934,"(ולא כמ\"ת דהתגלות אנכי לבנ\"י הי' בבחי' החכ' דתיקון פב\"פ כו', ולא כמשל ב' חצאי כדורים<sup data-n=\"11552\">832</sup> חצי כדור העליון הולך מן המיצר אל המרחב וחצי כדור התחתון הולך ג\"כ מן המיצר אל המרחב ומתחברים יחד באמצעיתן כמו מן המיצר קראתי י\"ה ענני במרחב י\"ה כמ\"ש במ\"א, אבל לע\"ל יתגלה ממרחב העצמי שנק' יש מקורא דכולא<sup data-n=\"11553\">833</sup> במרחב דכנ\"י שנק' ארץ טובה ורחבה שהוא ארץ החיים דעוה\"ב כו' שזהו בבחי' יש מיש וע\"כ יחי[ו] חיי עולם מחיי החיים העצמי' בלי ממוצע כלל וד\"ל).\n<b>ולפ\"ז</b> יובן באופן הב' בשרש ש\"ע וש\"ת לע\"ל שיהי' בבחי' שמחה גדולה שנק' שמחת עולם מצד גילוי עצמיות אור הא\"ס כנ\"ל, וזהו והנצח זו בנין ירושלים דלע\"ל בלא היקף חומה עם שומרים כלל (וינטל החותם דהו\"ר הנ\"ל רק בבחי' הבדלה בעלמא כנ\"ל למעלה הרבה משמחה דש\"ע וש\"ת עכשיו שהוא בבחי' המשכה דמשפיע במקבל בבחי' מ\"ד ומ\"נ עכ\"פ שהוא בגבול ומדה דאדם דתו\"מ כנ\"ל). ושרש הענין והטעם לזה יובן עפ\"י משל הנ\"ל בנצחון מלחמה ש[מ]בזבז האוצרות בשביל הניצוח הנ\"ל שאין זה רק קודם גמר הניצוח ש[מ]פזר כל הון לאיבוד לזרים, ולמעלה היינו גילוי ההעלם דסדכ\"ס כמו ביוכ\"פ בפנימי' כנ\"ל וגם במקיפי' דסוכות עד החיצוני' בסוכות בע' פרי החג כנ\"ל עד<sup data-n=\"11554\">834</sup> שנצרך לחותם כו'. אבל לאחר גמר הניצוח מלחמה כאשר כבר כבש למנגדו בתכלית שאין צריך עוד לבזבז אוצרות כלל, הרי אז עושה המלך משתה וסעודה גדולה לכל שריו ועבדיו<sup data-n=\"11555\">835</sup> הפרתמים רואי פני המלך ולכל העם בחצר החיצונה ומנגנין לפני המלך בכל כלי שיר בשמחה גדולה לאין שיעור כלל כו', ששמחה זו היא כפ\"ע<sup data-n=\"11556\">836</sup> שמחת המלך בעצמו יותר מכל התענוגי' היקרים שהרי בזבז אוצרות היקרים רק בשביל הניצוח כו'. וכך יובן למעלה בבנין ירושלים דלע\"ל שתהי' בש\"ע<sup data-n=\"11557\">837</sup> לאין שיעור כלל (כמו המשתה וסעודה שיעשה לצדיקים לע\"ל בתחה\"מ בלויתן ושור הבר ויין המשומר ודוד יברך על הכוס<sup data-n=\"11558\">838</sup> כו'), כי מל' דרקיע במל' דא\"ס שיתגלה לע\"ל בזמן ומקום למטה כמו למעלה זהו כמדת מל' דארעא<sup data-n=\"11559\">839</sup> שבגמר הניצוח שלו דוקא ישמח בסעודה ומשתה כו' (וכמו ינאי המלך שכבש ס' כרכים<sup data-n=\"11560\">840</sup> ועשה משתה גדולה כו' וכה\"ג). וזהו יהי' בש\"ע דוקא שמיוחד לבנ\"י שאמר בהם אם הבנים שמחה<sup data-n=\"11561\">841</sup> והיינו בקיבוץ גליות לירושלים שזהו שוש תשיש<sup data-n=\"11562\">842</sup> כו' בקיבוץ בניה לתוכה בשמחה וד\"ל, ואע\"פ שעכשיו נק' עצרת (ענין כניסה ואסיפה ג\"כ אבל הוא בא בגבול ומדה בבחי' חותם דהוש\"ר כנ\"ל שז\"ש לכ\"ם<sup data-n=\"11563\">843</sup> דייקא כו', אבל לע\"ל עצרת ואסיפה כנ\"ל<sup data-n=\"11564\">844</sup> זו היא בקיבוץ כל הגליות שבתוכה בשמחת עולם הנצחי",[["11552","832","<b>כמשל ב' חצאי כדורים</b>: ראה מאמרי אדה\"ז כתובים ח\"א ע' קב. דרך חיים לד, ג. לח, ד. עט\"ר כד, א. מאמרי אדה\"א קונטרסים ע' שה. וש\"נ."],["11553","833","<b>מקורא דכולא</b>: זהר בראשית לג, א."],["11554","834","<b>עד</b>: חט: ליתא."],["11555","835","<b>ועבדיו</b>: שם: ליתא."],["11556","836","<b>כפ\"ע</b>: ח: כפי ערך."],["11557","837","<b>בש\"ע</b>: חט: בשמחת עולם."],["11558","838","<b>ודוד יברך על הכוס</b>: נסמן לעיל קסא, א."],["11559","839","<b>מל' דרקיע. . כמדת מל' דארעא</b>: ראה ברכות נח, א."],["11560","840","<b>ינאי המלך שכבש ס' כרכים</b>: קדושין סו, א."],["11561","841","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["11562","842","<b>שוש תשיש</b>: נוסח ברכת נשואין."],["11563","843","<b>לכ\"ם</b>: פינחס כט, לה."],["11564","844","<b>כנ\"ל</b>: דחט: ליתא."]]],[2300540941,"כו' כמו שאו' והביאנו לציון עירך כו' כנ\"ל, וע\"כ פרזות תשב כו' בלי חומה כלל כי אין מנגד כלל שיצטרך להגביל ולהגן לשמירה כלל, וזהו ביום השמיני דוקא שלח המלך את העם כו' (שזהו מלך <span data-k=\"pg\">שמג</span> ּ המשיח מלך הח' שנק' הד\"ר כו' כמ\"ש במ\"א).\n<b>ואחכ\"ז</b> יובן מ\"ש צדקת פרזונ\"ו היינו פזרונ\"ו כמו<sup data-n=\"11565\">845</sup> דפזרונו ופרזונ\"ו ענין א' הוא, דענין פזרונו הוא שפיזרן לבין אוה\"ע הי' כדי שיבררו כל הניצוצים דקדושה חיל רב מע\"ש דנוגה ויהי' קיבוץ גליות בשמחת עולם לירושלים בבחי' נצחי' דא\"ס עצמו כנ\"ל, והוא ע\"י מדת הניצוח ששרשה למעלה מן הרצון וחכ' כנ\"ל, הרי עי\"ז אח\"כ כאשר נשלם הניצוח הזה נעשה בבחי' פרזונו שהוא מ\"ש פרזות תשב ירושלים בין בפנימי' האור האלקי בגילוי מל' דא\"ס עצמו ובין בחיצוני' בזמן ומקום, וא\"כ מפזרונו נעשה פרזונו דהכל א' דהא בהא תליא, לפי שבחי' שמחת עולם דירושלים דלע\"ל יבא מסיבת ענין הפיזור דכנ\"י בע\"ש זמן רב כ\"כ שנק' בזבוז האוצרות העליונים כנ\"ל ע\"י בחי' הניצוח, וז\"ש ג\"כ א\"ת פרזונ\"ו אלא פזרונו כו' (ונמצא ענין בזבוז האוצרות הוא בב' אופנים הפכים, א' לנצח המלחמה לאכפייא לסט\"א בזמן הגלות דשלט האדם באדם כו', והוא פיזור דניצוצות דנש\"י שנולדו בגוים זמן רב כו' כנ\"ל. והב' בזבוז אוצרות עליונים דח\"ע ותענוג הפשוט דעוה\"ב כנ\"ל לאחר גמר הניצוח, שהוא בש\"ע שיבא לירושלים בשמחת עולם שישפוך רוחו עכ\"ב וניבאו בניכם כו' וכמ\"ש להנחיל אוהבי יש האמיתי כו' מיש ליש ממש כנ\"ל, ואוצרותיהם אמלא בגילוי ההעלם שמגלה עמוקות דסדכ\"ס למטה כמו למעלה ממש שנק' פזרונו גם בזמן ומקו[ם] כנ\"ל וד\"ל).\n<b>והנה</b> לכאורה יש סתירה על כל הנ\"ל [ב]מ\"ש והנצח זו בנין ירושלים וכמ\"ש פרזות תשב ירושלים ממש<sup data-n=\"11566\">846</sup> ואני אהי' לה חומת אש סביב נאום ה'<sup data-n=\"11567\">847</sup> כו', דמשמע מזה שיצטרך עכ\"פ לשמירה ולהגן מן המנגד שלא יקרב לעיר ע\"כ יהי' לחומת אש סביב כו', ואם מפני שלא תהי' החומה עשוי' מאבנים ועפר בחיצוני' רק חומת אש [ה]אלקי כמ\"ש ואני אהי' לה כו', עכ\"ז לא נק' פרזות אחר שיהי' חומה של אש מקפת כו'. אך הענין הוא דמה שיהי' לה חומת אש אלקי אינו ענין הגבלה להגן ולשמירה כי לא יהי' מנגד כלל, רק שיהי' להאיר על ירושלים באור ואש האלקי העליון בבחי' מקיף העליון, ולא כענני כבוד שהיו במדבר בבחי' העלם כעננים, ולא כעמוד אש לילה<sup data-n=\"11568\">848</sup> שהוא",[["11565","845","<b>כמו</b>: דט: ליתא. ח: כו'."],["11566","846","<b>ממש</b>: דחט: ממה שא'."],["11567","847","<b>ואני אהי' לה. . ה'</b>: זכרי' ב, ט [ושם: נאום ה' חומת אש סביב]."],["11568","848","<b>כעמוד אש לילה</b>: בשלח יג, כב."]]],[2300540948,"במדרגו' של ההשתל' דאורות העליונים שנק' מקיפים ופנימים, אלא יהי' חומת אש זו ממדרגה עליונה מאד נעלה שאין למעלה הימנו והוא מ\"ש ואני אהי' להם<sup data-n=\"11569\">849</sup> חומת אש כו' אני בעצמי [דוקא] שלמעלה מכל ההשתל' כו' וד\"ל.\n<b>ולהבין</b> ביאור הענין, הנה יש להקדים המאמר ע\"פ אני חומה זו תורה וכן א' השרוי בל[א] תורה שרוי בל[א] חומה<sup data-n=\"11570\">850</sup> דמשמע מזה שהתו' היא<sup data-n=\"11571\">851</sup> מגינה על האדם כחומה ממש וכמ\"ש ובשכבך תשמור עליך<sup data-n=\"11572\">852</sup> כו' וא' דתו' מגנא ומצלא<sup data-n=\"11573\">853</sup> אפי' בעידנא דלא עסיק בה כמו בשכבך תשמור כו' (וראי' מרבב\"נ<sup data-n=\"11574\">854</sup> דלא פסיק פומי' מגירסא<sup data-n=\"11575\">855</sup> ולא יכול מה\"מ לגשת אליו). ובאמת י\"ל מה שייכות יש לתורה לענין חומה דוקא שזהו כמו חומה גשמי' העשוי' מאבנים ועפר דוקא. אך הנה יש להקדים ביאור <span data-k=\"pg\">688</span> ּ ענין בחי' מקיפי' העליונים שהן בחי' מגן ומחסה על נפש האדם וכן בכלל נש\"י להגן מכל קטרוג למעלה ולמטה בפו\"מ, שזהו ג\"כ כמו חומה גשמי' וכמחסה דצור ואבן כמו כי אתה ה' מחסי<sup data-n=\"11576\">856</sup> כו' וכה\"ג אנו אומרים אדון עוזינו צור משגבינו<sup data-n=\"11577\">857</sup> מגן ישענו כמ\"ש ה' צורי אחסה בו<sup data-n=\"11578\">858</sup>. והנה ידוע בסה\"ק<sup data-n=\"11579\">859</sup> שעיקר בחי' המקיפים העליונים שנק' מגן ומחסה היינו בחי' ר\"ר העליונים דוקא שנמשכו למטה להגן כמו הנשר שעל גוזליו ירחף<sup data-n=\"11580\">860</sup> כו'. וי\"ל מהו בחי' ר\"ר הללו למעלה שמתפשטים למטה מטה דוקא, וכמו המרחם על העני ומדוכא ושפל ביותר שסיבת הרחמנות אינו רק מצד השפלו' העצומה והעניות והיסורים כצעקת עני ומדוכה, אבל [על] העשיר ושר המרומם לא יפול בחי' הרחמנות כ\"כ כלל וכלל להתחסד עמו (הגם שיש חסד וטוב גם לעשירים זהו שנק' חסד וטוב ולא רחמנות) כידוע. אבל בחי' ר\"ר העליונים שלמעלה בא בהשוואה א' ממש על העולמות העליונים מאד כמו על התחתו[נים] השפלים ביותר, כי סיבת הרחמים העליונים בא מצד עוצם הרוממות דעצמות [ה]א\"ס ב\"ה במה שנשגב שמו למעלה מכל ההשתל' דכולא קמי' כלא ממש חשיבי, לפי שמובדל ומרומם בערך מכל העולמות כמ\"ש המלך המרומם לבדו<sup data-n=\"11581\">861</sup> ממש המתנשא כו', ואפי' מעולם העליון ביותר שנק' עלמין סתימין<sup data-n=\"11582\">862</sup> כו' כמאמר דאפי' אור צח ומצוחצח אוכם הוא לגבי עה\"ע עצמו שנק' סדכ\"ס דלית מחתב\"כ וכמו שאו' לעילא מן כל ברכתא כו' דאמירן בעלמא כו' כנ\"ל<sup data-n=\"11583\">863</sup>, והוא בבחי' ההתנשאו' דעצמות ממש שאין לו שיעור למעלה מעלה שע\"כ אמר משובח ומפואר עדי עד כו' וכן יהללוך סלה<sup data-n=\"11584\">864</sup> בלי שיעור כלל כידוע. ולפ\"ז הרי יובן דשוה ומשוה עליונים ותחתונים, שתגדל הרחמנות על עולם העליון",[["11569","849","<b>להם</b>: דחט: לה."],["11570","850","<b>השרוי בל[א] תורה. . חומה</b>: וכ\"ה במאמרי אדה\"ז תקס\"ה כאן [ע' א']. אמנם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470099\" data-slug=\"or-hatorah-hb\" data-id=\"8316470099\">אוה\"ת יתרו ע' תקסה</a>: השרוי בלא אשה. . בלא תורה בלא חומה פרק הבע\"י [יבמות] דס\"ב ע\"ב."],["11571","851","<b>היא</b>: חט: ליתא."],["11572","852","<b>ובשכבך תשמור עליך</b>: משלי ו, כב [ושם: בשכבך וכ\"ה בדט. — ראה מאמרי אדה\"א במדבר ח\"ב ר\"ע תרנג]."],["11573","853","<b>דתו' מגנא ומצלא</b>: ראה סוטה כא, א. ש\"א יב, א ובהערה 16. אוה\"ת מג\"א ס\"ע רעו."],["11574","854","<b>מרבב\"נ</b>: דחט: מרבה ב\"נ."],["11575","855","<b>דלא פסיק פומי' מגירסא</b>: ב\"מ פו, א."],["11576","856","<b>כי אתה ה' מחסי</b>: תהלם צא, ט."],["11577","857","<b>אדון עוזינו צור משגבינו</b>: ברכת יוצר."],["11578","858","<b>ה' צורי אחסה בו</b>: שמו\"ב כב, ב. ג [ושם: ה'. . אלקי צורי]. תהלים יח, ג [ושם: ה'. . אלי צורי]."],["11579","859","<b>בסה\"ק</b>: חט: בספרי הקבלה."],["11580","860","<b>הנשר שעל גוזליו ירחף</b>: האזינו לב, יא."],["11581","861","<b>המלך המרומם לבדו</b>: ברכת יוצר."],["11582","862","<b>עלמין סתימין</b>: ת\"ז בהקדמה (יז, א)."],["11583","863","<b>לעילא מן כל ברכתא. . כנ\"ל</b>: שכג, ב."],["11584","864","<b>יהללוך סלה</b>: תהלים פד, ה."]]],[2300540955,"ביותר כמו שירחם על [ה]בריות השפלים<sup data-n=\"11585\">865</sup> ביותר כי בחי' עו[מ]\"ר ועו[מ]\"ת שוין לפניו ממש כמו המגביהי לשבת המשפילי לראות<sup data-n=\"11586\">866</sup> [כו'] בשמים ממעל ועל הארץ מתחת<sup data-n=\"11587\">867</sup> בשוה ממש, להיותו מובדל בערך מהיות גם מקור למקור דקו\"ח במקיפים ופנימי' בכו\"פ<sup data-n=\"11588\">868</sup> כו' להיותו למעלה מבחי' מעלה ומטה ולזאת בחי' מעו\"מ שבקו\"ח שוין ממש וד\"ל. ואדרבה כל הקרוב קמי' ממש יותר כלא יחשב מאחר דמה<sup data-n=\"11589\">869</sup> שאין לו שיעור למעלה בעילוי אחר עילוי היינו שיותר מובדל ומרומם בהפלאה והבדלה כו' ולכך יהללוך סלה כו', א\"כ כל העולה יותר יותר יבא לבחי' העדר ההשגה בביטול במציאות יותר כנ\"ל דגם אור צח כו' (כמו אור המקיף דכתר אע\"פ שנק' מקיף לחכמה בעלותו למעלה יותר נעשה בחי' צמצום דאו\"פ כידוע בז' עליות דהוי' הוא אלקי'<sup data-n=\"11590\">870</sup> בעולם העליון ממנו כו', וע\"כ אנו רואים שכל הקרוב קרוב יותר לאור פני אלקי' כמשה [ש]הי' בביטול דמ\"ה בעצם יותר כו'). ולפי\"ז נמשך בחי' הר\"ר שמצד רוממות אמיתי' עצמותו ית' על כל העליונים כמו [על] התחתונים, לזה אנו או' אחר המלך המרומם לבדו כו' אלקי עולם ברחמיך הרבים רחם עלינו להיות אדון עוזינו כו' עד משגב בעדינו פי' ברחמיך הרבים דוקא, כי סיבת הר\"ר הללו לא נודע ומושג בעולמות כלל אף לעליונים מצד הפלאות והבדלת הערך ביותר ע\"כ אומרים ברחמיך הרבים שלא נודע הרחמנות רק לו ית' לבדו, <span data-k=\"pg\">שדמ</span> ּ ומבחי' ר\"ר שבעצמ[ו]' ממש יומשך עלינו בבחי' מקיף בהעלם, כמו רחמי האב על התינוק ובהמה שאין בהם דעת להכיר הרחמנות אשר עליהם מצד שפלות ערכם והאב ברוממות החכ' והחסד שבו יראה וידע הרחמנות שעליהם וירחם עליהם. וכך למעלה מרחם על הבריות השפלים בבחי' מקיף בהעלם עליהם וכן גם עולמות העליונים לפי שאין ערך כלל בעליונים כמו בתחתונים מטעם הנ\"ל. וזהו רחם עלינו להיות אדון עוזינו וצור משגבינו [כו'] שהן ד' מיני מקיפים<sup data-n=\"11591\">871</sup> העליונים מאצי' לבריאה<sup data-n=\"11592\">872</sup> שבאים בהתלבשות בהעלם ע\"י<sup data-n=\"11593\">873</sup> נש\"י בבחי' מקיף ומגן ומחסה עליהם כמו צור וחומה להצילם מן הקטרוג למעלה ברוחניות עד שנק' משגב בעדינו בנשמות שבגופי' גשמיי' בעולם העשי' להגן עליהם מכל אויב ומשחית בגשמיות וד\"ל.\n<b>והנה</b> בחי' המשכת ר\"ר הנ\"ל הוא שנק' בשם מקיפים העליונים שנמשכים למטה לשמירה ולהגין כמו החומה המקפת",[["11585","865","<b>הרחמנות. . העליון. . השפלים</b>: ראה לעיל קעא, א ואילך. מאמרי אדה\"א דברים ח\"א ע' צג. וש\"נ."],["11586","866","<b>המגביהי לשבת המשפילי לראות</b>: תהלים קיג, ה. ו."],["11587","867","<b>מתחת</b>: חט: ליתא."],["11588","868","<b>במקיפים ופנימי' בכו\"פ</b>: שם: במקום פנוי בכלל ובפרט."],["11589","869","<b>דמה</b>: שם: ליתא."],["11590","870","<b>בז' עליות דהוי' הוא אלקי'</b>: ראה לעיל פ' שמות מח, ג. וש\"נ."],["11591","871","<b>אדון עוזינו. . ד' מיני מקיפים</b>: נסמן לעיל פ' וארא נג, א."],["11592","872","<b>לבריאה</b>: דח: לבי\"ע. ט: מטושטש."],["11593","873","<b>ע\"י</b>: שם: על."]]],[2300540962,"לשמור לעיר מן האויב, דהיינו שנמשך מבחי' ההעלם דעלמין סתימין שנק' מקיפים למעלה שזהו ענין העלי' בעצמות הרוממות<sup data-n=\"11594\">874</sup> דא\"ס באין<sup data-n=\"11595\">875</sup> שיעור למעלה כו' כמו ישת חש\"ך סתר\"ו ונק' סת\"ר עליו\"ן וצ\"ל שדי<sup data-n=\"11596\">876</sup> וכה\"ג עד בחי' סדכ\"ס כנ\"ל, שמבחי' ההעלם הזה דוקא הוא שנמשך למטה בעולמות דבי\"ע עד עוה\"ז השפל כנ\"ל בענין אדון עוזינו צור כו'. והטעם הוא לפי שעיקר בחי' הרחמנות שלמעלה אינו אלא מצד הרוממות ביותר כנ\"ל [ו]כמו שאנו רואים שכל מלך ב\"ו<sup data-n=\"11597\">877</sup> ושר מצד הרוממות שלו יותר ירחם על השפלים, משא\"כ מי שאינו מרומם כ\"כ אינו מרחם כ\"כ. וכך הוא למעלה כל שהוא מרומם יותר בהעלם אחר העלם מכל ההשתל' משם יומשך ר\"ר יותר כנ\"ל בפי' ברחמיך הרבים דוקא רחם עלינו כו', א\"כ כל מה שירד אור המקיף למטה יותר בהלבשה גשמיות זהו בא דוקא מבחי' הרוממות מהעלם העצמו' יותר כו' כמו ענני כבוד שהיו בחי' מקיפים [ב]לבוש עננים גשמיי' והיו מאירי' מאורות [ה]מקיפים עליונים [ב]יותר, וכן בחי' מקיפי' ששורים בצל הסכך הגשמי שנק' מקיפי' דאימא<sup data-n=\"11598\">878</sup> כידוע כמו על גוזליו ירחף כו', והוא לשמירה בגשמיות כמו שאומרים ופרוס עלינו סוכת שלומך<sup data-n=\"11599\">879</sup> כו'. וידוע דכל שומר<sup data-n=\"11600\">880</sup> גדול יותר<sup data-n=\"11601\">881</sup> מן המשתמר שלא יוכל המשתמר להשיג[ו] כלל (וכמו ניסים שנעשו בהעלם שאין בעה\"נ מכיר<sup data-n=\"11602\">882</sup> כלל במקטרגים שנתבטלו מפני ששומר ישראל [ו]לא נודע למטה כלל כו') וכמ\"ש דוד כי יצפנני בסוכו<sup data-n=\"11603\">883</sup> ביום רעה דדינא שלטא כו' יסתירני בסתר אהלו בצור ירוממני כנ\"ל<sup data-n=\"11604\">884</sup>, והן מקיפים ששומרים לאדם מכל חטא שלא יכשל בו כמו שנשמר בגשמיות מן המזיקים ולסטים וכה\"ג (וכמו וישם ה' לקין אות<sup data-n=\"11605\">886</sup> כו' וכתי' ויס\"ך אלקי בעדי<sup data-n=\"11606\">887</sup> כו' ובאיוב א' הלא אתה סכת בעדי<sup data-n=\"11607\">888</sup> ), וזהו ברוך מרחם על הבריות<sup data-n=\"11608\">889</sup> על כל הבריות משום דרחמיו על כל מעשיו<sup data-n=\"11609\">885</sup> (וכמו בנינוה שא' ואיך לא אחו\"ס<sup data-n=\"11610\">890</sup> על אד\"ם ובהמ\"ה רב\"ה כו'). וא\"כ יובן עכ\"פ שיש חילוקי מדריגות מרוחניות לגשמיות בהמשכת הר\"ר שנק' מקיפים בכל עולם לפ\"ע<sup data-n=\"11611\">891</sup> עד עוה\"ז [ב]גשמי' והכל נמשך מבחי' העלם דמקיפי' [ה]עליונים אף שנמשך על כל העולמות [על] העליוני' כמו על התחתונים בשוה, מ\"מ באים בהתלבשו' לפ\"ע <span data-k=\"pg\">690</span> ּ כל עולם, כמו שיש הפרש במקיף לשמור מן החטא כמו רגלי חסידיו ישמור<sup data-n=\"11612\">892</sup> כו' וכמו ולא יאונה לצדיק<sup data-n=\"11613\">893</sup> כו' כמו כי הוא יצילך<sup data-n=\"11614\">894</sup> מפח יקוש כו' באברתו כו' ותחת כנפיו<sup data-n=\"11615\">895</sup> כו', ובין<sup data-n=\"11616\">896</sup>",[["11594","874","<b>בעצמות הרוממות</b>: שם: ברוממות העצמות."],["11595","875","<b>באין</b>: שם: בלי."],["11596","876","<b>סת\"ר עליו\"ן וצ\"ל שדי</b>: תהלים צא, א."],["11597","877","<b>ב\"ו</b>: חט: ליתא."],["11598","878","<b>הסכך. . מקיפי' דאימא</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'שנו. וש\"נ."],["11599","879","<b>ופרוס עלינו סוכת שלומך</b>: ברכת השכיבנו."],["11600","880","<b>דכל שומר. . המשתמר</b>: נסמן לעיל פ' וארא נח, ד."],["11601","881","<b>יותר</b>: דחט: ליתא."],["11602","882","<b>שאין בעה\"נ מכיר</b>: ראה גם לעיל פ' שמות כא, א. וש\"נ."],["11603","883","<b>כי יצפנני בסוכו</b>: תהלים כז, ה. ראה זהר מצורע נד, סע\"א. מאמרי אדה\"א דברים ח\"ד ע' א'שעה."],["11604","884","<b>ירוממני כנ\"ל</b>: דחט: כו'."],["11605","886","<b>וישם ה' לקין אות</b>: בראשית ד, טו. ראה גם מאמרי אדה\"א שמות ח\"א ע' כז. וש\"נ. נ\"ך ע' ל."],["11606","887","<b>ויס\"ך אלקי בעדי </b>[ד: בעדו]: — איוב ג, כג. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שמא. דברים ח\"ד ע' א'שעו. לעיל פ' וארא סב, ג."],["11607","888","<b>הלא אתה סכת בעדי </b>[ד: שכת בעדו]: איוב א, י."],["11608","889","<b>ברוך מרחם על הבריות</b>: ברכת ברוך שאמר."],["11609","885","<b>(וכמו. . מעשיו</b>: חטטו: ליתא. ד: כבפנים."],["11610","890","<b>ואיך לא אחו\"ס</b>: יונה ד, יא [ושם: ואני לא אחוס. . אדם. . ובהמה רבה — ראה גם מאמרי אדה\"א דברים ח\"א ע' שט]."],["11611","891","<b>לפ\"ע</b>: חט: לפי ערכו."],["11612","892","<b>רגלי חסידיו ישמור</b>: שמו\"א ב, ט. ראה גם מאמרי אדה\"א נ\"ך ע' ל. וש\"נ."],["11613","893","<b>ולא </b>[דחט: לא]<b> יאונה לצדיק</b>: משלי יב, כא. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שעה."],["11614","894","<b>כי הוא יצילך</b>: תהלים צא, ג."],["11615","895","<b>באברתו כו' ותחת כנפיו</b>: תהלים שם, ד."],["11616","896","<b>ובין</b>: חט: וכמו. ד: כבפנים."]]],[2300540968,"מקיף זה עצמו לשמור בגשמיות מכל פגע רע בפ\"מ, ושרשם הכל א' ממקור כל המקיפי' העליונים שנק' ר\"ר העליונים שבא[ו] מרוממו' העצמו' דוקא שאין לו שיעור למעלה כלל כנ\"ל וד\"ל.\n<b>וז\"ש</b> אני חומה זו תורה כו', דהנה הגם שמבואר למעלה בשרש בחי' המשכת המקיפי' עליונים<sup data-n=\"11617\">897</sup> שהן בחי' הר\"ר שנמשך למטה להגן על האדם, מ\"מ איך שייך לומר שיהי' בחי' מקיף [ד]ר\"ר זה בא בהתלבשות גשמי להיות כ[מו] חומה ממש שעשוי מאבנים ועפר גשמי כו'. אך לזאת א' אני חומה זו תו' הנגלית לנו בבחי' אותיות ממש, שאותיות התו' נעשה בחי' חומה גשמיות מאבנים להגן על האדם ברוחניות ובגשמיות ממש כנ\"ל אפי' בעת שאינו לומד וקורא כמו בשכבך תשמור עליך כו'. והענין הוא כידוע שהאותיות נק' אבנים כמ\"ש בס\"י ה' אבנים בונות ק\"ך בתים שמה' אותיות נעשה ק\"ך צירופים כו', וכך גם אותיות תשב\"כ אעפ\"י שבאים בגשמיות בקלף ודיו כו' הן למעלה בבחי' אותיות העליונים דשמות וצירופי' דאו\"כ דאצי' כמ\"ש הקורא בתו' קורא בשמותיו<sup data-n=\"11618\">898</sup> כו' שהן בחי' מקיפים העליונים והוא בחי' רצה\"ע וח\"ע הגנוז בטנת\"א כמו<sup data-n=\"11619\">899</sup> שיתגלה לע\"ל ומתלבשים באותיות הללו דוקא, וע\"כ יש בה[ן] קרי וכתיב<sup data-n=\"11620\">900</sup> מלא וחסר כו' וכמ\"כ בכל פסוקי הנביאים וכתובים הכל בכתב מיד ה'<sup data-n=\"11621\">901</sup> כידוע. וידוע דג' קשרין הן ס\"ר נש\"י מתקשראן בס\"ר אותיות התו' בשרשם למעלה בתוה\"ק<sup data-n=\"11622\">902</sup> בחי' סתים דישראל עלו במחה\"ק וע\"כ האותיות הן בחי' עצמ[י]' ופנימי' בלי שינוי כלל (ונק' מיילדות העבריות<sup data-n=\"11623\">903</sup> כנ\"ל<sup data-n=\"11624\">904</sup> כמ\"ש במ\"א). וזהו אז ראה ויספרה כו' כאבן ספיר<sup data-n=\"11625\">905</sup> וזהו לבנת הספיר ומבואר במ\"א שהן ב' מיני אותיות דתושב\"כ ושבע\"פ<sup data-n=\"11626\">906</sup> דאותיות דתושב\"כ נק' אבן ספיר מתחלת הווייתן<sup data-n=\"11627\">907</sup> [קדש] כו', ואותיות דתושבע\"פ שאו' בכל לשון זהו כלבינה שנעשה מעפר אחר השריפה וכמ\"ש ותהי להם הלבינה לאבן<sup data-n=\"11628\">908</sup> שממנו עיקר בנין החומה מאבנים ולבנים בגשמיות. וכמ\"כ ממש באותיות התורה הנגלית לנו שמקושרים בהן ס\"ר נש\"י וענפיהן שבכל דור ודור המלובשים בגופי' שזהו כריתות ברית דתו' בחורב<sup data-n=\"11629\">909</sup> (אף [ל]נשמות שאיננו פה היום), וע\"כ גם ע\"ה או'<sup data-n=\"11630\">910</sup> ומברכים<sup data-n=\"11631\">911</sup> נותן התורה כו' וזהו ויאמר לאדם הן כו' וד\"ל. וזהו פי'<sup data-n=\"11632\">912</sup> הטעם כל הקורא בתורה ולומד במשנה ובתלמוד מגין על נפשו",[["11617","897","<b>עליונים</b>: חט: ליתא."],["11618","898","<b>הקורא בתו' קורא בשמותיו</b>: נסמן לעיל פ' שמות ז, ד."],["11619","899","<b>כמו</b>: חט: כו'."],["11620","900","<b>קרי וכתיב</b>: ראה גם בענין קרי וכתיב מאמרי אדה\"ז הקצרים ע' קכז. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תנה ואילך. ע' תפב."],["11621","901","<b>הכל בכתב מיד ה'</b>: דהי\"א כח, יט."],["11622","902","<b>בתוה\"ק</b>: חט: בתורה הקדומה — נסמן לעיל ב, ד."],["11623","903","<b>מיילדות העבריות</b>: ראה לעיל פ' שמות לב, א."],["11624","904","<b>כנ\"ל</b>: חטטו: ליתא."],["11625","905","<b>ויספרה. . כאבן ספיר</b>: ראה גם תו\"ח ח\"ש קלד, ב."],["11626","906","<b>ב' מיני אותיות דתושב\"כ ושבע\"פ</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' עו ואילך. ע' סז ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'תנ ואילך. וש\"נ. שמות ח\"א ע' עג."],["11627","907","<b>אבן ספיר מתחלת הווייתן</b>: וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550058\" data-slug=\"torat-chaim\" data-id=\"2300550058\">תו\"ח</a> ח\"ש שם. ראה לקמן פ' תצוה שמה, ג. מאמרי אדה\"א שמות ח\"ב ע' שצא. דברים ח\"ד ע' א'תנא."],["11628","908","<b>ותהי להם הלבינה לאבן</b>: נח, יא, ג."],["11629","909","<b>כריתות ברית דתו' בחורב</b>: ואתחנן ה, ב."],["11630","910","<b>ע\"ה או'. . נותן התורה</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, סהי\"ב. וש\"נ. מאמרי אדה\"א דברים ח\"ג ע' תשעט. וש\"נ. שע\"ת לט, ב ובהערה 18."],["11631","911","<b>ומברכים</b>: חט: ומברך."],["11632","912","<b>וזהו פי'</b>: שם: ומזה."]]],[2300540974,"מאותיות התו' שקורא ולומד כמו שמגין החומה על העיר להצילו מכל חטא ומכל מזיק בפו\"מ וכמ\"ש ואשים דברי בפיך<sup data-n=\"11633\">913</sup> ובצל ידי כסיתיך כו', כי הוי' יושב ושונה [כנגדו] כו' וכמ\"ש ה' צלך, והיינו בחי' המקיפי' העליונים שמתלבשים באותיות הללו כמו כי אתה ה' מחסי כו'. ואע\"פ שהן אותיות גשמי' ומלובשי' בעניני' גשמי', מ\"מ יש בהם מאור המקיף העליון דוקא עד שנק' שומר לנפש האדם כנ\"ל וכל שומר גדול מהמשתמר כנ\"ל, וכמו עד\"מ החומה אע\"פ שהוא מאבנים ועפר גשמיות בחי' דומם מגינה על העיר ויושביה שהן בחי' אדם מדבר כו', וכך אותיות התו' מצד עצם<sup data-n=\"11634\">914</sup> שרשם למעלה מעלה משרש נשמת <span data-k=\"pg\">שמה</span> ּ האדם שלמטה כנ\"ל (גם למעלה משרש נשמת האדם בחו\"ב דאצי' מקור המדות דאצי', כי התו' שרשה בחה\"ק<sup data-n=\"11635\">915</sup> קודם הצמצום דקו\"ח להאציל ע\"ס כו' כנ\"ל [ו]כמ\"ש ואהי' אצלו אמון מוצנע<sup data-n=\"11636\">916</sup> כו' רק שירדה למטה בהתלבשות בעה\"ד טו\"ר בדברים גשמיי' ברמ\"ח מ\"ע ושס\"ה ל\"ת כו', ע\"כ יש בכח האותיות הללו להיות בחי' שומר להגן על הנשמה כחומה ממש (והוא גם מצד שרש נש\"י במחה\"ק כו' וד\"ל. וזהו אני חומה דכנ\"י או' אני חומה שהן מקיף דתורה לכללות נש\"י להגן עליהם אף בזמן הגלות שנק' שינה כמ\"ש אני ישינה<sup data-n=\"11637\">917</sup> כו') (ושדי כמגדלות<sup data-n=\"11638\">918</sup> היינו בחי' פנימי' התורה שהן רזי תורה וסודות כטעמי המצות שנק' חלב<sup data-n=\"11639\">919</sup> שנמשך משדים כמו יונק שדי אמי<sup data-n=\"11640\">920</sup> כמ\"ש במ\"א) וכמו החומה שעשוי להגן ולהבדיל בהם הפנימי' מן החיצוני' שנק' חותם כנ\"ל בענין חומ\"ת וחות\"ם ותחו\"ם כו' כמשי\"ת.\n<b>ומ\"ש</b> דוד אחת שאלתי<sup data-n=\"11641\">921</sup> כו' שבתי בבית ה' כו' שהן אותיות התו' שנק' בית ה' והיכלא דאוריי' היכלא עילאה<sup data-n=\"11642\">922</sup> כו' וכמשארז\"ל דמשחרב בהמ\"ק אין לו להקב\"ה<sup data-n=\"11643\">923</sup> בעולמו אלא ד\"א ש\"ה במקום היכל ק\"ק<sup data-n=\"11644\">924</sup> וכתיב ביעקב איש תם יושב אוהלים<sup data-n=\"11645\">925</sup> כו'<sup data-n=\"11646\">926</sup> אהל תו[רה]<sup data-n=\"11647\">927</sup> וכמ\"ש ביהושע לא ימיש מתוך האהל<sup data-n=\"11648\">928</sup> כו' כידוע. אך ידוע דבג\"ע העליון ותחתון יש בתים והיכלות עליונים שנק' אידרין עילאין<sup data-n=\"11649\">929</sup> כו', והוא בחי' היכל דתורה הפנימי' כמו היכל ק\"ק שבו הי' הארון והלוחות כו'. וזהו בשעה שיושב ועוסק בתו[רה] שמהבל הדיבור נעשה או\"מ<sup data-n=\"11650\">930</sup> לנשמתו כמו היכל ק\"ק<sup data-n=\"11651\">931</sup> והקב\"ה יושב ושונה כנגדו בהיכל ז[ה] עצמו, שזהו הטעם שנק' אחים וריעים להקב\"ה כו' כמ\"ש למען אחיי",[["11633","913","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["11634","914","<b>עצם</b>: חט: ליתא."],["11635","915","<b>בחה\"ק</b>: שם: בחכמה הקדומה."],["11636","916","<b>ואהי' אצלו אמון מוצנע</b>: משלי ח, ל. ב\"ר בתחלתו."],["11637","917","<b>אני ישינה</b>: נסמן לעיל לז, ד."],["11638","918","<b>ושדי כמגדלות</b>: המשך הכתוב אני חומה."],["11639","919","<b>פנימי' התורה. . חלב</b>: ראה מאמרי אדה\"א שמות ח\"א ע' עז. וש\"נ. ח\"ב ע' תנט. תו\"ח נח סג, ג."],["11640","920","<b>יונק שדי אמי</b>: שה\"ש ח, א. ראה גם לעיל פ' שמות י, ב."],["11641","921","<b>אחת שאלתי</b>: תהלים כז, ד."],["11642","922","<b>דאוריי' היכלא עילאה</b>: ראה זהר ויקהל ר, א."],["11643","923","<b>דמשחרב בהמ\"ק אין לו להקב\"ה</b>: נסמן לעיל פ' וארא ע, ג."],["11644","924","<b>ד\"א ש\"ה במקום היכל ק\"ק</b>: נסמן לעיל פ' בא צד, א."],["11645","925","<b>ביעקב איש תם יושב אוהלים</b>: תולדות כה, כז."],["11646","926","<b>כו'</b>: כ\"ה גם בחט."],["11647","927","<b>אוהלים. . אהל תו[רה]</b>: ראה ב\"ר פס\"ג, י."],["11648","928","<b>ביהושע לא ימיש מתוך האהל</b>: תשא לג, יא. ראה גם מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרו."],["11649","929","<b>אידרין עילאין</b>: ראה ז\"ח לך כו, א. ויצא כח, ב. שה\"ש סח, ב."],["11650","930","<b>שמהבל הדיבור נעשה או\"מ</b>: נסמן לעיל קפא, ב."],["11651","931","<b>ק\"ק</b>: חט: ליתא."]]],[2300540979,"וריעיי<sup data-n=\"11652\">932</sup> [כו'] וכתיב מי יתנך כאח לי<sup data-n=\"11653\">933</sup> כו' עד שהביאותים אל בית אמי<sup data-n=\"11654\">934</sup> כו'<sup data-n=\"11655\">935</sup> ([ו]ע\"כ לע\"ל נק' היכל הוי' כמ\"ש היכל הוי' המה<sup data-n=\"11656\">936</sup> כו') דמקיף דהיכל ובית הכל<sup data-n=\"11657\">937</sup> א' מקיף לשניהם יחד כו'. וזהו היושבת בגנים בגעה\"ע וגעה\"ת<sup data-n=\"11658\">938</sup> חברים מקשיבים כו' וכתיב השמיעני את קולך קלא דאורייתא<sup data-n=\"11659\">939</sup> דוקא כמ\"ש בזהר דקוב\"ה אתא לאשתעשע<sup data-n=\"11660\">940</sup> בג\"ע בקול דתורה שלומדים שם (וכמו בעובדא דרב\"נ<sup data-n=\"11661\">941</sup> במחלוקת בדין קדם שער לבן לבהרת קוב\"ה אמר טהור ומתיבתא כו' וכה\"ג). וז\"ש כ\"א בתורת ה' חפצו<sup data-n=\"11662\">942</sup> מעיקרא אדעתי' דנפשי' עביד לתקן אור נשמתו בבחי' או\"פ ומקיף (כמשי\"ת), ואח\"כ ובתו[רתו] יהגה להמשיך אוא\"ס ב\"ה בתו[רה] שזהו עוסק בתו[רה] לשמה לשם התורה עצמה<sup data-n=\"11663\">943</sup> כמ\"ש במ\"א (והוא מ\"ש ולכבוד אהי' בתוכה<sup data-n=\"11664\">944</sup> כמשי\"ת). וז\"ש אחת שאלתי כו' שבתי בבית ה' כל ימי חיי בהיכל דתורה [ב]מקיף ופנימי ששרשה בחכ' דתוה\"ק הנ\"ל, ואז ממילא נמשך כל המקיפים העליונים שנעשים להגן ולהגביל האור כו' יצפנני בסוכו כו' עד בצור ירוממני כו'.\n<b>ואמנם</b> המדרג' הב' באותיות התורה הוא למעלה גם מבחי' היכל<sup data-n=\"11665\">945</sup> הפנימי אעפ\"י שהוא בבחי' חיצוני' יותר, והוא ענין החומה המקפת כל הבתים והיכלות דתורה אור שנעשה לשומר ולהגבלה כנ\"ל (כמו חומת ירושלים אעפ\"י שהוא בבחי' המל'<sup data-n=\"11666\">946</sup> בבחי' מקיף<sup data-n=\"11667\">947</sup> חיצוני, שם יש יתרון מעלה בחיצוני'<sup data-n=\"11668\">948</sup> מפנימי' האור דכתר וחכ' שבהיכל ק\"ק כו', <span data-k=\"pg\">692</span> ּ מאחר שנעשה לשמירה ולהגן כמ\"ש על חומותיך ירושלים כו' (וזהו שרמז במדרש שאמר דוד<sup data-n=\"11669\">949</sup> ממך למדתי שא' ועתה ישראל מה ה' אלקיך שואל מעמך כ\"א ליראה כו' ואח\"כ א' לאהבה ולעבדו<sup data-n=\"11670\">950</sup> כו', כך אני או' אחת שאלתי שבתי בבית ה' בהיכל דתו' שנמשך שם ממקיף העליון יותר [דנועם ה' ממילא], כמו שמלמטה למעלה צריך לבוש היותר עליון שיורד בהתלבשות בבית והיכל דוקא, וכמו\"כ מלמעלה למטה מה ה' שואל מעמך כ\"א ליראה שהוא בחי' אחרונה ביותר שזהו [ש]תלוי בידי אדם ולא בידי שמים כמאמר דהכל בי\"ש חוץ מי\"ש, ואמנם משום דנתב\"ס דוקא כידוע ע\"כ ממילא נכלל בזה גם האהבה במס\"נ כו' ויומשך המקיף בבחי' שמירה בחיצוני' שזהו בחי' חומה להגן ולהגביל",[["11652","932","<b>למען אחיי וריעיי</b>: תהלים קכב, ח. ראה לעיל קפ, א. וש\"נ."],["11653","933","<b>מי יתנך כאח לי</b>: התחלת הכתוב יונק שדי אמי — שה\"ש ח, א."],["11654","934","<b>עד שהביאותים </b>[ח: שהבאתיו]<b> אל בית אמי</b>: שה\"ש ג, ד."],["11655","935","<b>כו'</b>: בתו\"ח כאן נכפלו התיבות: כמ\"ש למען אחיי וריעיי."],["11656","936","<b>היכל הוי' המה</b>: ירמי' ז, ד. ראה גם בסמוך בפסקא אך. לקמן פ' פקודי תמב, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380052\" data-slug=\"likkutei-torah\" data-id=\"4001380052\">לקו\"ת פקודי ג, א</a>. מאמרי אדה\"ז תקס\"ז ע' רכה. מאמרי אדה\"א במדבר ח\"ג ע' תתקצח-ט. שמות ח\"ב ע' שעז."],["11657","937","<b>הכל</b>: חט: ליתא."],["11658","938","<b>היושבת בגנים בגעה\"ע וגעה\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680032\" data-slug=\"torat-chaim\" data-id=\"2300680032\">תו\"ח וישב קצח, א</a> ובהערה 6. ויחי רמז, ב. לקמן פ' יתרו רסח, א."],["11659","939","<b>השמיעני את קולך קלא דאורייתא</b>: נסמן לעיל קח, ג."],["11660","940","<b>דקוב\"ה אתא לאשתעשע</b>: ראה זהר לך עז, א."],["11661","941","<b>בעובדא דרב\"נ</b>: ב\"מ פו, א."],["11662","942","<b>כ\"א בתורת ה' חפצו</b>: תהלים א, ב. ראה פסחים סח, ב. מאמרי אדה\"א שמות ח\"ב ע' שסז. וש\"נ. במדבר ח\"ב ע' תרס. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680447\" data-slug=\"torat-chaim\" data-id=\"2300680447\">תו\"ח מקץ רכו, ג</a> ובהערה 38. לקמן פ' ויקהל תיז, א. וש\"נ."],["11663","943","<b>לשמה לשם התורה עצמה</b>: ראה לעיל פ' וארא פ, ד הערה 576. בהערה שלפנ\"ז."],["11664","944","<b>ולכבוד אהי' בתוכה</b>: (המשך הכתוב ואני אהי' לה חומת אש) זכרי' ב, ט."],["11665","945","<b>מבחי' היכל</b>: חט: מהיכל."],["11666","946","<b>ירושלים. . המל'</b>: ראה זהר שלח קעא, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשלז. שע\"ת עג, ד ובהערה 85."],["11667","947","<b>בבחי' מקיף</b>: חט: במקיף."],["11668","948","<b>בחיצוני'</b>: שם: ליתא."],["11669","949","<b>במדרש שאמר דוד</b>: ראה מדרש תהלים כז, ד. יל\"ש שם."],["11670","950","<b>לאהבה ולעבדו</b>: בעקב שם: ולאהבה אותו ולעבד את ה\"א."]]],[2300540984,"האור דקדושה כו'. ואמנם יר\"ת שנעשה חומה חיצונית נמשך מיר\"ע<sup data-n=\"11671\">951</sup> הפנימי' שבאהל והיכל דתו' דנסב\"ת וכן להיפוך נתח[ב]\"ס דוקא כמ\"ש סוף דבר הכל נשמע<sup data-n=\"11672\">952</sup> כו' [ו]הוא לימוד דתושבע\"פ דוקא כמו ב\"ע הי' שונה ואש מלהטת סביבו<sup data-n=\"11673\">953</sup> כו' וכמאמר מה להלן באימה כו' וכמ\"ש במ\"א עמ\"ש לבך יהגה אימה כו' וכמ\"ש<sup data-n=\"11674\">954</sup> בהתהלכך תנחה אותך<sup data-n=\"11675\">955</sup> כו' בשכבך תשמור עליך כו' אף בעידנא דלא עסיק בה כמו החומה המקפת ומגנת כו' (וראי' מראב\"נ<sup data-n=\"11676\">*956</sup> כנ\"ל ומבני עלי<sup data-n=\"11677\">956</sup> וחזקי' המלך<sup data-n=\"11678\">*957</sup> כו' כמ\"ש בגמ' וד\"ל).\n<b>וזהו</b> זאת נחמתי בעניי<sup data-n=\"11679\">957</sup> כו', דהנה מ\"ש אלקי עולם ברחמיך הרבים<sup data-n=\"11680\">958</sup> כו' והיינו לפי שקדם לומר המלך המרומם לבדו כו' שמפני זה יגדל הרחמים על כל העולמות בשוה כנ\"ל, ומרח\"ר הללו נמשך בחי' מקיף דהיינו מ\"ש אדון עוזינו צור משגבינו כו' והוא אותיות התו' שנק' חומה המגינה על נפש האדם בתמידות כנ\"ל. וז\"ש זאת נחמתי בעניי כו', פי' לאחר שמעורר על נפשו ועל כל העולמות בחי' ר\"ר הנ\"ל יאמר לנחם נפשו זאת נחמתי בעניי בשפלות עצומה כזאת כו' עכ\"ז אמרתך חייתני, פי' אמרתך הן אותיות התו'<sup data-n=\"11681\">*959</sup> כמו שהן בשרשן למעלה מעלה במקור חוצב[ם] הראשון בעצמות המאציל כמ\"ש אז ראה ויספרה כו' וכן ואהי' אצלו אמון כו' כנ\"ל, שהוא למעלה מכל ההשתל' הרי הן עצמן הוא שירדו למטה מטה מאד ונתלבשו בעניני' גשמיי' כנ\"ל ונעשים בבחי' אותיות גשמיות כאבנים ועפר כו' להגן ולחסות על האדם [ל]בלתי יקרב אליו שום דבר רע בין ברוחניות בין בגשמיות. וז\"ש כי אמרתך ממש חייתני באור וחיות העליון דהיינו בבחי' מקיף כחומה שעשוי' להגן בתמידות אפי' בעידנא דלא עסיק בה כמ\"ש בשכבך תשמור עליך וכה\"ג כנ\"ל וד\"ל (ובאמת פי' חייתני היינו שאמרתך מחי' את נפשו בתוך תוכה בבחי' או\"פ כנ\"ל דמעיקרא עביד אינש אדעתא דנפשי' לתקן אור נשמתו כו', והן אותיות התו' שמתקשרי' בהן נש\"י בכלל ובפרט בכאו\"א כנ\"ל וכמ\"ש ואשים דברי בפיך דוקא, וכתי' כי על כל מוצא פי הוי'<sup data-n=\"11682\">959</sup> בדיבור בת\"ת<sup data-n=\"11683\">960</sup> בפה דוקא יחי' האדם וכמ\"ש ותורתך בתוך מעי<sup data-n=\"11684\">961</sup> שהתו' נק' מזון לנשמה ממש להחיותה בבחי' או\"פ ממש כי חיים הם למוצאיהם בפה<sup data-n=\"11685\">962</sup> דוקא.",[["11671","951","<b>יר\"ת. . מיר\"ע</b>: נסמן לעיל פ' בא קכה, ג."],["11672","952","<b>הכל נשמע</b>: חט: ליתא."],["11673","953","<b>ב\"ע </b>[חט: בן עזאי]<b>. . מלהטת סביבו</b>: ויק\"ר פט\"ז, ד."],["11674","954","<b>וכמ\"ש</b>: חט: וזהו."],["11675","955","<b>בהתהלכך תנחה אותך </b>[חט: ליתא]: משלי ו, כב."],["11676","*956","<b>מראב\"נ</b>: ח: מטושטש. ט: מרבה ב\"נ."],["11677","956","<b>ומבני עלי</b>: ראה ר\"ה יח, א רבה ואביי מדבית עלי קאתו וכו'. . משפחה אחת וכו'."],["11678","*957","<b>וחזקי' המלך</b>: ראה סנהדרין צד, ב. צה, א ובחידושי אגדות מהרש\"א ד\"ה מעונה של נוב."],["11679","957","<b>זאת נחמתי בעניי</b>: תהלים קיט, נ."],["11680","958","<b>אלקי עולם ברחמיך הרבים</b>: ברכת יוצר."],["11681","*959","<b>אמרתך הן אותיות התו'</b>: ראה גם לקמן פ' ויקהל תטז, ג. וש\"נ."],["11682","959","<b>כי על כל מוצא פי הוי'</b>: עקב ח, ג."],["11683","960","<b>בת\"ת</b>: חט: בד\"ת."],["11684","961","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["11685","962","<b>כי </b>[חט: כמו]<b> חיים הם למוצאיהם בפה</b>: משלי ד, כב. עירובין נד, א."]]],[2300540989,"<b>וזהו</b> טעם מצות ת\"ת בדיבור<sup data-n=\"11686\">963</sup> <span data-k=\"pg\">שמו</span> ּ דוקא בתמידות כמ\"ש ודברת בם<sup data-n=\"11687\">964</sup> וכתיב לא ימוש<sup data-n=\"11688\">965</sup> כו' [ש]זהו בעידנא דעסיק בה כו'<sup data-n=\"11689\">966</sup> ולא בעת שאינו מדבר בפה כו'. אבל הענין הוא דשניהם אמת דז\"ש כי אמרתך חייתני היינו ב' מדריגות דאור וחיות באו\"פ ואו\"מ להגן כמו חומה כמ\"ש אני חומה כו' וזהו פי' בשכבך כו' כנ\"ל וד\"ל).\n<b>אך</b><sup data-n=\"11690\">967</sup> הנה עכ\"פ מובן שעיקר [ענין] לימוד התורה הוא נמשך מצד הרח\"ר שמעורר ע\"ע כנ\"ל ע\"כ אח\"כ בזאת [ת]תנחם נפשו בעיניו והוא מ\"ש זאת נחמתי בעניי דוקא כי אמרתך חייתני כו', וא\"כ<sup data-n=\"11691\">968</sup> מה שהתו' נק' חומה זהו מצד הרחמנות לבד [ש]נמשך עי\"ז מגן על האדם עד שיהי' לו זאת התורה נחמתי בעניי לבד. ולכאו' יש לזה סתירה שהרי עיקר מצות ת\"ת הוא [ב]שמחה וחדוה<sup data-n=\"11692\">969</sup> כמ\"ש שש אנכי על אמרתיך<sup data-n=\"11693\">970</sup> כמוצא כו' וכן בעדותיך ששתי<sup data-n=\"11694\">971</sup> כעל כל הון כו' וכמ\"ש ונשמח בד\"ת כי הם חיינו<sup data-n=\"11695\">972</sup> כו' וה\"ז היפך הנ\"ל בזאת נחמתי בעניי דוקא כו'. אך הענין הוא דשניהם אמת, דהנה ידוע שהתורה [ש]היא מעץ החיים ירדה בעה\"ד טו\"ר לברר לרפ\"ח ניצוצין כו', וא\"א להיות בירור זה בין טו\"ר כ\"א בדבר שכבר נברר בעצם כמו חכ[ם] שכבר הוברר אצלו חכ' אחת יכול לברר ולתקן בה דבר המקולקל, כך התוה\"ק שכבר הוברר בעצם כנ\"ל נמשך למטה לברר לעה\"ד. וזהו שהתוה\"ק נק' אמת<sup data-n=\"11696\">973</sup> והוא בחי' החותם המבדיל בין פנימי' לחיצוני' כמו בכל רמ\"ח מ\"ע ושס\"ה ל\"ת שניתנו לישראל דוקא שנבחרו בזה בבחי' קבלת הפנימיות דתו\"מ שנק' אמת כמ\"ש כי יעקב בחר לו י\"ה<sup data-n=\"11697\">974</sup> כו' וכתי' ויקם עדות ביעקב<sup data-n=\"11698\">975</sup> דוקא כו', והן בחי' אותיות דתוש\"מ שאמר אז ראה ויספרה כו' עד תו' הנגלית לנו למטה. וז\"ש כי חק לישראל הוא דוקא והוא בכסא בר\"ה ויוכ\"פ שלפני ה' תטהרו דטה\"ע<sup data-n=\"11699\">976</sup> נמשך משם בחי' הפנימי' דתו\"מ כנ\"ל. ואמנם זהו שנמשך מצד [בחי'] הבחירה שברצון ותענוג העליון שהוא מלובש בתו\"מ בבחי' הפנימי' ע\"פ פנימי' דתוש\"מ ויש בזה ג' מדריגות מזון ולבוש ובית, דהיינו בחי' או\"פ כמזון ממש [כמו] ותורתך בתוך מעי ממש כנ\"ל (וה[י]א מה שבא[ה] בעה\"ד כו' למיימינים בה סמא דחיי<sup data-n=\"11700\">977</sup> כו'), וכמו המאכל שצריך לאכול בכל יום בוקר וערב<sup data-n=\"11701\">978</sup> וכדי שביעה לנפש כך מזון דתורה בקביעת עתים בוקר וערב כמו פרק א' שחרית<sup data-n=\"11702\">979</sup> כו' וק\"ש בקר וערב<sup data-n=\"11703\">980</sup> כידוע שזהו",[["11686","963","<b>מצות ת\"ת בדיבור</b>: נסמן לעיל פ' וארא פ, ג."],["11687","964","<b>ודברת בם</b>: ואתחנן ו, ז."],["11688","965","<b>לא ימוש</b>: יהושע א, ח."],["11689","966","<b>כו'</b>: חט: דוקא."],["11690","967","<b>אך</b>: שם: אבל."],["11691","968","<b>וא\"כ</b>: שם: והוא."],["11692","969","<b>מצות ת\"ת הוא בשמחה וחדוה</b>: ראה שו\"ע אדה\"ז או\"ח מהדו\"ק ס\"א, ס\"ח. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>. פל\"א. מאמרי אדה\"א קונטרסים ע' רעא."],["11693","970","<b>שש אנכי על אמרתיך</b>: תהלים קיט, קסב. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680443\" data-slug=\"torat-chaim\" data-id=\"2300680443\">תו\"ח מקץ רכו, א</a>."],["11694","971","<b>בעדותיך ששתי</b>: תהלים קיט, יד [ושם: בדרך עדותיך — ראה גם תו\"ח מקץ שם]."],["11695","972","<b>ונשמח. . הם חיינו</b>: ברכות ק\"ש ערבית [בדילוג]."],["11696","973","<b>שהתוה\"ק </b>[חט: שהתורה]<b> נק' אמת</b>: מלאכי ב, ו."],["11697","974","<b>כי יעקב בחר לו י\"ה</b>: תהלים קלה, ד."],["11698","975","<b>ויקם עדות ביעקב</b>: תהלים עח, ה."],["11699","976","<b>שלפני ה' תטהרו דטה\"ע</b>: נסמן לעיל פ' בא קכג, ג."],["11700","977","<b>למיימינים בה סמא דחיי</b>: שבת פח, ב."],["11701","978","<b>לאכול. . בוקר וערב</b>: בשלח טז, ח. סידור שער התפלה כ, ג."],["11702","979","<b>פרק א' שחרית</b>: מנחות צט, ב."],["11703","980","<b>וק\"ש בקר וערב</b>: ראה שו\"ע אדה\"ז הל' ק\"ש רסנ\"ח."]]],[2300540994,"בשכבך ובקומך<sup data-n=\"11704\">981</sup> כו' כמ\"ש בסידור<sup data-n=\"11705\">982</sup> בענין מזו\"ן ולבו\"ש ובי\"ת כו'. ובחי' לבוש דתו' שזהו בחי' או\"מ דתורה שמקיף לנשמה מראש לרגל כמ\"ש עוטה אור כשלמה<sup data-n=\"11706\">983</sup> וכן לבושי' כתלג<sup data-n=\"11707\">984</sup> כו' ונק' לבוש מל' כמ\"ש ה' מלך גיאות לבש<sup data-n=\"11708\">985</sup> כו' ה' עוז דתו'<sup data-n=\"11709\">986</sup> כמ\"ש במ\"א ע\"פ יביאו לבוש מל'<sup data-n=\"11710\">987</sup> כו' והיינו אור דתוה\"ק שהוא בבחי' עה\"ח כו' כמ\"ש כבוד ה' יאספך<sup data-n=\"11711\">988</sup> לנשמות בג\"ע כידוע במ\"ש ותלבש אסתר מל'<sup data-n=\"11712\">989</sup>. ובחי' בית היינו בחי' מקיף למקיף ששורה על הנשמות בהיכל ק\"ק<sup data-n=\"11713\">990</sup> ונק' בית ה' היכל ה' כמ\"ש במ\"א לע\"ל היכל ה' המה כו' (ובהיכל ק\"ק וכן היכלות הפנימי' שבג\"ע כמ\"ש במ\"א. וז\"ש אל חדר הורתי<sup data-n=\"11714\">991</sup> כו' וז\"ש שבתי בבית ה' כו' כנ\"ל. ובחי' חומה זהו מקיף הכללי שמקיף לכל הבתים והיכלות שבירושלי' ש\"מ שנק' עיר אלקינו כו', המגביל ומגין מן החיצוני' כמו ובשכבך כו' אפי' בעידנא <span data-k=\"pg\">694</span> ּ דלא עסיק בה כו', וזהו בחי' רח\"ר שנמשך ממקיף הכללי דאותיות התורה הקדומה שהובררה כבר כנ\"ל. וזהו אני חומה זו תורה ושדי כמגדלות בחי' פנימי' התוה\"ק שנמשך למטה שנק' אמת בבחי' חותם פנימי שנק' חותם בתוך חותם כו' כנ\"ל וד\"ל.\n<b>וזהו</b> זאת נחמתי בעניי זאת התו' שניתנה לישראל בג' מדריגות דמזון ולבוש ובמקיף דחומה הכל להיות להגן בר\"ר מפני יראת החיצוני' שיכולים לקבל בעניו דוקא שהוא בהיות כנ\"י בבחי' הקטנות דעני מן הדעת<sup data-n=\"11715\">992</sup> כו', כמו בזמן הגלות שנק' שינה וכה\"ג שזהו בשכבך כו'. אך אז אמרתך חייתני באו\"פ ומקיף להגן (וכן לאחר התפלה שהוא כעני כמ\"ש תפלה לעני כי יעטוף<sup data-n=\"11716\">993</sup> כו' שלפני ה' ישפוך שיחו ונק' שפיכת נפש<sup data-n=\"11717\">994</sup> כידוע אז אמרתך חייתני בעניי כו' כידוע). אבל הנה מדריג' הב' בתורה, היינו כמו שהוא בבחי' ההתכללו' בעונג ושעשועים העצמיים דעצמות אוא\"ס ב\"ה ממש טרם שירדה למטה ב[א]בי\"ע כו' כמ\"ש ואהי' אצלו אמון אמון מוצנע כו' שעשועי' יום יום כו', והן כמו הנגינ[ות] וטעמים שבתורה שנק' שירו כמ\"ש ויהי שירו<sup data-n=\"11718\">995</sup> כו', שהוא בחי' מקיף דשעשועי' העליונים שנק' שעשועי המלך בעצמותו שירד להשתעשע באור החכ' הקדומה דתוה\"ק. וע\"כ בחי' העונג העליון שבקריאת התורה בנגינות וטעמים הוא בבחי' העלם ומקיף בעונג העצמי ממש שלמעלה מבחי' הגבלת האותיות דתורה לגמרי (שמפני זה לא נדרש שום דרש בטעמים רק בנקודות יש דרש ועל כל קוץ ותג<sup data-n=\"11719\">996</sup> כו' כמ\"ש במ\"א). וזהו",[["11704","981","<b>בשכבך ובקומך</b>: ואתחנן ו, ז. עקב יא, יט."],["11705","982","<b>כמ\"ש בסידור</b>: שבהערה 978."],["11706","983","<b>עוטה אור כשלמה</b>: תהלים קד, ב."],["11707","984","<b>לבושי' כתלג</b>: דניאל ז, ט."],["11708","985","<b>ה' מלך גיאות לבש</b>: תהלים צג, א."],["11709","986","<b>כו' </b>[חט: לבש]<b> ה' עוז דתו'</b>: ראה לעיל קפג, ג. וש\"נ."],["11710","987","<b>יביאו לבוש מל'</b>: תו\"א מג\"א צ, א."],["11711","988","<b>כבוד ה' יאספך</b>: ישעי' נח, ח."],["11712","989","<b>ותלבש אסתר מל'</b>: אסתר ה, א. ראה שה\"א מב, ב. מאמרי אדה\"א נ\"ך ע' תסז. וש\"נ."],["11713","990","<b>ק\"ק</b>: חט: ליתא."],["11714","991","<b>אל חדר הורתי</b>: שה\"ש ג, ד [ושם: ואל]."],["11715","992","<b>דעני מן הדעת</b>: ראה כתובות סח, א. נדרים מא, א."],["11716","993","<b>תפלה לעני כי יעטוף</b>: תהלים קב, א."],["11717","994","<b>תפלה. . שפיכת נפש</b>: ראה ר\"ש פאה פ\"א, מ\"א (ד\"ה וגמילות חסדים). פע\"ח בתחלתו. מאמרי אדה\"א דברים ח\"ב ע' תרסט. וש\"נ."],["11718","995","<b>ויהי שירו</b>: נסמן לעיל פ' בא קט, ד."],["11719","996","<b>שום דרש בטעמים. . בנקודות. . קוץ ותג</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תע. וש\"נ. שמות ח\"א ע' לב וע' ע."]]],[2300540999,"ענין השמחה והתענוג שבמצות קריאת התו' כמו שאמר דוד זמירות היו לי חוקיך<sup data-n=\"11720\">997</sup> כו' (ומה שנענש ע\"ז לפי שעשה כדי להצילו מן האויב כמ\"ש בבית מגורי<sup data-n=\"11721\">*998</sup> כמ\"ש במ\"א), וכמו אני תורתך שעשעתי<sup data-n=\"11722\">998</sup> כו' וכן שש אנכי על כו' כנ\"ל שזהו למעלה הרבה מבחי' המקיף דחומה שאינה רק להגן בבחי' הר\"ר שהוא כעני לבד כו' וד\"ל.\n<b>ומעתה</b> יובן יותר מ\"ש למעלה בענין פרזות תשב ירושלים כו' [ש]לע\"ל יהי' ישיבת ירושלים בלי גבול כלל כמא' שעתידה ירושלים שתתפשט בכל א\"י וא\"י בכל העולם כו' ע\"כ פרזות תשב בלי היקף חומה המגביל יושבי' [כלל] כו'). והענין הוא כנ\"ל שיהי' התגלות אור העצמו' דא\"ס ממש שלמעלה מעומ\"ר ועומ\"ת כו', וע\"כ לא יהי' עליות וירידות כלל כעכשיו בקו\"ח ומקיף הכללי [ד]שה\"ש כו', לפי שיהי' בבחי' יש מיש<sup data-n=\"11723\">999</sup> כו', וע\"כ גם בזמן ומקום לא יהי' גבול והיינו פזרונו ופרזונו שהוא ע\"י הקיבוץ מע\"ש בבזבוז האוצרות כו' בגמר הניצוח כו'. וזהו פרזות תשב ירושלים בלי חומה דתורה כנ\"ל, משום דבחי' מקיף דתו\"מ באותיות<sup data-n=\"11724\">1000</sup> התוה\"ק הנ\"ל זה בא מעומ\"ר לעו[מ]\"ת בהמשכה בבחי' מקיף דרח\"ר על השפל ביותר כמ\"ש זאת נחמתי בעניי דוקא כנ\"ל, וצריך להגן מן האויב המקטרג כו'. אבל לע\"ל יהי' גילוי אורות השעשועי' העצמיי' שבתוה\"ק כנ\"ל שלמעלה מבחי' האותיות שבה (שזהו ענין ש\"ת שהתורה עצמה היא בשמחה עליונה שבמקיף דשעשועי' העצמי' שלמעלה גם משעשועי' שהי' בתוה\"ק בתחלה מצד שלימות דח\"ע <span data-k=\"pg\">שמז</span> ּ בסוף מעשה דוקא כמ\"ש במ\"א (בפי' תוצל\"מ<sup data-n=\"11725\">1001</sup> כו') שכולו פנימי' ואין שם בחי' חומה המגביל בין בחי' פנימי' לחיצוני' ממש כנ\"ל. ומ\"ש יבחר לנו כו' לע\"ל זהו במקיף העליון שלמעלה מע\"ס דכח\"ב ומדות כו' שיהי' קדוש[ת] ירושלים כא\"י דעכשיו למעלה מקדושת א\"י דלע\"ל שהוא ת' עלמין [דכסופין] וכה\"ג שיהי' בעדן עצמו שנק' ארץ החיים לע\"ל), ולפ\"ז הרי יהי' בירושלים [דלע\"ל] עשירות גדולה [וגדולה] ית[י]ר[ה] מכל הון יקר הע[ליון] שבשעשועי' העליונים כנ\"ל בענין שמחת עולם ומכל הון יקר שבקיבוץ וביריד'<sup data-n=\"11726\">1002</sup> דע\"ש שהוא בחי' עולם התענוג עצמו<sup data-n=\"11727\">1003</sup> דלע\"ל שיקובץ בנ\"י<sup data-n=\"11728\">1004</sup> לתוכה בשמחת עולם הא\"ס כו'. ולזאת לא יתכן אז",[["11720","997","<b>זמירות היו לי חוקיך</b>: נסמן לעיל קפג, א."],["11721","*998","<b>נענש. . בבית מגורי</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680292\" data-slug=\"torat-chaim\" data-id=\"2300680292\">תו\"ח מקץ ריט, ד</a>."],["11722","998","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע."],["11723","999","<b>מיש ליש</b>: ראה גם הנסמן לעיל קנט, ב."],["11724","1000","<b>דתו\"מ באותיות</b>: חט: דחומה דאותיות."],["11725","1001","<b>תוצל\"מ</b>: שם: תורה צוה לנו משה — ברכה לג, ד. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תקכה הערה 18. דרושי חתונה ח\"ב ע' תקכו בהערה. פלח הרמון שה\"ש ע' פו."],["11726","1002","<b>וביריד'</b>: חט: ובירור."],["11727","1003","<b>עולם התענוג עצמו</b>: ח: ענין ת\"ע. ט: עצמיות התענוג העליון."],["11728","1004","<b>בנ\"י</b>: ח: ליתא. ט: בני'."]]],[2300541004,"שיהי' חומה לירושלים מאבנים לתקן<sup data-n=\"11729\">1005</sup> מצד [ה]רחמנות מאחר שיהי' גילוי העצמי' דא\"ס למטה כמו למעלה ממש, ואין עניות כלל במקום עשירות<sup data-n=\"11730\">1006</sup> גדולה כזאת שתפול בו ענין רח\"ר ולא ענין המשכות מלמעלה למטה להגן כנ\"ל, וא\"כ לא יצטרכו לחומה דתו[רה] ג\"כ רק פרזות תשב כנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין י\"ל מ\"ש [ו]אני אהי' לה חומת אש סביב שיהי' בחי' חומה דאש האלקי העליון להגן ולהבדיל<sup data-n=\"11731\">1007</sup> או להאיר אור כנ\"ל, ומבואר למעלה שזה יהי' ממדריגות אור הע[צמי'] דא\"ס ממש כמ\"ש ואני אהי' לה חומת אש כו' אני ממש, וגם מ\"ש ולכבוד אהי' בתוכה כו'. והנה יש להקדים לזה ענין א' והוא מה שידוע שהתו' ניתנה באש שחורה<sup data-n=\"11732\">1008</sup> ע\"ג אש לבנה כו'. וביאור ענין ב' מיני אש הללו שחורה ולבנה ידוע מענין נר הוי' נשמת אדם<sup data-n=\"11733\">1009</sup> שכלולה מב' נהורין נה\"ע נק' נהורא חיוורא שהאור העליון לבן ובהיר ונק' אור בהיר המאיר להיות[ו] מאור העליון דבחי' החסדים דשם הוי' ובחי' נהורא אוכמא<sup data-n=\"11734\">1010</sup> אש שחורה שבאה בהתלבשות בגוף לברר לנה\"ט נק' אור השורף כו' (וכמו\"כ בכללות יותר בשרש נש\"י שעלו במחה\"ק בפנימי' ועצמו' ד[א]א\"ס שלפני הצמצום כו', וזהו אור הע[ליון] בחי' אור המאיר שנק' נה\"ע ונק' צ\"ע כאבן דשוהם<sup data-n=\"11735\">1011</sup> כידוע ונש\"י [ש]נמשכו מזו\"נ בבי\"ע לברר לעה\"ד טו\"ר<sup data-n=\"11736\">1012</sup> נק' אור השורף אור<sup data-n=\"11737\">1013</sup> אוכמא כו', וזהו ישפה צ\"ת<sup data-n=\"11738\">1014</sup> וזהו אשה אש ה'<sup data-n=\"11739\">1015</sup> כי מאיש<sup data-n=\"11740\">1016</sup> אש יו\"ד<sup data-n=\"11741\">1017</sup> דנהורא חיורא לוקחה כו' וד\"ל). וכך הוא באור דתורה בב' מדריגות דאור כנ\"ל (דג' קשרים הן נש\"י סתים וגליא שהן ב' אורות הנ\"ל ואורייתא סתים וגליא וקוב\"ה סתים וגליא), והוא ענין אש לבנה ואש שחורה, דבחי' אור דתוה\"ק שא' [בה] עוטה אור כו' וכן יהי אור<sup data-n=\"11742\">1018</sup> כו' אור המאיר והוא בחי' אש הוי' שבבחי' החסדים דמקור הח\"ע שנק' תושמ\"ע<sup data-n=\"11743\">1019</sup> כמ\"ש מימינו אש דת למו<sup data-n=\"11744\">1020</sup> מימינו דוקא שהוא נמשך בבחי' חסד<sup data-n=\"11745\">1021</sup> מלמעלה למטה דוקא וכמ\"ש [ו]תורת חסד<sup data-n=\"11746\">1022</sup> כו', וכמ\"ש<sup data-n=\"11747\">1023</sup> קול ה' חוצב להבות אש<sup data-n=\"11748\">1024</sup> כו' דמשמע כלהב אש העולה מלמטה למעלה דוקא וכמ\"ש קול אלקי' שמענו מתוך האש<sup data-n=\"11749\">1025</sup> כו'. והענין הוא דבמ\"ת הי' בחי' התכללות דאש שחורה דבחי' הגבורה העולה מלמטלמ\"ע<sup data-n=\"11750\">1026</sup> באש לבנה שיורד מלמעלה כמ\"ש והר סיני עשן<sup data-n=\"11751\">1027</sup> כו' (כמ\"ש במ\"א).",[["11729","1005","<b>לתקן</b>: ח: והון יקר. ט: ליתא."],["11730","1006","<b>ואין עניות. . במקום עשירות</b>: שבת קב, ב."],["11731","1007","<b>ולהבדיל</b>: חט: ולהגביל."],["11732","1008","<b>שהתו' ניתנה באש שחורה</b>: ראה רש\"י שה\"ש ה, טז [ד\"ה שחורות]. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקעח."],["11733","1009","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["11734","1010","<b>נהורא חיוורא. . נהורא אוכמא</b>: ראה זהר בראשית נא, רע\"א. ש\"א לד, ב ואילך."],["11735","1011","<b>צ\"ע כאבן דשוהם</b>: ראה לעיל פ' שמות ז, א. וש\"נ."],["11736","1012","<b>טו\"ר</b>: חט: ליתא."],["11737","1013","<b>אור</b>: שם: אשא."],["11738","1014","<b>ישפה צ\"ת</b>: ראה לעיל פ' שמות ז, א. וש\"נ."],["11739","1015","<b>אשה אש ה'</b>: ראה סוטה יז, א. זהר בראשית מח, ב. ביאוה\"ז נח ז, ב. מאמרי אדה\"א שבהערה 1017."],["11740","1016","<b>כי מאיש. . לוקחה</b>: בראשית ב, כג."],["11741","1017","<b>מאיש אש יו\"ד</b>: ראה סוטה שם. פרדס (שער ערה\"כ) שכ\"ג מערכת אשה. מאמרי אדה\"א במדבר ח\"ג ס\"ע א'רס ואילך (ובהנסמן בריש המאמר שם). ע' א'רסג ואילך."],["11742","1018","<b>יהי אור</b>: בראשית א, ג."],["11743","1019","<b>תושמ\"ע</b>: ח: חכ' ש\"מ."],["11744","1020","<b>מימינו אש דת למו</b>: ברכה לג, ב."],["11745","1021","<b>חסד</b>: חט: עה\"ד."],["11746","1022","<b>[ו]תורת חסד</b>: משלי לא, כו."],["11747","1023","<b>וכמ\"ש</b>: חט: וכתיב."],["11748","1024","<b>קול ה' חוצב להבות אש</b>: תהלים כט, ז."],["11749","1025","<b>קול אלקי' שמענו מתוך האש</b>: ואתחנן ה, כא [ושם: ואת קולו שמענו]. ד, לג [ושם: קול אלקים מדבר]."],["11750","1026","<b>מלמטלמ\"ע</b>: חט: מלמטה."],["11751","1027","<b>והר סיני עשן</b>: יתרו יט, יח. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' שלה. ע' שמו ואילך. ע' תסא ואילך. ע' תשצד."]]],[2300541009,"<b>וביאור</b> הענין הנה ידוע שיש באש ואור ב' הפכים דאו\"ח ואו\"י, וזהו מ\"ש בס\"י הוציא אש ממים ומים מאש<sup data-n=\"11752\">1028</sup> כו' וכמ\"ש אש אוכלת ואש שותה<sup data-n=\"11753\">1029</sup> כו', [ו]כמו שאנו רואים <span data-k=\"pg\">696</span> ּ בחוש שיש ברשפי אש הלהב ב' הפכיי' דרו\"ש שעולה ויורד וחוזר ועולה כו' וכמ\"ש והחיות רו\"ש כמראה הבזק<sup data-n=\"11754\">1030</sup> שזהו כלהב [היוצא] מחרסי'<sup data-n=\"11755\">1031</sup> שעולה ויורד כו'. וכמו הנש[י]מה בלב האדם בא<sup data-n=\"11756\">1032</sup> ברוח החיים שיוצא מן הלב וחוזר ונכנס, כך יש בחי' רוח העולה ויורד פי' שיוצא מכלי גופו<sup data-n=\"11757\">1033</sup> שבלב כמו בצמאון והתשוקה האלקי' שעולה בהתלהבות אלקי' שיוצא מכלי גופו למעלה וחוזר ויורד ומתיישב בלב, שזהו חמימות רשפי אש אלקי המתיישב להיות כמו אור וחיות בלבו בהתגלות לבו בתשוקה ותשוקה<sup data-n=\"11758\">1034</sup> זו המורגשת, עד שזהו כמו חיות המזון [ל]נפש רעיבה כו' וכמים לצמא המשיב את הנפש ורוח כו', והוא בחי' מים שבאש שיורד מלמעלה למטה היפך ההסתלקו' דאש העולה כו'. ואמנם אחר ההסתלקו' דאש דאו\"ח נמשך אש דאו\"י והא בהא תליא והיו לאחדים ממש, כנראה בחוש באור הנר דאש הלבן נאחז באש השחור וסיבת אור המאיר תלוי באש השורף כו'. וכך הי' באש הקרבנות דאש השורף שמביא מן ההדיוט ממשיך אש העליון שיורד מלמעלה<sup data-n=\"11759\">1035</sup> למטה לאכול הקרבן, וכמו במעשה דאליהו<sup data-n=\"11760\">1036</sup> שנפלה אש ה' מן השמים ותאכל העולה כו' הרי יש אש [ה]יורד מגבוה לנמוך שנק' אש ה' כו' והוא כמו בחי' שוב [כ]אש דחיות הקדש שהוא בחי' רו\"ש כו' כנ\"ל (ואמנם מבואר במ\"א ששרש האש השחורה ששורף שעולה בלהב בבחי' או\"ח למעלה כו' הוא גבוה משרש האש הלבן<sup data-n=\"11761\">1037</sup> היו\"ד<sup data-n=\"11762\">1038</sup> כו' והוא בחי' אויר העליון שלמעלה מ[ן ה]אור שהוא עצם חשוך<sup data-n=\"11763\">*1039</sup> וממנו מקור מציאות האור כו'). ויובן זה ג\"כ באוי\"ר שבתפלה שאהבה הוא בחי' רץ לבך<sup data-n=\"11764\">1039</sup> ברשפי אש התשוקה העולה למעלה ומיד אחר הרצוא בחי' השוב בחי' ההמשכה בגילוי אלקות להשיב את הנפש שמתיישב בלב לאור וחיות, והוא בעסק התו\"מ כמו הצמא שמרווה צמאו[נו] במים כנ\"ל. וזהו ג\"כ התכללות דב' אורות [ד]נש\"י [ש]נק' נר הוי' באו\"ח ואו\"י יחד כנ\"ל, וזהו ואהבת גימ' ב\"פ אור<sup data-n=\"11765\">1040</sup> כידוע, וזהו רשפיה רשפי אש שלהבת י\"ה<sup data-n=\"11766\">1041</sup> בצמצום והתפשטות כמו הנשימה [ש]באף וחוטם בעת השינה.",[["11752","1028","<b>הוציא אש ממים ומים מאש</b>: נסמן לעיל פ' שמות מה, ג."],["11753","1029","<b>אש אוכלת ואש שותה</b>: ראה יומא כא, ב. ראה גם לקמן פ' ויקהל שצה, סע\"ב."],["11754","1030","<b>והחיות רו\"ש כמראה הבזק</b>: יחזקאל א, יד."],["11755","1031","<b>כלהב [היוצא] מחרסי'</b>: ראה חגיגה יג ב וברש\"י שם."],["11756","1032","<b>בא</b>: חט: ליתא."],["11757","1033","<b>פי' שיוצא מכלי גופו</b>: ח: כאש. ט: באש."],["11758","1034","<b>בתשוקה ותשוקה</b>: ח: בתשוקה וחשק. ט: בחשק ותשוקה."],["11759","1035","<b>דאש. . מן ההדיוט. . אש. . שיורד מלמעלה</b>: תו\"כ ויקרא א, ז. ערובין סג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ. וראה גם לעיל קסב, א."],["11760","1036","<b>במעשה דאליהו</b>: מל\"א יח, לח. ראה גם לקמן פ' ויקהל שצה, ב ובהערה 97."],["11761","1037","<b>האש השחורה. . גבוה. . האש הלבן</b>: ראה גם לקמן רלט, ג. אמ\"ב שער הציצית צב, א. ש\"א מג, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תמה (ובהנסמן שם)."],["11762","1038","<b>היו\"ד</b>: חט: היורד."],["11763","*1039","<b>אויר. . עצם חשוך</b>: ראה גם לקמן פ' ויקהל שצד, ב. וש\"נ."],["11764","1039","<b>רץ לבך</b>: נסמן לעיל קסד, ג."],["11765","1040","<b>ואהבת גימ' ב\"פ אור</b>: נסמן לעיל פ' וארא סה, ג."],["11766","1041","<b>רשפיה. . שלהבת י\"ה</b>: שה\"ש ח, ו."]]],[2300541014,"<b>אך</b> הנה ידוע דשרש רו\"ש שעולה מלמטלמ\"ע מן המקבל אל המשפיע נמשך מבחי' מטי ולא מטי<sup data-n=\"11767\">1042</sup>, מטי תחלה ואח\"כ לא מטי התפשטות תחלה ואח\"כ הסתלקו' (כנשימה שבחוטם כו' בהקיץ כו'), וכמו ורוח אלקי' מרחפת נוגע ואינו נוגע<sup data-n=\"11768\">1043</sup> כו' שזהו מן המשפיע אל המקבל דוקא שנמשך בבחי' החסד תחלה, כמו שרואים בחוש בתיאובתא דדכורא לגבי נוק'<sup data-n=\"11769\">1044</sup> הגם שהוא באש וחום התאוה, אבל נמשך כמים בהתפשטו' [ו]מדובק באהבה כמו וימינו תחבקני<sup data-n=\"11770\">1045</sup> כו' ואח\"כ הנשיקה בהתלהבות העולה מהבל הלב. וכמו\"כ בשעשועי' דאב לבנו יחידו שמחבקו ומנשקו שזהו עיקר התענוג והשעשועים<sup data-n=\"11771\">1046</sup> דזהו חו\"ג שבתענוג העצמי (בל\"א דער קוועל אין תענוג כמו ברו\"ש דאהבה שבלב), כידוע ומבואר במ\"א בענין השעשועי' ב' פעמי' ש\"ע<sup data-n=\"11772\">1047</sup> דהיינו חו\"ג שבתענוג. כי פי' ש\"ע לשון הטייה והזזה ממקומו וכמו וישע ה' אל הבל<sup data-n=\"11773\">1048</sup> כו', וכמו הנענוע שמנענע א\"ע בבחי' רו\"ש עלי' וירידה, אמנם הטי' והתפשטות התענוג (בל\"א צו זיך) תחלה ואח\"כ ברשפי אש להב תענוג העולה למעלה (פון זיך), וכנראה ענין עצם השעשועי' דתענוג דמשפיע שכלול מחו\"ג באופן זה דוקא <span data-k=\"pg\">שמח</span> ּ כמו כל תענוג[י] עוה\"ז שיתענג ומשתעשע כמו בכלי יקר ואבני חפץ או מרחיצה וסיכה וכל מיני מעדנים וכה\"ג). אבל בתשוקה והתענוג של המקבל למשפיע כתיאובתא דנוק' לדכורא<sup data-n=\"11774\">1049</sup> בא תחלה ברשפי אש דהסתלקות בחי' גבורה שבתענוג, שהוא בחי' הצמאון שבתשוקה וחמדת הלב חוץ ממנו (כמו נכספה וגם כלתה נפשי<sup data-n=\"11775\">1050</sup> ), והיא תשוקת האשה אל אישה כמ\"ש ואל אישך תשוקתך<sup data-n=\"11776\">1051</sup> שהוא בחי' אש העולה כרצוא הנ\"ל ואח\"כ מתיישב בה התשוקה והעונג, וכמו אתבסמת נוק'<sup data-n=\"11777\">1052</sup> דעביד נייחא לה כו' כמ\"ש במ\"א. ונמצא דרו\"ש שבמקבל נעשה מן בחי' מטול\"מ דמשפיע בהיפוך, שמבחי' רצוא דמקבל נעשה בחי' שוב במשפיע ומבחי' מטי דמשפיע נעשה רצוא דמקבל וכה\"ג וד\"ל.\n<b>והנה</b> [ה]דוגמא מזה מובן באוי\"ר [ש]במצות ת\"ת דאורייתא בלא דו\"ר<sup data-n=\"11778\">1053</sup> לא פרחא לעילא, וכידוע שזהו היפוך בחי' אוי\"ר שבתפלה בבחי' רו\"ש שהוא כמו בחי' [ה]צמאון דבחי' או\"ח דמ\"נ<sup data-n=\"11779\">1054</sup> דנוק' לדכורא כנ\"ל. אבל בעסק התו' שזהו בחי' ירידות האור והשפע מ\"ד דדכורא לנוק', שהוא דבר ה' ממש בתנ\"ך",[["11767","1042","<b>רו\"ש. . מטי ולא מטי</b>: ראה גם לעיל פ' וארא סג, ד. וש\"נ."],["11768","1043","<b>ורוח אלקי' מרחפת נוגע ואינו נוגע</b>: בראשית א, ב. ראה ב\"ר פ\"ב, ד. רש\"י האזינו לב, יא."],["11769","1044","<b>בתיאובתא דדכורא לגבי נוק'</b>: נסמן לעיל פ' בא קו, ב."],["11770","1045","<b>וימינו תחבקני</b>: שה\"ש ב, ו. ח, ג."],["11771","1046","<b>התענוג והשעשועים</b>: חט: השעשועים."],["11772","1047","<b>בענין השעשועי' </b>[ח: בפי' שעשועי'. ט: ליתא]<b> ב' פעמי' ש\"ע</b>: ראה מאמרי אדה\"א קונטרסים ע' תקנה. וש\"נ. שם ע' תקעא. שע\"ת יד, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680090\" data-slug=\"torat-chaim\" data-id=\"2300680090\">תו\"ח תולדות קנ, א</a>."],["11773","1048","<b>וישע ה' אל הבל</b>: בראשית ד, ד."],["11774","1049","<b>כתיאובתא דנוק' לדכורא</b>: נסמן לעיל פ' בא קו, ב."],["11775","1050","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["11776","1051","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["11777","1052","<b>אתבסמת נוק'</b>: ראה זהר לך צד, א. ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ע' תצד (נוסחא שני'). מאמרי אדה\"א במדבר ח\"א ע' יב ואילך. ח\"ב ס\"ע תקא ואילך. ויקרא ח\"א ע' ל."],["11778","1053","<b>דאורייתא בלא דו\"ר</b>: ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא</a> פל\"ט: בתיקונים. ת\"ז ת\"י (כה, ב)."],["11779","1054","<b>דבחי' או\"ח דמ\"נ</b>: חט: בבחי' מ\"ן."]]],[2300541019,"והלכות וכמ\"ש ודברי אשר שמתי בפיך<sup data-n=\"11780\">1055</sup> כו' וכתיב כאשר ירד הגשם<sup data-n=\"11781\">1056</sup> כו' וכן דברי אשר<sup data-n=\"11782\">1057</sup> כו' וכתי' הלא דברי כאש<sup data-n=\"11783\">1058</sup> כו' וכמו במ\"ת שהי' קול אלקי' מדבר מתוך האש, והי' בזה בחי' מטול\"מ תחלה בחי' החסד שבתענוג העצמי דמשפיע שנתלבש בחכ' דתו' להשפיע לכנ\"י כמו שהי' שעשועי' העצמי' דתוה\"ק דב\"פ ש\"ע בחי' החסד שבתענוג בהתפשטות קודם כו', וזה[ו] שירד בה\"ס בחי' אש הוי' דא\"ס, אך אח\"כ לא מטי הולך ועולה למעלה כמו בהבל הדבור דתו'<sup data-n=\"11784\">1059</sup> שיש בו עלי' וירידה. ודוגמא זו יש בכל איש העוסק בתו' שדבר ה' יוצא מפיו כ[י] יושב ושונה כנגדו<sup data-n=\"11785\">1060</sup> כמו ב\"ע שא' שנפשו חשקה בתו'<sup data-n=\"11786\">1061</sup> כמ\"ש באהבתה תשגה תמיד<sup data-n=\"11787\">1062</sup> וכתי' כ\"א בתורת ה' חפצו<sup data-n=\"11788\">1063</sup> ובתורתו יהגה כו' וכה\"ג, זהו בחי' או\"י<sup data-n=\"11789\">1064</sup> דתענוג בבחי' ההמשכה והתפשטות (צו זיך) שיחפוץ לדבקה נפשו בתורת ה' (כמ\"ש בב\"ע כשהי' שונה הי' אש מלהטת סביבו, והוא בחי' אש דאור דתו' כמו שניתנה בה\"ס דכתי' מימינו אש דת למו כו'. ויש בו גם בחי' ההסתלקות וכמו חוצב להבות [אש] כו', והוא מה שעל כ\"ד פרחה נשמתן<sup data-n=\"11790\">1065</sup> דהיינו על כל בחי' המשכה דקול אלקי' באש העליון בדיבור דאנכי פ\"נ ליכלל באש העולה בבחי' רצוא כנ\"ל, דרצוא דמקבל נמשך מבחי' החסד ותענוג דמשפיע (רק שטל תו' החי' אותם<sup data-n=\"11791\">1066</sup> ) בבחי' שוב. והוא שא' כל העוסק בתורה טל תו' מחייהו<sup data-n=\"11792\">1067</sup> והוא כמו התענוג<sup data-n=\"11793\">1068</sup> שבתו' שמשיב את הנפש בהמשכת העונג דמקיף דכתר תורה (אך כמו שניתנה תורה באש שחורה ע\"ג אש לבנה כנ\"ל צ\"ל תחלה בחי' רצוא דתשוקה ליכלל ולידבק נפשו באותיות דתו' ואח\"כ אש לבנה בעונג היורד כמו אני תורתך שעשעתי מלמטלמ\"ע שהוא היפוך דשעשועי' ומטול\"מ במשפיע הנ\"ל וד\"ל).\n<b>אך</b> הנה כ\"ז בבחי' או\"י ואו\"ח דמשפיע ומקבל כנ\"ל שבחי' רו\"ש דמקבל היפוך מטול\"מ דמשפיע כנ\"ל, והטעם הוא כידוע שבחי' ההשתל' דעו\"ע זהו בהמשכות דמשפיע מאין ליש כמו והחכ' מאין ליש תמצא וכן מחכ' לבינה ומבינה למדות וממדות לדיבור כו', וע\"כ בחי' העלאה דמקבל הוא [ב]בחי' ביטול היש לאין שזהו רצוא <span data-k=\"pg\">698</span> ּ [ש]קודם לשו\"ב כנ\"ל. וכך הוא גם באוי\"ר דתורה [ב]בחי' חו\"ג דשעשועים<sup data-n=\"11794\">1069</sup> שנק' שעשועי דאורייתא כנ\"ל, לפי שבא גם אור דתורה בהשתלשלו' מאין ליש מן המשפיע אל המקבל כמו במ\"ת שבאור פניך נתת לנו<sup data-n=\"11795\">1070</sup> כו' וכאור השעשועי' בתוה\"ק כנ\"ל וד\"ל. אבל לע\"ל יהי' גילוי אור",[["11780","1055","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["11781","1056","<b>כאשר ירד הגשם</b>: ישעי' נה, י."],["11782","1057","<b>וכן </b>[חט: כן]<b> דברי אשר</b>: ישעי' שם, יא [ושם: כן יהי' דברי]."],["11783","1058","<b>הלא דברי כאש</b>: ירמי' כג, ט [ושם: הלא כה דברי — ראה לקמן פ' ויקהל תמ, ד. מאמרי אדה\"א שמות ח\"א ע' יח. וש\"נ]."],["11784","1059","<b>דתו'</b>: חט: דד\"ת."],["11785","1060","<b>יושב ושונה כנגדו</b>: נסמן לעיל פ' וארא נח, ג."],["11786","1061","<b>ב\"ע </b>[ח: בן עזאי]<b> שא' שנפשו חשקה בתו'</b>: ראה יבמות סג, ב. סוטה מט, א (במשנה). לקמן פ' תצוה שעח, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670303\" data-slug=\"torat-chaim\" data-id=\"2300670303\">תו\"ח נח נ, ג</a> ובהערה 42."],["11787","1062","<b>באהבתה תשגה תמיד</b>: משלי ה, יט."],["11788","1063","<b>כ\"א בתורת ה' חפצו</b>: תהלים א, ב."],["11789","1064","<b>או\"י</b>: חט: אש יו\"ד."],["11790","1065","<b>שעל כ\"ד פרחה נשמתן</b>: נסמן לעיל פ' וארא סט, א."],["11791","1066","<b>שטל תו' החי' אותם</b>: ראה שבת פח, ב ע\"פ תניא פל\"ו."],["11792","1067","<b>כל העוסק בתורה טל תו' מחייהו</b>: ראה כתובות קיא, ב. יל\"ש ואתחנן ד, ד (רמז תתכד). אוה\"ח בחוקותי כו, יא. <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא ספל\"ו</a>. מאמרי אדה\"א דברים ח\"א ע' רצט. וש\"נ. במדבר ח\"ב ע' תרלז. לקמן פקודי תמח, ב. וראה גם בשל\"ה מס' שבועות קפב, א."],["11793","1068","<b>התענוג</b>: חט: העיון."],["11794","1069","<b>דשעשועים</b>: שם: דתענוג."],["11795","1070","<b>שבאור פניך נתת לנו</b>: ע\"פ סיום תפילת שמו\"ע."]]],[2300541024,"העצמ[ו]' דא\"ס בבחי' מיש ליש כמ\"ש להנחיל אוהבי יש האמיתי בלי ממוצע כלל, [ו]לא יהי' מקיפי' ופנימי' עליות וירידות דקו\"ח אלא למטה כמו למעלה ממש שלא ע\"י ההשתל' עו\"ע מאין ליש כו' כנ\"ל. וא\"כ הרי יוכל להיות במקבל כמו במשפיע ממש בלי חילוף ושינוי כלל והיינו בחי' מעומ\"ט שיחובר יחד ממש עומ\"ר ועומ\"ת, וכן אור המאיר דמשפיע עם אור המקבל שנק' אור השורף אש[א] אוכמא [או נהורא אוכמא, ו]היינו מה שהי' תחלה במקבל בחי' אשא אוכמא בבחי' או\"ח למעלה זהו מצד בחי' עליות דמקבל וירידות דמשפיע. אבל ביש מיש יקבל המקבל בבחי' שוב דמשפיע כמו שהיא למעלה ממש וגם במשפיע לא יהי' הסתלקות אחר התפשטו' כלל בבחי' מטולמ\"ט אלא יומשך למטה ולמעלה בשוה שלא בבחי' משפיע ומקבל [ה]נ\"ל וד\"ל.\n<b>וזהו</b> ואני אהי' לה חומת אש סביב, כי הנה בחי' חומ[ה] דתורה עכשיו היינו אותיות דתורה ש\"מ<sup data-n=\"11796\">1071</sup> שיורדת למטה בבחי' ר\"ר דעומ\"ר [ב]עומ\"ת כנ\"ל, וכמו\"כ בשמחה ושעשועי' שבתוה\"ק יורדת האור העליון דתו' אור למטה בעה\"ז<sup data-n=\"11797\">1072</sup> לברר שנק' נהורא עילאה<sup data-n=\"11798\">1073</sup> כמו במ\"ת וכידוע דאורייתא סתים וגליא כנ\"ל, [ו]כמ\"כ בנש\"י בב' אורות דנהורא תתאה ונהו\"ע<sup data-n=\"11799\">1074</sup> כו', וזהו והחיות רו\"ש מלמטה למעלה ו[מול\"מ] מלמעלמ\"ט כנ\"ל. אבל לע\"ל יהי' אור העצמי' השעשועי' שנק' מקיף דתענוג [ה]פשוט כמו בנגינה דתו' שנק' שיר פשוט<sup data-n=\"11800\">1075</sup> כו' [ב]חיבור מעלה ומטה יחד, ע\"כ [מ]בחי' אש דרצוא בנש\"י שהוא אש דרצוא דתו' מלמטה למעלה דעכשיו יהי' אז בחי' שוב דאש העליון דמקיף דשעשועי' שבתורה, שיהי' מזה בחי' חומת אש סביב למטה כמו שהוא בבחי' מקיף סביב למעלה בתענוג הפשוט (כמו מלעיל ומלרע בניגונים שמקיפים בעיגול [כעיגול] השיר<sup data-n=\"11801\">1076</sup> כמ\"ש במ\"א). ונמצא דחומת אש זו יהי' נעשה מאש העליון דתו' במ\"ת שנגלה עליהם<sup data-n=\"11802\">1077</sup> בקול ודיבור כי הוא מבחי' מקיף דשעשועי' דתו' שלמעלה כו'.\n<b>אך</b> עדיין י\"ל מ\"ש [ו]אני בעצמי דוקא אהי' לה כו' ולמה חומה דוקא ע\"כ<sup data-n=\"11803\">1078</sup> פרזות תשב כו' שבחי' או\"פ יהי' בלי גבול כנ\"ל, וגם למה אש[א] מבחי'<sup data-n=\"11804\">1079</sup> אוכמא דבחי' רצוא דוקא. אך הנה ידוע דמ\"ש יחזקאל במראה דמרכבה והחיות רו\"ש זה הי' בזמן הגלות כמ\"ש ואני בתוך הגולה<sup data-n=\"11805\">1080</sup> כו', שאז תשוקה ברשפי",[["11796","1071","<b>ש\"מ</b>: חט: ליתא."],["11797","1072","<b>בעה\"ז</b>: שם: בעה\"ד."],["11798","1073","<b>נהורא עילאה</b>: ח: נה\"א. ט: נהורא אוכמא."],["11799","1074","<b>דנהורא תתאה ונהו\"ע</b>: חט: דנהורא חיוורא ונה\"א."],["11800","1075","<b>שיר פשוט</b>: ראה גם לעיל פ' בא קו, ד. וש\"נ."],["11801","1076","<b>[כעיגול] השיר</b>: ראה מאמרי אדה\"ז תקס\"ו ע' שעד וע' שעח. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381135\" data-slug=\"likkutei-torah\" data-id=\"4001381135\">לקו\"ת שה\"ש א, ג</a>."],["11802","1077","<b>עליהם</b>: חט: ליתא."],["11803","1078","<b>ע\"כ</b>: שם: ועכ\"ז."],["11804","1079","<b>מבחי'</b>: שם: ליתא."],["11805","1080","<b>ואני בתוך הגולה</b>: יחזקאל א, א."]]],[2300541029,"אש דמל' בבחי' אשא אוכמא דוקא כמ\"ש שחורה אני<sup data-n=\"11806\">1081</sup> כו' שזהו בחי' רצוא דוקא, כמו טבע האש השורף לעלות למעלה<sup data-n=\"11807\">1082</sup> כנר העולה וכמ\"ש עולת תמיד העשויה בה\"ס<sup data-n=\"11808\">1083</sup> שעכ\"ד פרחה כו' שזהו רצוא דתענוג דתשוקה ואהבת התו' כמו באהבתה תשגה תמיד וכב\"ע שחשקה נפשו כו', כך התקשרות כנ\"י ברצוא בתשוקה באור דתו' מה\"ס שנק' עולת תמיד. אך יהי' עליות העולמות בכלל ופרט בעילוי אחר עילוי בכל עולם לפ\"ע כמו מגעה\"ת [יהי'] געה\"ע וגעה\"ע בגילוי<sup data-n=\"11809\">1084</sup> יותר כו', וכך גם נשמות ישראל יתעלו למעלה במדריגה גבוה יותר, דמה שעכשיו בחי' רצוא שהוא<sup data-n=\"11810\">1085</sup> <span data-k=\"pg\">שמט</span> ּ עולה למעלה לקבל יתעלה רצוא זה עצמו להיות בבחי' מקיף בבחי' שוב למטה כמו משפיע כנ\"ל, והוא מה שיומשך מזה בחי' חומת אש להקיף. כי יוכל להיות מאש התחתון דרצוא שבתו' דעכשיו בחי' חומה מאש זה שעומד בתוקף להקיף למטה דוקא, וז\"ש ואני אהי' לה חומת אש סביב אני ממש והוא מאש דתענוג ושעשועי' העצמי' שבתוה\"ק כו' (ואני אותיות אין<sup data-n=\"11811\">1086</sup> דכתר כו' [ו]נמשך מבחי' העלאות דתענוג כמו אני תורתך שעשעתי כו'. ושרש הענין הוא מטעם הנ\"ל דיש מעלה יתירה באש השחורה התחתון יותר מאש הלבן העליון המאיר להיותו שרשו בא מעצם אור<sup data-n=\"11812\">1087</sup> החשוך שממנו נמצא מקור האור כנ\"ל, והוא מ\"ש ישת חשך סתרו כו' שלמעלה גם מאור דתוה\"ק וע\"כ מאש דרצוא דתו' שלמטה נמשך מקיף דחומת אש כנ\"ל (וכמו ב\"ע שהי' אש מלהטת סביבו) וכיונתן ב\"ע שכל עוף<sup data-n=\"11813\">1088</sup> הפורח עליו נשרף וכמו<sup data-n=\"11814\">1089</sup> מיכאל נשרף ע\"י אש דתו' שלמעלה, אך חומת אש דתו' ש\"מ שלע\"ל יהי' בבחי' אור המאיר ולא שורף כלל).\n<b>ויובן</b> זה עפ\"י הידוע בפ[י]' בראשית ברית אש<sup data-n=\"11815\">1090</sup> [שיש] כמו כריתות ברית באש והוא בחיבור ב' הפכים כאש שלמטה שטבע האש<sup data-n=\"11816\">1091</sup> לעלות למעלה ואש שלמעלה שטבעו לירד<sup data-n=\"11817\">1092</sup> מלמעלה למטה, ואנו רואים שיש חיבור ויחוד<sup data-n=\"11818\">1093</sup> ביניהם יחדיו ישכנו באור הנר שמתחבר אור העליון המאיר בתחתון לפי שאש התחתון העולה ימשיך לאור העליון אליו (מטעם הנ\"ל ששרשו למעלה מן האור), כמו שרואים בנסיון כאשר יעמדו וישימו אש התחתון מכוון לנגד אש העליון ירד אש העליון",[["11806","1081","<b>שחורה אני</b>: שה\"ש א, ה."],["11807","1082","<b>טבע האש. . לעלות למעלה</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ד, ה\"ב. תניא רפי\"ט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380186\" data-slug=\"likkutei-torah\" data-id=\"4001380186\">לקו\"ת אחרי כה, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670409\" data-slug=\"torat-chaim\" data-id=\"2300670409\">תו\"ח בראשית כה, ד</a> הערה 46. לקמן פ' ויקהל שצד, א (תח, סע\"ג)."],["11808","1083","<b>עולת תמיד העשויה בה\"ס</b>: פינחס כח, ו."],["11809","1084","<b>בגילוי</b>: חט: בעילוי."],["11810","1085","<b>שהוא</b>: שם: שלהם."],["11811","1086","<b>ואני אותיות אין</b>: נסמן לעיל נ, ד."],["11812","1087","<b>בא מעצם אור</b>: ח: באוי\"ר. ט: באור."],["11813","1088","<b>וכיונתן ב\"ע שכל עוף</b>: סוכה כח, א. ראה לקמן פ' תצוה שמט, סע\"ד. ויקהל תמ, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670263\" data-slug=\"torat-chaim\" data-id=\"2300670263\">תו\"ח נח מט, ד</a> ובהערה 50."],["11814","1089","<b>שכל עוף הפורח עליו נשרף וכמו</b>: חט: שעוף כמו."],["11815","1090","<b>בראשית ברית אש</b>: ת\"ז רתכ\"ג."],["11816","1091","<b>שטבע האש</b>: חט: שטבעו."],["11817","1092","<b>שטבעו לירד</b>: שם: שיורד."],["11818","1093","<b>ויחוד</b>: שם: ליתא."]]],[2300541034,"למטה כמו גם נר שכבה<sup data-n=\"11819\">1094</sup> ומעלה עשן ימשיך העשן לאור הדולק למעלה ממנו להדליק הנר שכבה כידוע (וכמו בה\"ס שעשן העולה<sup data-n=\"11820\">1095</sup> למעלה הוריד והמשיך אש ה' וכן להיפוך כו' וכמ\"ש במ\"א). וזהו ברית אש ב' אשות הפכים הללו שבהכרח שיומשך<sup data-n=\"11821\">1096</sup> מלמעלה משניהם והוא מבחי' אויר שלמעלה מאור, [ו]זהו ואני אהי' כו' שיומשך חומת אש זה מאש ואור העליון בבחי' חסדים דשוב מתענוג ושעשועי' דחסד שיהי' ע\"י ברית אש דהיינו הרצוא דאש שלמטה דוקא כנ\"ל. ומ\"ש ולכבוד אהי' בתוכה קאי לעוה\"ב שהוא העדן שהוא אהי' הב' כו', והיינו בחי' שעשועי המלך בעצמו ממש שלמעלה הרבה גם מבחי' שעשועי' העצמי' שמשתעשע בתוה\"ק<sup data-n=\"11822\">1097</sup> כו'. וזהו יהי' בעדן שלמעלה מג\"ע<sup data-n=\"11823\">1098</sup> שנק' כבוד בחי' מקיפי' דשעשועי' העצמי' ממש כו', ולפי שיהי' בחי' עליות העולמות מלמטלמ\"ע מבחי' רצוא דעכשיו יומשך בחי' מקיף דחומת אש כנ\"ל כך יהי' מבחי' שוב שכל<sup data-n=\"11824\">1099</sup> התענוגי' והשעשועי' דא\"ס דתו' דעכשיו (שנק' עוסק בתו' לשמה לשם התו' עצמ[ה] שנק' תורתו אומנתו כו' בחי' גילוי או\"פ וכבוד העליון שהוא מקיף דשעשועי' שבעצמות ממש שיהי' [ב]בחי' או\"פ בירושלים ש\"מ. וז\"ש ולכבוד אהי' בתוכה בבחי' פנימי' ולא בבחי' מקיף כו', ואמנם זהו למעלה הרבה מבחי' מקיף דחומת אש מבחוץ אבל הא בהא תליא דוקא מטעם הנ\"ל וד\"ל (שזהו מיש ליש דעוה\"ב אחר ביטול היש לאין כו' וד\"ל).",[["11819","1094","<b>נר שכבה</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שי. תקס\"ה ח\"ב ע' א'ג. ש\"א מג, ב. לקמן פ' תצוה שמו, רע\"ב."],["11820","1095","<b>בה\"ס שעשן העולה</b>: ראה גם בהנסמן לעיל הערה 1027. מאמרי אדה\"ז על פרשיות התורה שם."],["11821","1096","<b>שיומשך</b>: חט: שיחוברו."],["11822","1097","<b>שעשועי המלך בעצמו. . שלמעלה הרבה. . שמשתעשע בתוה\"ק</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680248\" data-slug=\"torat-chaim\" data-id=\"2300680248\">תו\"ח תולדות קנב, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680459\" data-slug=\"torat-chaim\" data-id=\"2300680459\">מקץ רכח, סע\"א</a>."],["11823","1098","<b>בעדן שלמעלה מג\"ע</b>: ראה ברכות לד, ב. לעיל צב, ד ובהנסמן שם. לקמן פ' ויקהל תי, ד ובהערה 738. סה\"מ תרס\"ו ע' י."],["11824","1099","<b>שכל</b>: חט: המשכת."]]],[2300540079,"<b>ליל שבת נחמו וויטעפסק שנת תקפ\"א</b>\n<span data-k=\"pg\">700</span> ּמקול מחצצים<sup data-n=\"11825\">1</sup> בין משאבים שם יתנו צדקות ה' צדקת\nפרזונו בישראל<sup data-n=\"11826\">2</sup> כו'. הנה דבורה אמרה על עצמה עד שקמתי [דבורה שקמתי] אם בישראל<sup data-n=\"11827\">3</sup> כו', כי קודם שבא[ה] דבורה חדלו פרזון בישראל<sup data-n=\"11828\">4</sup> וע\"י דבורה נמשך צדקת פרזונו בישראל וזה שקמתי אם בישראל כו'. ולהבין זה [הנה] יש להקדים להבין תירוץ קושיא א' חזקה מאד בענין השבת ובענין כל זמני המועדים<sup data-n=\"11829\">5</sup>, ונזכר זאת הקושי' במ\"א בענין תיקון חצות",[["11825","1","<b>מקול מחצצים</b>: כנראה שמאמר זה הוא הנחת כ\"ק אדה\"א מדרוש אביו כ\"ק אדה\"ז משנת תקס\"ט ונאמרה עוה\"פ בשנת תקפ\"א. במאמרי אדה\"ז תקס\"ט ע' רפא [וכן באוה\"ת נ\"ך כרך ג ע' א'קסז] נדפס ביאור מכ\"ק אדמו\"ר הצ\"צ. ראה עוד ע\"ד המאמר להלן ברשימות בכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["11826","2","<b>מקול מחצצים. . צדקת פרזונו בישראל</b>: ס' שופטים ה, יא."],["11827","3","<b>עד שקמתי. . אם בישראל</b>: שם שם, ז."],["11828","4","<b>חדלו פרזון בישראל</b>: התחלת הכתוב עד שקמתי."],["11829","5","<b>בענין השבת ובענין כל זמני המועדים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161098\" data-slug=\"likkutei-sichot\" data-id=\"1300161098\">לקו\"ש בא כרך טז ע' 98</a> ובהערה 38. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221250\" data-slug=\"likkutei-sichot\" data-id=\"1300221250\">לקו\"ש ניסן כרך כב ע' 234</a> ובהערה 38. וראה גם מאמרי אדה\"ז תקס\"ו ע' מג ואילך."]]],[2300540117,"לילה<sup data-n=\"11830\">6</sup> שהוא עת רצון<sup data-n=\"11831\">7</sup> למעלה כמבואר בזהר ובספרי המקובלים. ויש להקשות בזה קושי' גדולה לכאורה, דהלא ידוע דחצות לילה אינו משתווה בכל המקומות, כי כדור הארץ עגולי<sup data-n=\"11832\">8</sup> ולפי ערך<sup data-n=\"11833\">9</sup> מהלך השמש עלי' בקיץ ובחורף, יש מקומות דבקיץ היום קצר ובחורף היום ארוך כמו מתחת לרגלינו באקלי\"ם שלנגד מושבינו ואצלינו להיפך, וכן ישתנה מדרום לצפון<sup data-n=\"11834\">*10</sup>, שבצפון הרחוק הרבה מקו השוה בקיץ אין הלילה יותר משעה א' או שתים ובדרום הקרוב אל קו השוה שם היום ולילה כמעט שוים, ולהלאה מרחוק בקו השוה בדרום יהי' להיפך שהיום קצר והלילה ארוכה בקיץ, וכן בחורף ישתנה מצפון לדרום. וא\"כ הרי יש מקומות בארץ שחצות לילה אצלם הוא חצי היום אצלינו, וא\"כ איך יגזור אומר שבכל חצות לילה אז זמן עת רצון למעלה אחר שאינו שוה בכל המקומות, ואיך יוכל להיות שעת רצון יהי' אצלינו בי\"ב שעות קודם לזמן חצות לילה שבאקלי\"ם שתחתינו, וכן אותם האנשים שבצפון יבא להם עת רצון בזמן חצות לילה שלהם ובשעה זו אין עת רצון לאנשים שבדרום הרי עת רצון משמע לכל העולם כולו<sup data-n=\"11835\">10</sup> ביחד. והנה קושי' זאת י\"ל גם בכל קביעת זמן כמו בשבת ויו\"ט שהרי יוכל להיות שאותן שבדרום חושבת לשבת<sup data-n=\"11836\">11</sup> ואותן שבצפון יהי' אז יום חול ועובד בכל מלאכה ועבודה, מאחר שהיום והלילה ישתנו [הרבה] מאקלי\"ם שבצפון לאקלי\"ם שבדרום כנ\"ל, א\"כ בשעה זו שכלה זמן יום הששי בדרום ומתחיל זמן ליל שבת, בצפון אז התחלת יום הו' או יום ה' וכיוצא. וכן ישתנה הרבה זמן קביעת המועדים מפני שינוי זמן התקופות והמועדות<sup data-n=\"11837\">*12</sup>, שמשתנה הרבה מאקלי\"ם שבדרום לאקלי\"ם שבצפון או מאקלי\"ם שלנו לאקלי\"ם שתחתינו עד שיוכל להיות שבאותו יום שחג פסח אצלינו אז הוא [זמן] חג [ה]סוכות<sup data-n=\"11838\">12</sup> באקלי\"ם שתחתינו וכיוצא בזה מצפון לדרום מטעם הנ\"ל. ואם נאמר מה איכפת לן בזה השינוי של הזמן הרי כאו\"א על מקומו הוא שומר שבת ויו\"ט בזמנו וכן יו\"ט<sup data-n=\"11839\">13</sup> וכל [דיני] המצות התלוים בזמן זה, זהו דבר שא\"א להיות<sup data-n=\"11840\">14</sup> כלל ע\"פ הטעם וסוד ה' אשר במצות שבת ויו\"ט שהוא זמן גילוי אורות עליונים כמו בחי' מוחין דאו\"א שמתגלים בז\"א בשבת ויו\"ט<sup data-n=\"11841\">15</sup> כמ\"ש בספה\"ק, ואיך יכול<sup data-n=\"11842\">16</sup> לומר שבאקלים שבדרום ששבתן יהי' אז<sup data-n=\"11843\">17</sup> בחי' שבת למעלה באצי' [ב]גילוי אורות עליונים כו' ובאותו יום",[["11830","6","<b>הקושי'. . תיקון חצות לילה</b>: ראה שו\"ע אדה\"ז או\"ח מהדו\"ת ס\"א, ס\"ח."],["11831","7","<b>חצות לילה שהוא עת רצון</b>: ראה במקומות שנסמנו בסידור <a class=\"ft-cite\" href=\"#/read/torah-or/3901370452\" data-slug=\"torah-or\" data-id=\"3901370452\">תו\"א</a> סדר תיקון חצות קב, ב ואילך. פע\"ח (שער תיקון חצות) שי\"ז. ובשו\"ע אדה\"ז שם ס\"ג מציין גם ליבמות עב, א."],["11832","8","<b>כדור הארץ עגולי</b>: ראה ירושלמי ע\"ז פ\"ג, ה\"א. תוד\"ה ככדור ע\"ז מא, א. במדב\"ר פי\"ג, יד. רד\"ק לישעי' מ, כח. מו\"נ ח\"א פל\"א. רמב\"ן נשא ז, א. הגהות וחידושים מהר\"ץ חיות נדה כג, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שדמ ובהנסמן במ\"מ לשם. שה\"א סו, א. מאמרי אדה\"א הנחות תקע\"ז ע' קמד. וש\"נ."],["11833","9","<b>ערך</b>: זיד: ליתא."],["11834","*10","<b>מדרום לצפון</b>: ועד\"ז בסמוך. ראה שו\"ע אדה\"ז חאו\"ח מהדו\"ת ס\"א, ס\"ח."],["11835","10","<b>עת. . כולו</b>: ז: אין עת רצון לכולם. יד: עת רצון הוא לכולם."],["11836","11","<b>חושבת לשבת</b>: שם: ישבתו בשבת."],["11837","*12","<b>והמועדות</b>: ד: והמולדות. יז: ליתא."],["11838","12","<b>יום שחג פסח. . חג [ה]סוכות</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221238\" data-slug=\"likkutei-sichot\" data-id=\"1300221238\">לקו\"ש</a> אור לער\"ח אייר תש\"מ כרך כב ע' 222 בהערה (לאחר שמעתיק קטע זה אומר): וכנראה הכוונה לתקופת חג הפסח (אביב) ולתקופת חג הסוכות (אסיף) — וראה אוה\"ת (משפטים ע' א'קעח ואילך. פינחס ס\"ע א'ריב ואילך. ועוד) הבי' דשייכות המועדים לתבואת הארץ דוקא."],["11839","13","<b>וכן יו\"ט</b>: זיד: ליתא."],["11840","14","<b>להיות</b>: שם: לומר."],["11841","15","<b>מוחין דאו\"א. . בשבת ויו\"ט</b>: ראה לעיל פ' בא קטז, ד הערה 70."],["11842","16","<b>יכול</b>: דיז: יתכן."],["11843","17","<b>ששבתן יהי' אז</b>: שם: ששובתי' יהי'."]]],[2300540155,"בצפון אין בא<sup data-n=\"11844\">18</sup> שבת למעלה אלא בחי' חול, ונמצא יהי' למעלה באצי' בחי' שבת ובחי' חול כא' וזהו <span data-k=\"pg\">שנ</span> ּ דבר שאינו מובן כלל. ועוד דהא באצי' הוא בחי' גילוי מוחין דאו\"א בז\"א לכללות נש\"י הכלולים במל' דאצי', ולפ\"ז אין כל ישראל מקבלים כא' הארת המוחין אלא אותן שבדרום מקבלים תחילה או להיפך. ואם נאמר מפני שבבחי' האצי' הוא למעלה מהתחלקות הזמן לגמרי א\"כ איך אמר הכתוב וישבות ביום השביעי<sup data-n=\"11845\">19</sup>, אלא צ\"ל שו\"ק דאצי' הוא מקור התחלקות הזמן<sup data-n=\"11846\">20</sup> כידוע, ומאחר שהשבת אי[ן] זמנו שוה למטה בארץ כנ\"ל איך ישתנה במקור זמן השבת למעלה באצי' כו'.\n<b>אך</b> הנה לתרץ קושיא זו יש להקדים הקדמה א' בענין המאמר אנת חכים ולא בחכ' ידיעא<sup data-n=\"11847\">21</sup> כו', שהן [בחי'] ע\"ס דאצי' שהם רק לאחזאה כו' לאתנהגא בהון עלמין<sup data-n=\"11848\">22</sup> כו', אבל מצד עצמות אוא\"ס לאו דאית לי' מכא\"מ כלל<sup data-n=\"11849\">23</sup> וכמ\"ש בס\"י ע\"ס בלי מ\"ה כלומר בלי מהות<sup data-n=\"11850\">24</sup> כלל. וביאור הדברים ידוע שע\"ס דאצי' הם רק בחי' מקור להיות התהוות הבריאה<sup data-n=\"11851\">25</sup> יש מאין, והיינו שא' לאחזאה ולאתנהגא בהון עלמין כמו מציאת בחי' חו\"ב דאצי' אינם רק בשביל המשכת בחי' חו\"ב דבי\"ע עד שנתהוה בחי' שכל אנושי בעולם השפל, ולא שכל אנושי בלבד אלא [גם] שכל וחכ' דקדושה האלקי' כמו נשמות דעשי' שהם שכל[יים] המשיגים אלקות, הרי הם ג\"כ נמשכים ונולדים מבחי' יחוד דזו\"נ דעשי' כנודע, שבהם מלובש בחי' חו\"ב דעשי' ובחי' חו\"ב דאצי' מלובש בחו\"ב דעשי' ע\"י אמצעות זו\"נ דבריאה ויצי' כו', ונמצא גם בחי' נשמה דעשי' יש להם שרש בחו\"ב דאצי' כו'. אך הנה בחי' התפשטות חו\"ב דאצי' בבי\"ע אינו [רק] מבחי' הכלים דחו\"ב ולא מבחי' האורות עצמן דהיינו רק מבחי' האחרונה שנק' בחי' עשי' בלבד, וכידוע דכל ספי' כלולה מי\"ס<sup data-n=\"11852\">26</sup> ובחי' האחרונה הוא בחי' מל' שבה שנחשב דרך כלל בחי' עשי', כי בחי' חב\"ד חג\"ת נה\"י שבכל מקום הוא בחי' בריאה ויצי' ועשי' כידוע ובחי' עשי' שבחכ' נק' ג\"כ חכ' שבעשי' והכל א', דהיינו עד\"מ כמו השכל היורד ומתלבש בעשי' גשמיי' לצייר ציורים או לעשות כל מלאכת מחשבת אומן שקוראם הכתוב חכמים ג\"כ כמ\"ש [ו]בלב כל חכם לב נתתי חכ' לעשות<sup data-n=\"11853\">27</sup> כו', וזה נמשך מבחי' כלי [ה]חכ'",[["11844","18","<b>בא</b>: שם: בחי'"],["11845","19","<b>וישבות ביום השביעי</b>: בראשית ב, ב."],["11846","20","<b>שו\"ק דאצי' הוא מקור התחלקות הזמן</b>: ראה סידור שער הק\"ש עו, א ואילך. ביאורי הזהר וארא לח, ב. דרך מצותיך ע' קנא. מאמרי אדה\"ז נביאים ע' קטז."],["11847","21","<b>אנת חכים. . ידיעא</b>: ת\"ז בהקדמה (יז, ב). ראה גם לקמן פ' יתרו רסז, רע\"א."],["11848","22","<b>לאחזאה. . לאתנהגא בהון עלמין</b>: ראה שם (יז, ב. א)."],["11849","23","<b>לאו. . מכא\"מ כלל</b>: ראה שם (יז, ב)."],["11850","24","<b>ע\"ס בלי מ\"ה. . בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["11851","25","<b>שע\"ס דאצי'. . מקור. . הבריאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370418\" data-slug=\"torah-or\" data-id=\"3901370418\">תו\"א מג\"א צג, א</a>. מאמרי אדה\"ז על נביאים ע' קצא. פרשיות התורה ח\"ב ר\"ע תשפה בשם הפרדס (ובהנסמן במראי מקומות לשם). לקו\"ת ואתחנן יב, א."],["11852","26","<b>דכל ספי' כלולה מי\"ס</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד, פ\"א."],["11853","27","<b>[ו]בלב כל חכם לב. . לעשות [יד: ליתא]: תשא לא, ו [ושם</b>: ועשו]."]]],[2300540192,"היותר אחרון דהיינו רק בחי' עשי' שבחכ' והוא מה שיש בכח החכ' לירד ולהתפשט גם בעשי' גשמי' שהוא בחי' גשמי' אור וכח השכל ביותר מבחי' הארת השכל שבדבור ומח' ומדות וכה\"ג וד\"ל. [ו]אמנם הנה גם בחי' עשי' שבחו\"ב דאצי' אין בערך עדיין שיומשך משם התהוות בחי' חכ' מוגבלת בעולם הבריאה ויצי' כו' בהשגת הנשמות דבי\"ע ומכ\"ש התהוות שכל אנושי דעשי', כי הרי אין ערוך כלל וכלל לבריאת חכ' מוגבלת יש מאין גם לבחי' עשי' שבחכ' דאצי'<sup data-n=\"11854\">28</sup> כידוע, אך עכ\"ז הוא בחי' מקור ושרש לשרש התהוות חכ' בבי\"ע כו', כמו עד\"מ כח המצמיח שבארץ שמצמיח עשב גשמי' שבודאי אין ערך לגשמי' העשב לגבי כח המצמיח ומגדלו שהוא רוחני', ומ\"מ הוא מגדל ומצמיח כל עשבים ותבואות למיניהם אם טובים ואם רעים הכל הוא ע\"פ כח <span data-k=\"pg\">702</span> ּ הרוחני' [מ]שרשם אשר בכח המצמיח[ו], וא\"א לומר שבגשמי' העשבים ותבואה המורגשי' בטעם גשמי' ישנם ברוחני' המצמיחם ג\"כ במהות וטעם גשמי', ואעפ\"כ בהכרח לומר שיש ברוחני' המצמיחי' כל שינוי' אלה שמחולקים העשבים והתבואה למיניהם רק ששם הוא בהתחלקות בבחי' הרוחני', וא\"כ הגם שאין ערך לגשם העשבים והתבואה לגבי מקורם, מ\"מ משם נמשך כל פרטי התחלקות מציאותם למיניהם. וכך יובן למעלה בהתהוות חכ' מוגבלת דבי\"ע מבחי' עשי' שבחכ' דאצי' שהוא כדמיון כח המצמיח שבארץ שמצמיח גשמי[ו' התבואה] וכה\"ג, וכמ\"ש אור זרוע לצדיק<sup data-n=\"11855\">29</sup> פי' הנשמה שנק' אור נזרעת היא בבחי' יחוד זו\"נ דאצי' ע\"י בחי' מוחין דאו\"א המלובשים בהם ונולדים מאין ליש בבחי' האצי' מבחי' יסוד<sup data-n=\"11856\">30</sup> ז\"א שנק' צ\"ע<sup data-n=\"11857\">31</sup> כידוע. וכך הוא ענין תולדות הנשמות בבריאה מיחוד זו\"נ דבריאה ע\"י הארת מוחין דאו\"א בבריאה שמקבלים מבחי' האצי', עד שמיחוד זו\"נ דעשי' נולדו נשמות גשמי'<sup data-n=\"11858\">32</sup> דעשי', ומבחי' חיצוני' הכלי' דמל' שבחכ' דעשי' נמשך ג\"כ התהוות שכל אנושי ע\"י כמה ממוצעים כמו שמות<sup data-n=\"11859\">*33</sup> שכליים נבדלים<sup data-n=\"11860\">33</sup> כו'.\n<b>ונמצא</b> מובן מכ\"ז דגם בחי' החכ' דעשי' יש להם שרש [ומקור] באצי' מבחי' כלים דחכ' דאצי' ע\"ד הנ\"ל אבל אין זה רק באמצעות בחי' [כלי] החכ' שנק' עשי' שבחכ' ולא מבחי' האור דחכ' כו', וכך הוא בכל הע\"ס דאצי'. דהנה מש\"א אנת הוא<sup data-n=\"11861\">34</sup> חכים כו' פי' מה שהוא ית' נק' חכים [א]ו מבין הכל הוא בבחי' הכלים דע\"ס, אבל בבחי' האור ולא בחכמה ידיעא מפני שבבחי' האור אין החכ' נמצאת במציאות דבר מה כלל, כי אין הכוונה בכל ספרי המקובלים בהזכירן ע\"ס בהתחלקות רק מצד מציאת<sup data-n=\"11862\">*35</sup> הכלים שלהם אבל מצד בחי' האור נק' ע\"ס בלי מ\"ה כנ\"ל. והענין הוא כי אין פי' אור החכ'<sup data-n=\"11863\">35</sup> קאי על התהוות מציאות החכ' כי האור אינו מכונה כלל על התהוות מציאות",[["11854","28","<b>אין ערוך. . חכ'. . עשי' שבחכ' דאצי'</b>: ראה גם לעיל פ' בא צו, ד. וש\"נ."],["11855","29","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["11856","30","<b>יסוד. . שנק' צ\"ע</b>: ראה גם פרדס (שער עה\"כ) שכ\"ג מערכת צדיק."],["11857","31","<b>ז\"א שנק' צ\"ע</b>: ראה ע\"ח (שער ז\"א) שי\"ז, ספ\"א."],["11858","32","<b>גשמי'</b>: זיד: ליתא."],["11859","*33","<b>שמות</b>: ד: ליתא. יז: שהם."],["11860","33","<b>שכליים נבדלים</b>: ראה גם לעיל רי, ג הערה 57."],["11861","34","<b>הוא</b>: זיד: ליתא."],["11862","*35","<b>מציאת</b>: שם: אמצעי'."],["11863","35","<b>אין פי' אור החכ'</b>: ראה גם מאמרי אדה\"ז תקס\"ט ר\"ע ריח. וש\"נ. סידור שחרית מט, רע\"ד (מאמרי אדה\"א נ\"ך ע' קסה)."]]],[2300540226,"פרטי', אלא הפי' הוא אור התגלות המאציל בשביל התהוות מציאות חכ' ועדיין לא נמשך ונתהווה מציאת החכ', ומה שמתלבש אח\"כ בחי' גילוי אור המאציל בהתהוות מציאות החכ' הוא הנק' בחי' כלי החכ', כי פי' כלי הוא בחי' לבוש שמתלבש האור במציאת דבר מיוחד. וא\"כ מזה מובן שמה שנק' חכים ומבין הוא בבחי' הכלי', ומה שמתגלה אור המאציל בשביל התהוות חו\"ב נק' בחי' אורות דחו\"ב, ועד\"ז כל הע\"ס שנק' אורות הכל הוא רק בבחי' גילוי אור המאציל עצמו עדיין. ומה שיש בחי' התחלקות י\"ס באורות היינו לפי שנתגלה המאציל ביו\"ד מיני גילוים, אך אין בחי' התחלקות מציאות ניכרת כלל בבחי' גילוי אור המאציל וכמ\"ש ולא בחכ' ידיעא כו' וד\"ל.\n<b>ויובן</b> זה עד\"מ כח [ה]היולי שנק' כח המשכיל להשכיל כל מיני שכליים והרי יש שכל דק כמו שכל וסברא עמוקה בשכל ר[ם] ו[יש] שכל גס כמו בהמצאות עשי' וציור גשמי', וב' השכליי' כלולים בכח המשכיל יחד בלי התחלקות כלל רק שמתגלה כאו\"א במדריגה בפ\"ע, כי כשממציא שכל הדק ודאי שמאיר אור מכח המשכיל בהארה פנימי' יותר משמאיר להמצאת שכל הגס, ומ\"מ אין הפרש ניכר בשתי הארות הללו רק כשבאים בהתלבשות שכל ממש. <span data-k=\"pg\">שנא</span> ּ וכמו\"כ בהמשכת החסד מכח ההיולי שבטבע הטוב שמתחלק לכמה מיני חסדים, לפעמים מתחסד בממון ולא בשכל ויש מתחסד להיפך ויש מתחסד בשתיהן ושתיהן כלולי' בכח החסד ויוצאי' מחולקי' כאו\"א בפ\"ע, אך אין חילוק מדריגתם ניכרת רק בהתלבשותם בכלי שהוא פועל החסד. וכיוצא בזה יובן למשכיל [למעלה] שהפרש חילוק המדרגות בע\"ס אינו ניכר כלל רק כשהוא בבחי' הכלים אבל לא בבחי' האורות הגם שיוצאי' מחולקים ונק' ע\"ס, אבל כאו\"א לא נודע במציאות ניכרת עדיין וז\"ש ולא בחכ' ידיעא כו'. ונמצא מובן מכ\"ז דבחי' החכ' עצמה נק' כלי וגילוי אור המאציל שהאצ[י]לה נק' אור החכ' ועד\"ז בכל הע\"ס כו' וד\"ל.\n<b>והנה</b> אחר שמבואר למעלה בבחי' התהוות השכל של הנשמה [ד]בי\"ע מבחי' חכ' דאצי' הוא מבחי' כלי החכ' בלבד ונתבאר למעלה ההפרש בין בחי' האור ובין בחי' הכלי' כו', ומעתה יובן<sup data-n=\"11864\">36</sup> מה שמבואר בע\"ח בכמה דוכתי שיש הפרש בין בחי' פנימי' הכלי' לחיצוני' הכלי' והוא ההפרש שבין שרש נש\"י לשרש המלאכים שהנשמות נמשכי' מבחי' פנימי' הכלים והמלאכים מבחי' חיצוני'<sup data-n=\"11865\">37</sup> הכלים. וביאור הדברים הנה ידוע שבכל ספי' יש ג' מדרגות חב\"ד חג\"ת נה\"י<sup data-n=\"11866\">38</sup> כמו בחי' אור החכ' שהיא כלולה מע\"ס, הנה בחי' הפנימי' נק' חכ' שבחכ' ובחי' המדות שבחכ' נק' חג\"ת שבחכ' ובחי' השפעת שבחכ' לזולתו או",[["11864","36","<b>יובן</b>: זיד: יש להבין."],["11865","37","<b>שהנשמות. . פנימי' הכלים והמלאכים מבחי' חיצוני'</b>: ראה ע\"ח (שער העבורים) שכ\"ח, פ\"א. (שער פנימיות וחיצוניות) ש\"מ, דרוש י. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"ג ע' תשסח. וש\"נ."],["11866","38","<b>שבכל ספי'. . חב\"ד חג\"ת נה\"י</b>: ראה גם דרך מצותיך יב, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' תטו ואילך. כתובים ח\"א ר\"ע קפח. אוה\"ת נ\"ך כרך ב ע' תשנ."]]],[2300540258,"לשלמטה הימנו נק' נה\"י שבחכמה. וכך הוא בבחי' אור החסד שכלולה מע\"ס הנה בחי' פנימי' אור החסד נק' חב\"ד שבחסד שהוא [ה]שכל ו[ה]טעם להתהוות החסד בלבו ובחי' גופו של חסד נק' חסד שבחסד ובחי' השפעת גילוי אור החסד למטה נק' נה\"י שבחסד כו'. וכמו שיש הפרש ג' אלה בבחי' האורות כך יש הפרש בין זל\"ז בבחי' הכלים והוא ג' מיני [כלים] פנימי' לבחי' חב\"ד ואמצעות לבחי' חג\"ת וחיצוני' לבחי' נה\"י, ונק' כלים החיצונים דחסד בחי' השפעת הכלים דנה\"י שבחסד כי בחי' האור לא ניכר במציאות עדיין כנ\"ל בהפרש שבין בחי' האורות לבחי' הכלים כו' וד\"ל. וזהו ההפרש בין ישראל למלאכים שהמלאכי' שרשם מבחי' חיצוני' הכלים דנה\"י שבז\"א, והנשמות שרשם מבחי' פנימי' הכלים דהיינו מבחי' הכלי' דחב\"ד שבחסד דז\"א וע\"כ נק' ישראל לי ראש<sup data-n=\"11867\">39</sup> שהוא בחי' חב\"ד שבמדות דז\"א כידוע וד\"ל.\n<b>וביאור</b> הדבר יובן עד\"מ שאנו רואים בהפרש שיש בין גדול לקטן, שהקטן מדותיו קטנים מאד שאינו אוהב רק דברים קטנים מאד מפני ששכלו המאיר במדותיו קטן הוא עדיין וכתי' לפי שכלו יהולל איש<sup data-n=\"11868\">40</sup> שהמדות שנק' איש [הם מת]גדלים לפ\"ע [גידול] השכל כו', וע\"כ כל מה שיתגדל התינוק בשכלו ממילא יתגדלו מדותיו לאהוב דברים חשובים ביותר וכיוצא, לפי שהתלבשות השכל במדות כל מה שיגדל השכל יותר יותר יתלבש ויתפשט השכל הארתו במדותיו (ונמצא קטנות המדות ב' דברים הם, א' מצד קוטן השכל והב' מצד מיעוט הארתו במדות משא\"כ כשיגדל השכל מתרבה הארתו במדות כנ\"ל כי הא בהא תליא. ואז נק' גדלות המדות מב' טעמים, הא' מצד התלבשות השכל בהארה מרובה והב' מצד גודל השכל כו' וד\"ל). וזהו משל למעלה להבין שרש ההפרש בין ישראל למלאכים, שהנשמו' הן מבחי' פנימי' הכלים דחב\"ד שבחסד, דהיינו מבחי' מוחין דגדלות שהוא ענין <span data-k=\"pg\">704</span> ּ התלבשות השכל במדות בהארה מרובה וע\"כ נק' ישראל לי ראש שהוא מבחי' החכ' שבחסד בכללות. ושרש המלאכים מבחי' כלים דנצח שבחסד, ששם אינו מאיר בחי' החכ' שבחסד רק בבחי' עשי' שבחכ' ושכל<sup data-n=\"11869\">41</sup> שהוא בחי' קטנות המוחי'. ונמצא שכל שאור החכ' מתגלה יותר בחסד שרשו גם בחכ' בבחי' פנימי' יותר והיינו שרש נש\"י שהוא מבחי' פנימי' אור אבא כמ\"ש כי אתה אבינו<sup data-n=\"11870\">42</sup> וכמ\"ש במ\"א וד\"ל.\n<b>ומעתה</b> הנה י\"ל בשרש ענין חג הפסח שהוא למעלה בחי' זמן התגלות דאור חסד עליון, כידוע בשרש ענין ג' זמני<sup data-n=\"11871\">43</sup> מועדי ה' פסח שבועות [ו]סוכות שהן מבחי' חג\"ת<sup data-n=\"11872\">44</sup> דז\"א כו'.",[["11867","39","<b>ישראל לי ראש</b>: נסמן לעיל פ' שמות יח, ב."],["11868","40","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."],["11869","41","<b>שבחכ' ושכל</b>: זיד: שבשכל."],["11870","42","<b>כי אתה אבינו</b>: ישעי' סג, טז. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' שפח. לקמן פ' תצוה שמו, ב. וש\"נ."],["11871","43","<b>זמני</b>: זיד: ליתא."],["11872","44","<b>פסח שבועות [ו]סוכות. . חג\"ת</b>: ראה סידור שחרית לד, א. לז, סע\"א ואילך. מאמרי אדה\"א נ\"ך ע' שעה. וש\"נ. הנחות תקע\"ז ע' רכא. וש\"נ."]]],[2300540288,"<b>ולכאורה</b> אין זה מובן דהא בלא\"ה יש גילוי אור חסד עליון למעלה באצי' תמיד כמ\"ש כי חסד אל כל היום<sup data-n=\"11873\">45</sup> וכתי' כי אמרתי עולם חסד יבנה<sup data-n=\"11874\">46</sup> כו'. אך הענין הוא דשרש חג הפסח הוא ענין דילוג המוחי' מאור החכ' דאבא בז\"א דאצי', והוא בחי' התלבשות והארת [ה]חכ' בחסד דז\"א יותר מכפי המדה בסדר השתלשלו' והתלבשות הפרצופי'. והטעם לבחי' גילוי אור החכ' בחסד דז\"א בתוס' גילוי יותר מכפי [ה]מדה [ה]ראשונה הוא כדי לבטל ולהשפיל שרש יניקת פרעה, כי הנה פרעה א' מי הוי' אשר אשמע בקולו<sup data-n=\"11875\">47</sup>, לפי שאין הע\"ש<sup data-n=\"11876\">48</sup> העליונים מקבלים יניקה מבחי' פנימי' [דקדושה] שהוא שם הוי' וכמ\"ש וכבודי לאחר לא אתן<sup data-n=\"11877\">49</sup> כו', אלא מקבלים מבחי' שם אלקי' המסתיר על שם הוי' כמו שמסתיר המגן על השמש כמ\"ש כי שמש ומגן הוי' אלקי'<sup data-n=\"11878\">50</sup>, וכידוע דכל יניקת החיצוני' הוא רק מבחי' אחוריים דשם אלקי' דוקא כמ\"ש [מלך] אלקי' על גוים<sup data-n=\"11879\">51</sup> כו', אבל בחי' שם הוי' א\"א להם לקבל יניקה וע\"כ כתי' רם על כל גוים הוי'<sup data-n=\"11880\">52</sup> כו' ולהיות כן לא ידע פרעה [כלל] בשם הוי', וז\"ש מי הוי' אשר אשמע בקולו כו'. ו[ל]טעם זה הי' כל עיקר היו\"ד מכות כדי להכניע את מצרים בשרשם באחוריי' דשם אלקי' [דקדושה] כמ\"ש ובכל אלקי מצרים אעשה שפטים<sup data-n=\"11881\">53</sup> כו' וידעו מצרים כי אני הוי'<sup data-n=\"11882\">54</sup> דוקא ומבחי' שם הוי' לא יוכלו לקבל וכמ\"ש במ\"א. אך איך יתגלה שם הוי' מאחר דשם אלקי' מסתיר עלי[ו], הנה לזה הוא שרש חג הפסח שפסח הוי' על הפתח<sup data-n=\"11883\">55</sup> כו' ונמשך בחי' תוס' גילוי אור רב מבחי' החכ' בחסד דז\"א עד שמחמת ריבוי האור האיר גם להעלם והסתר דשם אלקי' שלא יסתיר כלל, והיינו שלא יסתיר הכלי לבחי' האור כלל, כידוע דשם הוי' הוא בחי' האורות ושם אלקי' הוא בבחי' הכלים<sup data-n=\"11884\">56</sup>. וכאשר האיר האור דשם הוי' דחכ' בחסד דז\"א יותר מכפי המדה עד שגם בחי' הכלים דשם אלקי' האיר מחמתו, א\"כ הרי הוא<sup data-n=\"11885\">57</sup> מאיר אור חסד עליון למטה בבי\"ע למעלה מסדר ההשתל' והתלבשות דאור וכלי, וע\"כ אז ממילא בטלה שרש יניקת פרעה שמקבל מבחי' אחוריי' וחיצוני' דשם אלקי' כו', ובשביל זה הי' עיקר הדילוג של אור החכ' להאיר בתוס' גילוי בחסד עליון והוא שרש ענין הפסח וד\"ל. ועד\"ז יובן ג\"כ ענין חג השבועות וסוכות שהם ג\"כ בחי' תוס' אורות בכלים, וע\"ד מ\"ש כי הוי' הוא האלקי'<sup data-n=\"11886\">58</sup> שיתגלה שם הוי' בתוס' אור בבחי' אלקי' כו' שהוא ענין א' עם תוס' גילוי אורות בכלים הנ\"ל, וז\"ש במ\"ת וירד הוי'<sup data-n=\"11887\">59</sup> כו' וד\"ל. אך יש הפרש בין ג' רגלים דפסח שבועות סוכות לשבת, שבג' המועדי' <span data-k=\"pg\">שנב</span> ּ הוא בחי' תוס' גילוי אורות בכלים מלמעלה למטה דוקא וכמ\"ש במ\"ת וירד הוי' כו' ובפסח כתי' ופסח הוי' כו' היינו באתעדל\"ע<sup data-n=\"11888\">60</sup> שלא מצד אתעדל\"ת כלל",[["11873","45","<b>כי חסד אל כל היום</b>: נסמן לעיל פ' בא קיב, ד."],["11874","46","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["11875","47","<b>מי הוי' אשר אשמע בקולו</b>: שמות ה, ב. ראה לעיל פ' שמות לא, ב."],["11876","48","<b>הע\"ש</b>: נסמן לעיל לז, ג."],["11877","49","<b>וכבודי לאחר לא אתן</b>: ישעי' מב, ח. מח, יא."],["11878","50","<b>כי שמש ומגן הוי' אלקי'</b>: נסמן לעיל פ' וארא סג, ג."],["11879","51","<b>[מלך] אלקי' על גוים</b>: תהלים מז, ט."],["11880","52","<b>רם על כל גוים הוי'</b>: תהלים קיג, ד."],["11881","53","<b>ובכל אלקי מצרים אעשה שפטים</b>: בא יב, יב."],["11882","54","<b>וידעו מצרים כי אני הוי'</b>: וארא ז, ה. ראה לעיל כ, ב. וש\"נ."],["11883","55","<b>שפסח הוי' על הפתח</b>: בא יב, כג."],["11884","56","<b>הוי'. . האורות. . אלקי'. . הכלים</b>: ראה גם שער היחוה\"א פ\"ד ואילך. סידור שחרית נו, ג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370311\" data-slug=\"torah-or\" data-id=\"3901370311\">תו\"א יתרו סט, ד</a>."],["11885","57","<b>הוא</b>: זיד: הי'."],["11886","58","<b>כי הוי' הוא האלקי'</b>: ואתחנן ד, לט."],["11887","59","<b>וירד הוי'</b>: יתרו יט, כ."],["11888","60","<b>ובפסח. . באתעדל\"ע</b>: ראה גם סידור (שער חגה\"מ) רצ, ב. מאמרי אדה\"ז תקס\"ט ע' נד. שה\"א יא, ב. מאמרי אדה\"א הנחות תקע\"ז ע' כו. ויקרא ח\"א ע' רצד. לקמן רמב, א ואילך."]]],[2300540316,"כמ\"ש במ\"א. אבל בשבת הגם שבו נמשך תוס' גילוי אורות בכלים יותר מבמועדים (וכמ\"ש במ\"א בענין קדש מלה בגרמי'<sup data-n=\"11889\">61</sup> ששרש השבת בקדש דאור אבא עצמ[ו] ויו\"ט נק' מקראי קדש<sup data-n=\"11890\">62</sup> ), אבל סיבת תוס' גילוי אור הוי' דחכ' בשבת הוא בא ע\"י אתעדל\"ת שהוא בחי' העלאה והבירור מלמטה למעלה כל ששת ימי המעשה כו' וד\"ל.\n<b>וביאור</b> הדברים הנה יובן בהקדים להבין תחלה שרש [ענין] ההפרש בין בחי' אדם לדצ\"ח למטה ו[מ]זה יובן למעלה בבחי' אדה\"ע דאצי', [ד]הנה אנו רואים שהאדם מקבל חיות מדצ\"ח שלמטה הימנו, [ו]הרי כל יגיעת האדם ביגיעת כפו באיזה מלאכה או עמלו בעסק סחורה כדי להרויח ממון הוא רק להשיג מזונותיו ומלבושיו ושאר צרכי גופו, וכולם הם למטה הימנו שהרי כל הדברים הצריכי' לגופו הם רק מחלקי דצ\"ח כמ\"ש כל העמל האדם לפיהו<sup data-n=\"11891\">63</sup> כו', והרי [הוא] נותן נפשו וכל כחו ושכלו עד שישיג טרף מזונו ובגד ללבוש כו', וא\"כ יש הוראה מזה שהוא למטה מהם. אך הנה אנו רואים להיפך ג\"כ שהאדם גבוה מהם, שהרי האדם הוא המעלה את חלקי הדצ\"ח להיות כי לאחר שהשיג המאכל ואכל המזון הרי נכלל חיות המזון בנפש המדברת ונעשה גם המזון הצומח בחי' אדם מדבר, מאחר שנתחזק כח השכל ע\"י כח של<sup data-n=\"11892\">64</sup> המאכלים הרי נתהפך ונכלל גם חיות המזון בבחי' השכל. וכמו\"כ המלבושים נכללו בבחי' אדם כשלובשם עליו, וכן שאר צרכי הגוף נתעלי' ונכללי' בבחי' אדם. אמנם זהו דוקא לאחר שיגע ומצא את מזונו ומלבושיו שנכללי' ועולין בו, כי בהיותו עולה בו כחו שטרח ויגע וכח שכלו בעמלו<sup data-n=\"11893\">65</sup> בכח שכלו ומדותיו הפנימי' אזי גם הלחם שאוכל נכלל בו כו' וכן גם הלבוש כו'. משא\"כ קודם שיגע ומצא המזונות והמלבושי' אדרבה הרי נהפך הוא שהאדם הוא למטה הרבה מהן כי נעשה בחי' מקבל מהן באכילה כנ\"ל ומכ\"ש ביגיעת כחו להשיג[ם] כנ\"ל וד\"ל.\n<b>וכמו\"כ</b> יובן למטה ההפרש בין ו' ימי חול לשבת באדם התחתון, שכל ו' ימי החול הוא נותן נפשו וטורח להשיג מזונות ושאר צרכי גופו ע\"י עסק מלאכות הרבה כמו חורש וזורע כו', ובבוא יום השבת הוא בחי' העלאה מכל אשר יגע כל ימי החול ונכללי' כולם בבחי' אדם, כי בשבת הוא נח ושובת דהיינו שעולה אל עצמו' נפשו השכלי' שנק' אדם ומי",[["11889","61","<b>קדש מלה בגרמי'</b>: נסמן לעיל קכ, ב."],["11890","62","<b>השבת בקדש. . ויו\"ט. . מקראי קדש</b>: ראה לעיל פ' בא קכ, א. וש\"נ."],["11891","63","<b>כל העמל </b>[זיד: עמל]<b> האדם לפיהו</b>: קהלת ו, ז."],["11892","64","<b>כח של</b>: ז: בחי' חיות של. יד: כח."],["11893","65","<b>כחו שטרח. . בעמלו</b>: זיד: בבחי' אדם."]]],[2300540341,"שטרח בע\"ש<sup data-n=\"11894\">66</sup> דוקא הוא יאכל בשבת להעלותם לבחי' אדם. והענין בעבודת ה' ידוע שכל ימי החול האדם שהוא בחי' חכ' שבנפש ה[אלקי'] מברר ל[א]הפכא חשוכא לנהורא<sup data-n=\"11895\">67</sup> כו' כמ\"ש ששת ימים תעבוד<sup data-n=\"11896\">68</sup> כו' ו[ב]שבת כל מה שטרח בחול עולה ונכלל בבחי' אדם, כי כשהוא שובת ומתעל[ה] להיות בבחי' אדם אז גם כל מה שיגע בחכמתו לברר עולי' ונכללי' בו כו'. וא\"כ הרי מובן מכ\"ז דאם לאו [כל] מה שעבד בחול לא הי' עולה בשבת להיות בבחי' אדם, ועד\"ז אכילת המזון שמחזק השכל [ו]כן עבודת הבירורי' לאהפכא חשוכא [לנהורא] כו' מוסיף אור החכ' בנה\"א כו'. ובזה ו' ימי החול גבוהים מבחי' השבת, אבל מ\"מ הרי המעלה לכל ו' ימי החול <span data-k=\"pg\">706</span> ּ הוא השבת שבו נק' האדם להעלות כל מה שעבד [ב]ו' ימי החול כו' וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למשכיל למעלה דבו' ימי המעשה<sup data-n=\"11897\">69</sup> דלמעלה הנה בחי' ז\"א דאצי' שנק' אדם<sup data-n=\"11898\">70</sup> יורד בבי\"ע לברר בירורי נוגה שהוא למשל אדם שמייגע בל\"ט מלאכות כנ\"ל (וכמ\"ש<sup data-n=\"11899\">71</sup> במ\"א בענין ז'<sup data-n=\"11900\">72</sup> אלפי' צבא הצובאי' על מדין<sup data-n=\"11901\">73</sup> כו' דבכל יום מאיר אור מז\"א בבי\"ע לברר בירורי נוג\"ה כו'), [ו]מפני ששרש הנוגה הוא מרפ\"ח ניצוצו'<sup data-n=\"11902\">74</sup> דתהו ובהו<sup data-n=\"11903\">75</sup>, ע\"כ יש ביכולתן לאחר שיבורר ויהופך חושך לאור ע\"י שם מ\"ה דאדם<sup data-n=\"11904\">76</sup> [לה]וסיף אור באדם זה וכמשל המזון שמחי' לנפש האדם כו', וע\"ז נאמר למעלה ג\"כ באדם העליון ששת ימים תעבוד כו' בעבודת הבירורים דנוגה (וכמ\"ש ותקם בעוד לילה<sup data-n=\"11905\">77</sup> ותתן טרף לביתה שהוא ע\"י כח החכ' דוקא כמ\"ש במ\"א). ואחר העלא' והבירור מכל ו' יומין בהגיע יום השבת שאז מאיר אורות ומוחי' דאו\"א בשלימות בז\"א ונק' אדם בבחי' מוחי' דגדלות אזי ג\"כ עולים ונכללי' כל הבירורי' דרפ\"ח כו' שעשה בל\"ט מלאכות כו'<sup data-n=\"11906\">78</sup> ונעשים גם הם בבחי' אדם כמובן ממשלים הנ\"ל. וז\"ש בסוף יום הששי וירא אלקי' [את כל] אשר עשה<sup data-n=\"11907\">79</sup> בוי\"מ<sup data-n=\"11908\">80</sup> שהוא טוב מאד, להיות כי מי שטרח בע\"ש דוקא יאכל כו' שבבחי' א' הרי עבודת וי\"מ גורמים לו להיות בבחי' אדם מטעם שהתהו גבוה מהתיקון<sup data-n=\"11909\">81</sup> כו'. וז\"ש ויכולו השמים<sup data-n=\"11910\">82</sup> דהיינו העל[י]' לבחי' עתיק כו' שהוא בחי' עונג העליון, וז\"ש<sup data-n=\"11911\">83</sup> טוב מאד בלי גבול<sup data-n=\"11912\">84</sup> כי מל' דא\"ס מאיר בפנימי' עתיק כידוע וד\"ל. אך עלי' גדולה כזו א\"א להיות בב\"א<sup data-n=\"11913\">85</sup> לכך הוסדו התפלות שהוא בחי' העלאת האדה\"ע כל יום מעין בחי' השבת<sup data-n=\"11914\">*86</sup> בכללות, ומעט מעט ע\"י התפלה דוי\"מ נעשה כללות העלאת באדם בשבת, כי עלי' התפלה הוא בחי' ממוצעת בין חול לשבת כמ\"ש במ\"א בענין סולם מוצב<sup data-n=\"11915\">87</sup>",[["11894","66","<b>ומי שטרח בע\"ש</b>: ע\"ז ג, א."],["11895","67","<b>ל[א]הפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["11896","68","<b>ששת ימים תעבוד</b>: יתרו כ, ט. ואתחנן ה, יג."],["11897","69","<b>המעשה</b>: זיד: החול."],["11898","70","<b>ז\"א. . אדם</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"ה."],["11899","71","<b>שהוא. . (וכמ\"ש</b>: זיד: (שהוא. . וכמ\"ש."],["11900","72","<b>ז'</b>: דיד: יב — ראה פיה\"מ מא, סע\"א ואילך."],["11901","73","<b>ז' אלפי' צבא הצובאי' על מדין</b>: נסמן לעיל פ' בא קכז, ד [ושם: ו']."],["11902","74","<b>מרפ\"ח ניצוצו'</b>: נסמן לעיל פ' שמות לו, ג."],["11903","75","<b>ובהו</b>: זיד: ליתא."],["11904","76","<b>שם מ\"ה דאדם</b>: נסמן לעיל ד, ב."],["11905","77","<b>ותקם בעוד לילה</b>: משלי לא, טו. ראה גם פיה\"מ מב, סע\"א. ביאוה\"ז אחרי עה, ד."],["11906","78","<b>כו'</b>: זיד: כל ימי החול."],["11907","79","<b>וירא אלקי'. . עשה</b>: בראשית א, לא."],["11908","80","<b>בוי\"מ</b>: ז: בו' ימי החול. יד: בהו' ימים. ועד\"ז להלן. וראה להלן הערה 146."],["11909","81","<b>שהתהו גבוה מהתיקון</b>: נסמן לעיל לט, ג."],["11910","82","<b>ויכולו השמים</b>: בראשית ב, א. ראה גם לעיל רכ, ב."],["11911","83","<b>וז\"ש</b>: זיד: (ו)זהו שנק'."],["11912","84","<b>מאד בלי גבול</b>: נסמן לעיל פ' וארא סא, ב."],["11913","85","<b>בב\"א</b>: זיד: בבת אחת."],["11914","*86","<b>התפלות. . כל יום. . השבת</b>: ראה לקמן פ' ויקהל תטו, ג. וש\"נ."],["11915","87","<b>התפלה. . סולם מוצב ארצה</b>: נסמן לעיל פ' וארא עח, א הערה 388."]]],[2300540364,"ארצה<sup data-n=\"11916\">86</sup> כו' שהתפלה הוא עלי' הגוף ובשבת הוא בחי' עלי' הנשמה כו'.\n<b>וזהו</b> ההפרש בין ג' מועדים לשבת שבחי' המועדים נמשך תמיד תוס' גילוי אורות בכלים מלמעלה למטה שלא ע\"י אתעדל\"ת כלל, אבל בשבת נמשך בחי' תוס' אור ע\"י העלאה מלמטה למעלה כנ\"ל. אך הנה זהו דוקא במועדים הראשוני' כמו פסח מצרים וחג שבועות שהי' אחריו קודם מ\"ת הן המה<sup data-n=\"11917\">88</sup> בחי' תוס' אורות<sup data-n=\"11918\">89</sup> המשכה מלמעלה למטה שלא ע\"י אתעדל\"ת כמ\"ש ופסח הוי' [כו'] וירד הוי' [כו'] הכל מעצמו, אבל כל המועדים שאנו עושים אחר מ\"ת גם ה[ם] כמו בחי' השבת שבחי' תוס' אור [ה]מתגלה למעלה בחג\"ת דז\"א אבל<sup data-n=\"11919\">90</sup> הוא ע\"י בחי' אתעדל\"ת, שהרי אנו עושים פסח ע\"י מצות התורה [ב]לבד שציוה ה' לאכול בו<sup data-n=\"11920\">91</sup> מצה ומרור זכר ליצ\"מ ועי\"ז אנו מעוררים למעלה שמתגלה בחי' תוס' אור חסד עליון דאצי' כמו שהי' מאיר בזמן יצ\"מ דכתי' ופסח ה' על הפתח<sup data-n=\"11921\">92</sup> כו'. ו[א\"כ הרי] סיבת תוס' גילוי אור חסד זה לא נמשך בעצמו רק ע\"י אתעדל\"ת ע\"י מעשה המצות דמצה ומרור [ו]ע\"י קדוש היום ו[ב]תפלת היום כו' ועי\"ז<sup data-n=\"11922\">93</sup> שעושין לזה היום קדש בכלל כו', משא\"כ פסח מצרים הרי הי' מעצמו בלי אתעדל\"ת כלל כמ\"ש ופסח הוי' כו'. ומה שציוה לאכול מצה כו' הרי הי' להיפך מטעם [שאנו אוכלים מצה, כי מה] שאנו אוכלים שהוא רק כדי לעורר למעלה, אבל מה שהיו הם אוכלים הוא מטעם שכבר נתעורר למעלה להיות מאיר <span data-k=\"pg\">שנג</span> ּ בדילוג כו' ולכך ציוה אותם ג\"כ לאכול קרבן פסח על מצות ומרורים כו' דהיינו המשכת חג הפסח שמלמעלה למטה, וזהו היפך הפסח שאנו עושי' לעורר מלמטה למעלה כו'. וכמ\"כ חג השבועות שעשו ה[ם] הגם שהי' אחר שספרו ז' שבועות<sup data-n=\"11923\">94</sup> כמ\"ש וספרתם לכם<sup data-n=\"11924\">95</sup> כו', מ\"מ יש הפרש גדול בין ספירה שלהם לספי' שלנו, כי ע\"כ<sup data-n=\"11925\">96</sup> הספי' שלהם הוא<sup data-n=\"11926\">98</sup> בחי' המשכה עליונה מלמעלה למטה כדי שיהיו ראוים לקבלת התורה<sup data-n=\"11927\">97</sup> כמ\"ש בזהר, ומצות ספה\"ע שלנו דכתי' ז' שבועות תספר<sup data-n=\"11928\">99</sup> לך שבא<sup data-n=\"11929\">100</sup> לעורר למעלה בחי' המשכת מוחי' [ב]ז' מדות<sup data-n=\"11930\">101</sup> ע\"י מצות הספי' שאנו מקיימין ע\"פ התו', והרי הוא בחי' הכנה והעלאה מלמטה למעלה כידוע. וא\"כ ממילא יש הפרש בין חג שבועות שלה[ם] דכתי' וירד הוי' שירד מעצמו, משא\"כ עכשיו אע\"פ שנמשך ויורד הארת הכתר בז\"א ע\"י מצות חג השבועות<sup data-n=\"11931\">102</sup> שאנו עושין כמ\"ש בפע\"ח, אבל זה גופא אינו נעשה ונמשך למעלה<sup data-n=\"11932\">103</sup> רק ע\"י מצות הספי' [שקדמה] תחלה בבחי' העלאה וע\"י [מצות] קידוש היום",[["11916","86","<b>התפלה. . ממוצעת. . סולם מוצב ארצה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370396\" data-slug=\"torah-or\" data-id=\"3901370396\">תו\"א ויקהל פח, א</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' שמג."],["11917","88","<b>המה</b>: ז: הי' מאיר. יד: היו."],["11918","89","<b>תוס' אורות</b>: שם: ליתא."],["11919","90","<b>אבל</b>: שם: ליתא."],["11920","91","<b>בו</b>: שם: ליתא."],["11921","92","<b>על הפתח</b>: שם: ליתא."],["11922","93","<b>ועי\"ז</b>: שם: וע\"י."],["11923","94","<b>חג השבועות. . שספרו ז' שבועות</b>: ראה גם לעיל פ' בא קכא, ג ובהערה 336."],["11924","95","<b>וספרתם לכם</b>: אמור כג, טו (לאחרי ביאתם לארץ)."],["11925","96","<b>ע\"כ</b>: זיד: ליתא."],["11926","98","<b>הוא</b>: שם: הי'."],["11927","97","<b>הספי' שלהם. . ראוים לקבלת התורה</b>: ראה זהר אמור צז, ב."],["11928","99","<b>ז' שבועות תספר לך</b>: פ' ראה טז, ט."],["11929","100","<b>לך שבא</b>: זיד: שהוא."],["11930","101","<b>המשכת מוחי' [ב]ז' מדות</b>: ראה פע\"ח (שער ספה\"ע) שכ\"ב, פ\"א."],["11931","102","<b>הכתר בז\"א. . חג השבועות</b>: ראה פע\"ח (שער חה\"ש) שכ\"ג, פ\"א."],["11932","103","<b>למעלה</b>: ז: למטה."]]],[2300540385,"לעשות מקראי קדש עפ\"י תורה כו'. וכמו\"כ חג הסוכות ש[אנו] עושין הוא ע\"י בחי' העלאה מלמטה [ל]עורר למעלה בחי' המשכת המקיפי', והוא ע\"י הסכך שאנו עושין במצות סוכה כהלכת[ה] ע\"פ התורה דוקא, וכן ע\"י מצות לולב ואתרוג כו'. משא\"כ חג הסוכות שעשו במדבר<sup data-n=\"11933\">104</sup>, הגם שנצטוו במצות ה' בסוכות תשבו<sup data-n=\"11934\">105</sup> כו' כי בסוכות הושבתי<sup data-n=\"11935\">106</sup> כו', הנה זה הי' מפני בחי' המשכ' עליונה שכבר נתעוררה עליהם בחי' המשכת המקיפי' ע\"כ צונו<sup data-n=\"11936\">107</sup> לעשות סוכה למטה ג\"כ, אבל סוכות דלדורות הוא לעורר בחי' המשכת המקיפי' שהי' מאיר עליהם במדבר וכמ\"ש הטעם כי בסוכות הושבתי כו' שהם ענני כבוד<sup data-n=\"11937\">108</sup> כידוע. ועד\"ז יובן כל פרטי המשכות אורות עליונים שבג' מועדים יש הפרש בין ג' מועדים שלהם למועדים שאנו עושין אחר מ\"ת ע\"פ דיני התורה שהן מלמטלמ\"ע באתעדל\"ת דוקא כנ\"ל בשרש ענין השבת וד\"ל.\n<b>אך</b> מ\"מ יש הפרש קצת בין שבת למועדים ורגלים דעכשיו ג\"כ, כי תוס' האור דשבת לא בא רק ע\"י שטרח כל ו' יומין דחול וכמבואר למעלה במשל המזון שמחי' לאדם כו', וגם כפי פשוטו דכתי' כי בו שבת וינפש<sup data-n=\"11938\">109</sup> ואין מנוחה רק אחר מלאכה דוקא. משא\"כ ג' המועדים שאנו עושים הגם שאנו מעוררים בהעלאה מלמטה ואם לאו אינו נמשך תוס' אורות בכלים כלל (וראי' מעובדא דריב\"ח עם ר\"ג<sup data-n=\"11939\">110</sup> דאמר לו ר\"ע מפסוק אשר תקראו אותם אפי' שוגגים אפי' מוטעים<sup data-n=\"11940\">111</sup> כו', ונמצא בחי' חג הפסח למעלה לא נעשה רק בזמן שסנהדרין למטה עושי' אותו ואפי' [הן מוטעים ו)עושים אותו ביום חול<sup data-n=\"11941\">112</sup> נעשה ונמשך למעלה בחי' הפסח כמו שהי' בזמן יצ\"מ כו' וכמ\"ש במ\"א וד\"ל), הרי מ\"מ אין זה האור הנמשך בתוס' הוא אור הנעשה ונמשך מחדש לגמרי, אלא הוא רק בחי' התעוררות המשכת אור שכבר האיר כמו בפסח לעורר [גילוי אור] חסד עליון שכבר האיר בזמן יצ\"מ כמ\"ש ופסח הוי' כו', וכן בשבועות לעורר ירידת האור דכתר עליון שכבר ירד במ\"ת כמ\"ש וירד הוי', משא\"כ בחי' אור דשבת שהוא המשכת אור חדש לגמרי<sup data-n=\"11942\">113</sup> הנעשה ע\"י הבירורי' כו' כנ\"ל וד\"ל.\n<b>ואחר</b> כל הנ\"ל יתורץ הקושי' בענין תיקון חצות וקביעות המועדים <span data-k=\"pg\">708</span> ּ שלמטה שמשתנים לפי האקלימי\"ם אלו עושים שבת ויו\"ט בזמן זה ואלו בזמן אחר, ולמעלה איך ישתנה זמנם הלא עת רצון למעלה לכולם בזמן א', וכן הארת שבת",[["11933","104","<b>הסוכות שעשו במדבר</b>: סוכה יא, סע\"ב. מכילתא בא יב, לז. תו\"כ אמור כג, מג."],["11934","105","<b>בסוכות תשבו</b>: אמור כג, מב."],["11935","106","<b>כי בסוכות הושבתי</b>: אמור שם, מג."],["11936","107","<b>צונו</b>: זיד: ציום."],["11937","108","<b>בסוכות. . ענני כבוד</b>: נסמן בהערה 104."],["11938","109","<b>כי בו שבת וינפש</b>: נסמן לעיל רט, ד."],["11939","110","<b>מעובדא דריב\"ח עם ר\"ג</b>: ר\"ה כה, א."],["11940","111","<b>אשר תקראו אותם. . מוטעים</b>: אמור כג, ד. ראה ר\"ה שם."],["11941","112","<b>חג הפסח. . ואפי'. . ביום חול</b>: ראה סידור שער המועדים רכ, א ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380080\" data-slug=\"likkutei-torah\" data-id=\"4001380080\">לקו\"ת ויקרא א, ג</a>."],["11942","113","<b>לגמרי</b>: זיד: ליתא."]]],[2300540405,"ויו\"ט למעלה א' הוא. אך הענין יובן ע\"פ הנ\"ל בשרש הענין או\"כ דאצי', דבחי' האור הוא בחי' גילוי המאציל להאציל הספי' ובחי' הכלים הוא בחי' התהוות מציא[ו]ת הספי' כו', ונמצא בבחי' זו נק' ע\"ס בלי מה כנ\"ל באריכות, ויובן מזה דבחי' האור נק' גילוי אור המאציל ובחי' הכלי הוא העלם [ה]גילוי [ה]זה כי עצם מציא[ו]ת הספי' נק' העלם האור. אך הנה גם בבחי' הכלים אמר דאיהו וגרמוהי חד<sup data-n=\"11943\">114</sup> כמו [שאמר] דאיהו וחיוהי חד<sup data-n=\"11944\">115</sup> משום דגם בחי' הכלים הן בחי' אלקו' ממש כמו האורות, וא\"כ לכאו' זה יסתור ענין הנ\"ל דבחי' הכלים נק' העלם האור להיות[ם] נחשבים בבחי' מציא[ו]ת דבר מה ואיך יאמר עליהם דאיהו וגרמוהי חד כמו בבחי' האורות שנק' ע\"ס בלי מ\"ה. אמנם זה הענין יובן בהקדים שיש ב' מיני כלים הא' נק' פנימי' הכלים שמתאחדים עם האורות וכנ\"ל בהפרש שבין מלאכים לנש\"י כו', והב' בחי' חיצוני' הכלים<sup data-n=\"11945\">116</sup> שנבדל[י'] מן בחי' האור. כי ענין חיצוני' הכלים הוא מה שיש בכח הכלי להשפיע שפע והמשכה למקבלים עד\"מ כלי המוח שמשפיע התחכמות מושכלים, משא\"כ עצם כלי המוח מתאחד עם אור השכל ההיולי, וכן כלי העין וכיוצא. [ו]נמצא דרך חיצוני' הכלים נמשך ונגלה שפע אור למטה נק' בחי' גילוי למקבלים, ובחי' פנימי' הכלים נק' בחי' העלם למקבלים וגם נק' העלם לגבי בחי' גילוי [אור מן המאציל (הרי יש ג' מדריגות גילוי והעלם וגילוי, ובוודאי אין ערוך לגילוי אחרון שמתגלה אחר צמצום ההעלם הכלי לגבי בחי' גילוי] הראשון מעצמות המאציל<sup data-n=\"11946\">117</sup>. והנה מבואר לעיל ב[שורש] ענין שבתות ויו\"ט דעכשיו שנעשה למעלה בחי' תוס' גילוי אורות בכלים ע\"י אתעדל\"ת כו', וענין בחי' תוס' גילוי אור הזה בהכרח לומר שהוא יותר מכפי המדה הקצובה בגילוי אור הראשון כנ\"ל עד שגם בחי' הכלים לא יסתיר ולא יעלים כ\"כ כו' וכנ\"ל באורך. ונמצא יש כאן ב' דברים, הא' הוא בחי' תוס' גילוי אור הראשון, והב' תוס' גילוי אור השני שאחר העלם הכלי רק שהא בהא תליא כו', וזהו עיקר ענין שבת ויו\"ט כנ\"ל, אך במועדים הראשונים הי' תוס' גילוי זה רק מצד אתעדל\"ע בלבד ועכשיו תלוי במעשה התחתונים כנ\"ל.\n<b>ומעתה</b> הנה יובן דכל עיקר ענין שבת ויו\"ט שהוא ענין שינוי התגלות [ה]אור בתוכו אין שינוי זה נוגע ל[גבי] עצמו' המאציל שהאציל או\"כ שהוא בחי' גילוי והעלם כנ\"ל כמ\"ש אני ה' לא שניתי<sup data-n=\"11947\">118</sup> כו', שהרי כל עיקר בחי' גילוי והעלם זה דאו\"כ או [העלם ו]גילוי שאחר העלם הכלי אין שייך רק לענין בחי' השפעה והמשכה למטה ל[גבי ה]מקבלים בלבד, דהיינו שאם האור מאיר בתוס' בכלים אזי יאיר למקבלים בתוס' ואם מאיר בצמצום יאיר להם בצמצום. אבל אין צמצום וריבוי זה ענין",[["11943","114","<b>דאיהו וגרמוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["11944","115","<b>דאיהו וחיוהי חד</b>: ת\"ז שם."],["11945","116","<b>פנימי' הכלים. . חיצוני' הכלים</b>: ע\"ח (דרוש עגו\"י) ש\"א, ענף ג."],["11946","117","<b>המאציל</b>: כנצ\"ל: המאציל)."],["11947","118","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."]]],[2300540425,"שינוי לגבי עצמו' המאציל שהרי<sup data-n=\"11948\">119</sup> עצמו' המאציל א\"צ להארת הגילוי כו', ואפי' בבחי' האורות והכלים שנאצלו ממנו אין דבר זה שינוי כלל מצד עצמם רק מצד בחי' הארתם והשפעתם למטה שהוא בבחי' חיצוני' הכלים כנ\"ל, אבל בבחי' פנימי' הכלים שמתאחד עם האורות ונק' [ה]כלי עצמו כמו עצם האור אין ריבוי ההארה או צמצום ההיא<sup data-n=\"11949\">120</sup> נק' שינוי <span data-k=\"pg\">שנד</span> ּ כלל מאחר שמיוחד בעצמו' המאציל ממש וכמ\"ש דאיהו וחיוהי חד ואיהו וגרמוהי חד כנ\"ל באריכות וד\"ל. ואע\"פ שהכלי נק' העלם האור אין זה רק בשביל המקבלים בלבד, ויובן זה עד\"מ מזריחת האור [של] השמש בחלונות הפתוחים או בכלי הזכוכית הבהירה שאם יסתמו החלון קצת במסך וימעיטו הארת השמש או יעכרו את הזכוכית שלא יאיר בה הארת השמש בבהירות, הרי גם שזכוכית זאת העלימ[ה] את האור אין זה עושה שינוי כלל בעצם אור השמש כי עצם בהירו נשאר במעמדו ומדרגתו ממש כמו שהאיר בה בתחלה, רק שלא נגלה הארתו עתה לאדם בזכוכית או במסך החלון מפני עוביים ומיד שיס[י]רו אותם יאיר האור כבתחלה, ונמצא מובן מזה למעלה דמצד עצם האור והכלי המעלים אין העלם זה שינוי כלל רק למה שלא יאיר למקבלים בלבד כנ\"ל וד\"ל. ויובן דבר זה בתוס' ביאור עד\"מ אור השכל הרוחני המתעלם בלבושי' והעלמות משלים וחידות הרבה שאין העלם זה רק למקבלים אבל לגבי [ה]משפיע אין שינוי כלל בהעלם המשלים וגם לגבי עצמו' האור השכל הנשפע אין זה ההעלם שינוי כלל כו' כמ\"ש במ\"א וד\"ל.\n<b>ועפ</b>[כ]\"ז יובן למשכיל תירוץ הקושי' הנ\"ל<sup data-n=\"11950\">121</sup> דהנה שרש הזמן דעבר הוה כו'<sup data-n=\"11951\">122</sup> הוא מבחי' [מל'<sup data-n=\"11952\">123</sup> ] מ‘לך מ לך וימלוך<sup data-n=\"11953\">124</sup> כו' וכמ\"ש בע\"ח בענין מ\"ע שהזמן גרמא<sup data-n=\"11954\">125</sup> נשים פטורות ששרש הזמן בנוק' דז\"א כו', ומקור בנין המל' הוא מבחי' למ\"ד כלים דז\"א כידוע והוא מבחי' חיצוני' הכלים המתגלים למטה אחר ההעלם כנ\"ל. אך בשבת ויו\"ט מתגלה בחי' תוס' גילוי אור ע\"י מעשה התחתונים כשעושים קדושת שבת ויו\"ט למטה כנ\"ל, אמנם הנה אין תוס' גילוי זה עושה שינוי כלל בעצמו' או\"כ מפני שהם למעלה גם ממקור הזמן דמל' מאחר שהם למעלה גם מבחי' השפעה למקבלים. והגם שבשבת ויו\"ט מאיר מבחי' פנימי' או\"כ, אין שינוי זה רק לענין השפעה למקבלים בלבד כנ\"ל ולא לגבי עצמותו כו'. וא\"כ הגם שאין זמן שבת ויו\"ט שוה בכל האקלי[מי]ם דהיינו שבאקלים זה מעוררים תוס' גילוי אורות בכלים למעלה ולגבי אקלי\"ם אחר האור הזה הוא בהעלם כמו בחול, אין זה שינוי כלל לגבי עצמות שלהם, אלא בכל אקלי\"ם שנשלם מעשה התחתוני'<sup data-n=\"11955\">126</sup> לעורר למעלה תוס' גילוי אור זה אז מאיר להם למעלה, ובהגיע זמן שבת ויו\"ט",[["11948","119","<b>המאציל שהרי</b>: זיד: כלל שהרי (גם) בחי'."],["11949","120","<b>ההיא</b>: שם: ההארה."],["11950","121","<b>הנ\"ל</b>: יד: הב'."],["11951","122","<b>כו'</b>: זיד: ועתיד."],["11952","123","<b>הזמן. . מבחי' [מל']</b>: ראה גם לעיל רלד, א. וש\"נ."],["11953","124","<b>מלך מלך וימלוך</b>: ראה זהר בראשית לד, א."],["11954","125","<b>בע\"ח בענין מ\"ע שהזמן גרמא</b>: קדושין כט, א (במשנה). ראה ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קלח ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ב ס\"ע תרכב. וש\"נ. נ\"ך ע' רכו. וש\"נ. שע\"ת קה, ב."],["11955","126","<b>בכל אקלי\"ם שנשלם מעשה התחתוני'</b>: ראה גם צפנת פענח — להר\"י מטראני — פ' בראשית ח, א."]]],[2300540445,"באקלי\"ם האחר מאיר להם למעלה בחי' תוס' גילוי זה כו', אבל לגבי העצמות נק' יום שכולו שבת<sup data-n=\"11956\">127</sup> וד\"ל (ומ\"ש ביום הז' שבת להוי'<sup data-n=\"11957\">128</sup> דוקא וכן גם ביום שכולו שבת הרי נק' יום והוא אל\"ף הז' והרי יש בחי' זמן קבוע למעלה בשוה, היינו רק בו\"ק דאצי' שמאירים למטה בבחי' זמן עד ו\"ק דעשי' ולכל אקלי\"ם ששובת הרי נק' יום הז' שלהם כו' וד\"ל).\n<b>ולהבין</b> זה בתוס' ביאור, וגם לתרץ הקושי' היטב ע\"ד הכתוב דביום הז' שבת למעלה הוא בזמן א' וכמ\"ש ביום השביעי דוקא שבת להוי' כו', וע\"פ תירוץ הנ\"ל גם למעלה אין זמן השבת שוה כנ\"ל, וגם איך יאיר האור בכלי<sup data-n=\"11958\">130</sup> לגבי האקלי\"ם זה ולגבי אקלי\"ם אחר הוא בהעלם ואיך יהי' העלם וגילוי כא' (וזה<sup data-n=\"11959\">129</sup> דוחק לומר שזמן זה (יום הז') דוקא דעשי' משתנה לפי מקומות האקלי\"ם כנ\"ל, אחר שבחי' זמן הגשמי דז' <span data-k=\"pg\">710</span> ּ ימים שלנו סובב והולך ע\"פ הזמן הרוחני דו\"ק דעשי' כמ\"ש ששת ימים עשה ה'<sup data-n=\"11960\">131</sup> כו' שהן מז' יומין עילאין דהיינו מו\"ק דבי\"ע כו', א\"כ יום הז' בכל הארץ בשוה כו'). אך הנה יובן הטעם ע\"פ הנ\"ל שיש ב' מיני ג[י]לויים, הא' הוא בחי' גילוי הראשון בכלי, והב' גילוי השני לאחר הצמצום והעלם הכלי מבחי' תוס' גילוי אור, היינו שמחמת תוס' גילוי אור הראשון בוקע ועובר גם דרך הכלי ומאיר בתוס' גילוי למקבלים כו' [ומבואר למעלה ששינוי זה שנתוסף אור למקבלים אין זה שינוי כלל וכלל לגבי בחי' גילוי אור הנתוסף בכלי מצד עצמיות המאציל כו']. והנה עפ\"ז יובן ג\"כ בשרש התהוות הזמן, דהנה מקור הזמן במל' הוא בבחי' הכלים דז\"א דוקא כנ\"ל, אבל בחי' גילוי אור הראשון הוא למעלה ממקור הזמן כו', וא\"כ בחי' אור השבת שבא באורות עליונים הרי הוא למעלה מבחי' הזמן. ומ\"ש ביום הז' שבת להוי' היינו בבחי' גילוי אור שמאיר בכלים דוקא, דהיינו מה שהאור בוקע אורו ועובר גם דרך הכלי והכלי מתבטל לגבי האור ומאיר למקבלים ג\"כ, וזה הדבר התלוי בזמן דהיינו ביום הז' שהוא בחי' מל', כי יום הא' שהוא בחי' כלי החסד דז\"א עדיין אין האור בוקע ועובר דרך הצמצום של הכלי כו' וכן ביום הב' שהוא בבחי' הגבורה כו' עד יום הז' וע\"כ נק' שבת מלכתא<sup data-n=\"11961\">132</sup> כו' וכמ\"ש הטעם במ\"א כו'. אבל בבחי' גילוי אור הראשון אין הדבר תלוי בזמן, כי מאיר בתמידות להיותו למעלה מבחי' התחלקו' הזמן לגמרי והוא למעלה גם מבחי' יום שכולו שבת, מאחר שיום שכולו שבת שהוא אלף הז' הוא בא ג\"כ בגדר זמן בכללות שיתא אלפי שנין דהוי עלמא<sup data-n=\"11962\">133</sup> כו'. אך עדיין יש להבין תירוץ קושי' הנ\"ל דממ\"נ בבחי' האור עצמו הוא למעלה מהזמן לגמרי כנ\"ל, ובבחי' הארת האור דרך הכלי כו' הרי תלוי הז'<sup data-n=\"11963\">134</sup> בזמן א' קבוע עכ\"פ דהיינו ביום הז' דוקא ולא בזמנים רבים שונים ומתחלפים, והרי באקלים שבארץ שזמן השבת",[["11956","127","<b>יום שכולו שבת</b>: תמיד בסופה."],["11957","128","<b>ביום הז' שבת להוי'</b>: יתרו כ, י. ואתחנן ה, יד [ושם: ויום]."],["11958","130","<b>בכלי</b>: ז: (כתבו והסגירו וממעל לשורה כתב) בגילוי. יד: בה."],["11959","129","<b>וע\"פ. . (וזה</b>: ז: (וע\"פ. . וזה."],["11960","131","<b>ששת ימים עשה ה'</b>: תשא לא, יז."],["11961","132","<b>שבת מלכתא</b>: נסמן לעיל רכ, ד."],["11962","133","<b>שיתא אלפי שנין דהוי עלמא</b>: ראה ר\"ה לא, א. הנסמן במאמרי אדה\"א בראשית ע' נג."],["11963","134","<b>הז'</b>: ז: זה. יד: ליתא."]]],[2300540465,"משתנה אצלם כנ\"ל בהכרח לומר שגם למעלה מאחר שאתעדל\"ע תלוי באתעדל\"ת משתנה זמן השבת לפי שינוי זמני שבת למטה. וגם איך יוכל להיות שמאיר אור דרך הכלי לגבי אתעדל\"ת דאקלי\"ם זה ובאותו הזמן הוא יום חול להיות האור בהעלם לגבי אקלי\"ם אחר כו' כנ\"ל.\n<b>אך</b> הנה תחלה יש לתרץ הקושי' השני' ואח\"כ יתורץ גם הקושי' הראשונה, והוא בהקדים לזה ענין א' הידוע בע\"ח דבחי' הכלים דע\"ס דז\"א נחלקים כאו\"א ליו\"ד ויו\"ד למאה ומאה לאלף כו' עד שיש ס' ריבוי מדרגות שהם ת\"ר אלף שרשי נש\"י שהם מסתעפים מבחי' ו\"ק דז\"א<sup data-n=\"11964\">135</sup> מצד בחי' ריבוי התחלקות הכלים. והנה ע\"ד דוגמא ס\"ר נש\"י מפוזרים בכל כדור הארץ ויש הרבה מהם במקום א' ששרשם הוא מבחי' כלי נצח שבחסד דז\"א המתחלק ליו\"ד ויו\"ד למאה ומאה לאלף כו' עד שיש ס\"ר כו' והן עושי' יום השבת או יום המועד והרגל באתעדל\"ת, הנה ע\"י אתעדל\"ת שלהם ודאי מעוררים אתעדל\"ע בשרש כללות מחצב נשמתם שהוא בבחי' כלי נצח שבחסד דז\"א לפ\"ע ריבוי מספרם, דהיינו שמאיר האור בהסתר הכלי נצח דז\"א בתוס' גילוי אור להאיר למקבלים למטה. וגם אם הם מועטין מאד <span data-k=\"pg\">שנה</span> ּ מעוררים למעלה, אף שאינם מעוררים כל ההסתעפות שיסתעף מריבוי התחלקות הכלים [נצח] שבז\"א אלא רק בפרט א' מפרטי ההתחלקות מהכלים דנצח, אבל באורו הפרט יאיר האור דרך הכלי ונעשה למעלה בחי' שבת ויו\"ט. והנה יש עוד הרבה מישראל במקום א' בכדור הארץ ששרשם בכלי הוד דז\"א, וזמן השבת אצלם ביום אחר מאותו יום שהי' בחי' שבת למעלה בבחי' כלי דנצח לגבי אנשי המקום ואקלי\"ם שהם מבחי' נצח, הי' אז בחי' חול ממש למעלה בבחי' כלי הוד דז\"א לגבי אנשי המקום ואקלי\"ם שהם מבחי' הוד שאצלם הי' יום חול, וכשמגיע יום וזמן<sup data-n=\"11965\">136</sup> שבת שלהם מאיר האור בתוס' גילוי בכלי ההוד, ואז הוא יום חול למעלה בכלי הנצח דהיינו שהאור בכלי הנצח מוסתר בכלי כו'. ועד\"ז יש הרבה שינוים למעלה מפני ההתחלקות הכלים דו\"ק דז\"א שלפעמים האור מאיר דרך כלי פרטי' והוא נק' יום שבת למעלה (וביום הז' דוקא כמשי\"ת) ובכלי אחרת זולתה הוא יום חול שהאור מוסתר בכלי, ויכול להיות עכ\"ז<sup data-n=\"11966\">137</sup> כמה מיני מדרגות פרטיות שבכלים דז\"א ששם האור מאיר בתוס' ולזולת[ה] לא יאיר בגילוי, וזה תלוי בשינוי הזמן [ד]שבתות ויו\"ט באקלי[מי]ם שלמטה לפי אתעדל\"ת שלהם, דהיינו שאנשי האקלי\"ם זה [ש]שרש אחיזתם למעלה בכלי פרטי' מעוררי' הגילוי בהגיע זמנם ואנשי האקלים האחר מעוררים בזמן אחר בשרש אחיזתם למעלה בכלי אחר כו'. ומעתה יתורץ הקושיא הב' איך יוכל להיות העלם וגילוי כא' למעלה העלם לגבי אקלים זה וגילוי לגבי אקלים אחר כו', דאם הי' בחי' הגילוי",[["11964","135","<b>ת\"ר אלף שרשי נש\"י. . ו\"ק דז\"א</b>: ראה גם לקו\"ת להאריז\"ל פ' וישב דרוש גלות מצרים. לקמן רמו, ד."],["11965","136","<b>יום וזמן</b>: זיד: זמן."],["11966","137","<b>עכ\"ז</b>: שם: עד\"ז."]]],[2300540484,"או ההעלם במקום א' ומדרגה א' שבאצי' הי' דבר שא\"א להיות העלם וגילוי כא', אבל מאחר שיש בחי' התחלקו' הכלים לס\"ר מדרגות הרי יוכל להיות גילוי בבחי' כלי זה והעלם בבחי' כלי זה האחרת<sup data-n=\"11967\">138</sup> כו' וד\"ל.\n<b>ומעתה</b> יתורץ גם [ה]קושי' האחרת<sup data-n=\"11968\">139</sup>, אך יש להקדים תחילה שאין שינוי זה שהאור בגילוי בכלי זה ובהעלם בכלי אחרת רק שהוא<sup data-n=\"11969\">140</sup> בבחי' התגלות למקבלים בלבד שהוא בחי' גילוי הב' הנ\"ל, אבל בבחי' גילוי הראשון להיותו למעלה מבחי' גילוי למקבלים וגם מצד בחי' הכלים מאחר שהם עצם א' עם האור[ות] כנ\"ל, אין זה נק' שינוי כלל מה שבכלי זה האור בא בהעלם ובכלי האחרת הוא מאיר בגילוי, עד\"מ אור השכל המאיר ובא בגילוי בכלים מכלים שונים דהיינו כמה מיני משלים וחידות [ב]משל זה מתלבש אור השכל באופן זה ובמשל אחר באופן אחר, והרי ידוע דהמשל מעלים את אור השכל העצמי מאחר שהמשל הוא מעניני' זרים כו' רק [ש]אחר ההסתר והעלם של המשל יוכל המקבל להבחין ולעמוד על דבר החכ' שהוא הנמשל מן המשל [הזה]. וה\"ז דמיון [ל]ענין הארת אור השכל שבוקע ועובר דרך עובי הכלי כנ\"ל, כך הארת השכל עובר דרך צמצום דברי המשל, כמו משלי שלמה וכיוצא שיכולים להשכיל ולעמוד על הנמשל מהן שהן חכ' נפלאות כו'. והנה לפעמים יאיר ויבקע אור השכל לצמצום ענין המשל עד שיובן כל המכוון הפנימי <span data-k=\"pg\">712</span> ּ שבשכל [ה]הוא מתוך המשל, ולפעמים לא יאיר השכל כ\"כ ויתעלם קצתו במשל ולא יובן ממנו רק אפס קצהו, ולפעמים מתעלם כל אור השכל לגמרי במשל זה. ואמנם יאיר אורו מתוך משל אחר, אעפ\"י שהמשל האחר יגלה אור השכל באופן אחר מ\"מ יתגלה הוא בתוכו עפ\"י אותו האופן, ובאותו אופן של<sup data-n=\"11970\">141</sup> משל זולתו נתעלם לגמרי או קצת כנ\"ל. וכאשר ימצא אדם ריבוי משלים לשכל אחד יוכל להיות כמה מיני מדריגות חלוקים בענין התגלות אור השכל הזה, דהיינו שבאופן משל זה נתגלה חלק א' ממנו א' וב'<sup data-n=\"11971\">142</sup> וג' חלקים ובמשל אחר לא נתגלה כלום ממנו ובמשל הג' נתגלה חיצוני' שבו ולא פנימיותו ובמשל הרביעי נתגלה גם פנימיותו כו' וכיוצא. והנה כל אלה מיני התגלות המחולקים אינם עושי' שינוי כלל בגוף אור השכל המאיר ומתלבש בכמה שינוי<sup data-n=\"11972\">143</sup> משלים כו', כי הרי הוא מתלבש בכלים, רק הגילוי בזה הוא יותר מבזה, ואין זה שינוי רק ל[גבי ה]מקבלים הבנת השכל מתוך לבוש המשל שלזה יאיר ולזה לא יאיר כנ\"ל, או למקבלים באופן משל זה יאיר ולמקבלים באופן משל אחר לא יאיר כלל או אפס קצהו וכיוצא. אך הנה יובן עוד כאשר אור השכל מתעלה ופושט מלבושי המשל[ים] שאז לא יסתירו המשלים כלל, כמו אור [השכל] כ[מו] שהוא אצל המשפיע עצמו שאינם צריך להלבישו כלל במשלים וחידות כי אינו",[["11967","138","<b>זה האחרת</b>: שם: אחרת."],["11968","139","<b>האחרת</b>: שם: הא'. וראה גם הערה 149."],["11969","140","<b>שהוא</b>: שם: ליתא."],["11970","141","<b>ובאותו אופן של</b>: שם: ובאופן."],["11971","142","<b>א' וב'</b>: ז: או ב'."],["11972","143","<b>שינוי</b>: זיד: מיני."]]],[2300540502,"מלבישו רק למקבלים כידוע, [הרי] אז הארתו בוקע ועובר לכל העלמו' של רבוי המשלים בהשוואה א', רק כשמתפשט' פנימי' הארה זאת למקבלים דרך עובי הלבשו' המשלים אינו מאיר בהשוואה א', שלמקבלים הללו יאיר את עובי המסך של המשל תחלה ואח\"כ יתפשט עוד [ויאיר למקבלי' דרך מסך אחר ואח\"כ יתפשט עוד במשל] הג' והד' עד שעובר את כולם. והרי כל מה שנתעכב האור להאיר את כולם אין זה מצד עצם רק מפני חילוק המדריגות המקבלים בלבד, אבל מצד עצמו הרי הי' כ\"ז בסקירה א' רק שנמשך ונתפשט אח\"כ בכלים רבים כו' וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למשכיל למעלה בשרש כללות ענין השבת למעלה דכתי' כי בו שבת וינפש דהיינו בחי' הארת פנימי' אור אבא עד\"מ כשאדם ש[ו]בת ונח בשכלו [מל]התלבש במשלים למקבלים כנ\"ל עד<sup data-n=\"11973\">144</sup> שבא אור השכל ההוא [א]ל עצמו' המשפיע כו'. וכך בראשית ברא וביום הז' חוזר אור החכ' דאצי' אל בחי' עצמו' המאציל ונק' נייחא דרוחא<sup data-n=\"11974\">145</sup> כידוע. והנה כל וי\"מ<sup data-n=\"11975\">146</sup> בחי' חכ' זו מתלבש[ת] בכלים רבים שהם בחי' ו\"ק דז\"א יום א' בחסד ויום ב' בגבורה כו', ו[ב]יום הז' מתגלה האור תוך העלם הכלי הנ\"ל ויוכל להיות גילוי העלם כלי זה בפרט בכלי<sup data-n=\"11976\">147</sup> זה ולא באחרת כנ\"ל, ואין זה שינוי לגבי בחי' גילוי האור כו' מצד עצמו שהוא בחי' השבת בכללות וכמ\"ש כי בו שבת, רק שאח\"כ מתפשט ומאיר דרך עובי כל כלי וצמצום בזא\"ז לפי אופני אתעדל\"ת שלמטה באקלי[מי]\"ם שלמטה, אלה מעוררים גילוי העלם כלי נצח דז\"א ואח\"כ באקלי[מי]\"ם שלמטה<sup data-n=\"11977\">148</sup> האחר[ים] מעורר[ים] גילוי העלם הכלי דהוד כו' כנ\"ל. וה\"ז כדמיון הארת השכל דרך הלבשת המשלים שלפעמים מאיר תחלה בזה ואח\"כ באחר שאין שינוי זה רק מצד <span data-k=\"pg\">שנו</span> ּ המקבלים בלבד כו' וד\"ל.\n<b>ומעתה</b> יתורץ היטב גם הקושי' הא'<sup data-n=\"11978\">149</sup> הנ\"ל איך [יהי'] זמן השבת למעלה א' ביום הז' דוקא ולמטה משתנה הזמן לפי האקלימי\"ם, דממ\"נ מצד האור עצמו הוא למעלה מהזמן [לגמרי] ומצד בחי' התגלותו בכלים הרי תלוי בזמן זה כנ\"ל. דהנה הארת כללות [ה]שבת המאיר [מ]עצמו' המאציל ה\"ז כמשל התפשטו' אור השכל מן הלבושים [של ה]משל[ים] ואז מאיר לכל בחי' התחלקו' הזמן דשיתא אלפי שני כא' ממש, ואח\"כ מתפשט[ת] הארה זו ומתפשטת<sup data-n=\"11979\">150</sup> ומתחלקת להאיר לכלים רבים כו' ונעשה כמה מיני מדריגות שבת כמו לכל הז' ימים שבפרט כ\"א בבחי' הכלים דז\"א כמו בנצח דז\"א שובת ביום הז' שלו שהוא בחי' המל' וכן בשארי פרטים. אמנם כללות הארה זו<sup data-n=\"11980\">151</sup> מ\"ש ביום הז' שבת להוי' כו' כי בו שבת כו' שנק' יום שכולו שבת, דהיינו לאחר העלמ[ו] בששת מיני העלמות [ב]כלים כללים מקור<sup data-n=\"11981\">152</sup>",[["11973","144","<b>עד</b>: שם: ליתא."],["11974","145","<b>נייחא דרוחא</b>: ראה גם שה\"א כט, א ובהנסמן במ\"מ לשם."],["11975","146","<b>וי\"מ</b>: ז: ניתוסף: החול. יד: ו' ימי המעשה. וראה לעיל הערה 80."],["11976","147","<b>כלי זה בפרט בכלי</b>: ז: הכלי בפרט כלי. יד: בפרט כלי."],["11977","148","<b>שלמטה</b>: שם: ליתא."],["11978","149","<b>הא'</b>: שם: הראשונה. וראה גם הערה 139."],["11979","150","<b>ומתפשטת</b>: שם: ליתא."],["11980","151","<b>זו</b>: שם: הוא."],["11981","152","<b>מקור</b>: ז: שרש ומקור. יד: שהמה מקור."]]],[2300540520,"כללות הזמן דשיתא אלפי שנין כו' שבת וינפש, והוא יום הז' למעלה בכלל הנק' אלף הז' למטה כידוע שיש בכל שבת מהארת יום זה שכולו שבת<sup data-n=\"11982\">153</sup> כו'. ונמצא שאע\"פ שגילוי אור הראשון הזה הוא למעלה מבחי' הזמן הבא בכלים ומאיר בכללותם יחד, אבל מ\"מ מתפשט ונמשך אח\"כ בסדר זמן שלכל<sup data-n=\"11983\">154</sup> הכלים כו'<sup data-n=\"11984\">155</sup>. וא\"כ לק\"מ גם משינוי הזמן<sup data-n=\"11985\">156</sup> זמני השבת שלמטה מפני שמקבלים מבחי' הזמן השבת שבכל כלי וכלי [ד]אצי' בפרט, ואין יום הז' של הכלי זה שוה בזמן א' עם יום הז' של כלי זולתה, להיות כי כל הכלים הם בבחי' התחלקות הזמן ובחי' יום הז' הכללי מאיר בכאו\"א. ומה שמתאחדי' זע\"ז אין זה שינוי כלל לגבי בחי' גילוי האור הכלי עד\"מ מהתחלקות הזמן של שס\"ה יום בר\"ה ול' יום בר\"ח שא\"א לומר בר\"ה יום האחרון בשס\"ה בא [ב]אחרונה אלא כולם נסקרים כאח' ממש וד\"ל.\n<b>ואחר</b> הקדמה הנ\"ל יובן שרש ענין מ\"ש צדקת פרזונו בישראל כו', דהנה פי' ישראל היינו לי ראש שהוא בחי' התכללות האורות בחי' [ה]תיקון שנק' אדם ונק' ישראל וכמ\"ש ואלה המלכים כו' לפני מלוך מלך לבנ\"י<sup data-n=\"11986\">157</sup> כו'. והטעם הוא שישראל הוא בחי' התיקון, היינו מפני שנעשה בחי' חיבור והתכללו' האורות ע\"י שמתחברי' האורות בריבוי קודם<sup data-n=\"11987\">158</sup> מכלים שונים כו' כמ\"ש במ\"א בפי' הפסוק מי שם פה לאדם<sup data-n=\"11988\">159</sup> כו'. וזהו פי' דתיבת ישראל<sup data-n=\"11989\">*160</sup>, כי הנה פי' שר לשון שררה לשון אדנות<sup data-n=\"11990\">160</sup> הוא בחי' גבורות ודינים כמלך ושר שמושל ושליט לענוש את עבדיו ותפול אימתו עליהם שהוא בחי' גבורות ודינים, והיינו שרש בחי' שם אדנ\"י א' דין<sup data-n=\"11991\">161</sup> דינא דמלכותא<sup data-n=\"11992\">162</sup> כו', וכן פי' אלקי', וע\"כ נק' המל' מטרוניתא<sup data-n=\"11993\">163</sup> לשון שררה כו' ששרש בנין המל' מבחי<sup data-n=\"11994\">164</sup>' הגבורות<sup data-n=\"11995\">165</sup> דז\"א שנק' שר ושופט כמ\"ש השופט כל הארץ<sup data-n=\"11996\">166</sup> אדון כל הארץ<sup data-n=\"11997\">167</sup> כו'. ופי' אל הוא [בחי'] ה\"ח<sup data-n=\"11998\">168</sup> דז\"א כמ\"ש כי חסד אל כל היום וכמ\"ש כי אמרתי עולם חסד יבנה שעיקר בנין העולם שנקרא ז\"א<sup data-n=\"11999\">169</sup> מהחסדים הוא מצד",[["11982","153","<b>בכל שבת. . שכולו שבת</b>: נסמן לעיל לג, ג."],["11983","154","<b>שלכל</b>: זיד: של."],["11984","155","<b>כו'</b>: יד: דו\"ק."],["11985","156","<b>הזמן</b>: זיד: ליתא."],["11986","157","<b>ואלה. . מלך לבנ\"י</b>: וישלח לו, לא."],["11987","158","<b>קודם</b>: זיד: כלי'."],["11988","159","<b>מי שם פה לאדם</b>: ראה ד\"ה זה לעיל פ' שמות מה, א ואילך ובהנסמן בריש המאמר שם."],["11989","*160","<b>פי' דתיבת ישראל</b>: ראה גם לקמן רמו, ב."],["11990","160","<b>לשון אדנות</b>: זיד: ואדנות."],["11991","161","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380925\" data-slug=\"likkutei-torah\" data-id=\"4001380925\">אדנ\"י א</a>' דין</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"ה. מבו\"ש ש\"ה ח\"א פ\"ג ובהגהת צמח שם הגה ג. סידור תפלת ר\"ה רלו, ג. לקו\"ת נצבים נא, ג. מאמרי אדה\"א דברים ח\"ג ע' א'ט ואילך. בראשית ע' קצח. במדבר ח\"ג ע' א'נג. לעיל פ' בא פח, ג."],["11992","162","<b>דינא דמלכותא</b>: גיטין י, ב."],["11993","163","<b>המל' מטרוניתא</b>: נסמן לעיל קצ, א."],["11994","164","<b>בנין המל' מבחי' הגבורות</b>: ראה סידור שחרית מא, א: כמ\"ש בע\"ח בענין הדלקת נרות המנורה [שער תיקון הנוקבא — של\"ד, פ\"ה]. סה\"מ תרמ\"ו ע' י: וכמ\"ש בהקדמת הזהר בתחילתו במק\"מ שם. מאמרי אדה\"א דברים ח\"א ע' ריח. וש\"נ."],["11995","165","<b>הגבורות</b>: ז: ה\"ג. יד: ה' גבו'."],["11996","166","<b>השופט כל הארץ</b>: וירא יח, כה."],["11997","167","<b>אדון כל הארץ</b>: יהושע ג, יא."],["11998","168","<b>אל. . ה\"ח</b>: ראה זהר צו ל, ב. אחרי סה, א. מבוא שערים ש\"ג ח\"ב פט\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 39."],["11999","169","<b>העולם. . ז\"א</b>: ראה ע\"ח (שער הארת המוחין) של\"ב, פ\"ה. (שער לאה ורחל) של\"ח, פ\"ט. שער מאמרי רז\"ל (סנהדרין צז, א) ל, ב."]]],[2300540538,"הארת אור אבא בז\"א שמשם מקור כל החסדי' וכמ\"ש כי אתה אבינו וכמ\"ש במ\"א בפי' מאמר הזהר בתלת דוכתי נק' אתה<sup data-n=\"12000\">170</sup> כו', וז\"ש אתה כהן לעולם<sup data-n=\"12001\">171</sup> כו', ולפי שבחי' ז\"א רובו חסדים ומיעוט[ו] גבו' כמ\"ש בע\"ח<sup data-n=\"12002\">172</sup>, ע\"כ נק' ישראל שהוא חיבור חו\"ג שנק' ש\"ר <span data-k=\"pg\">714</span> ּ א\"ל<sup data-n=\"12003\">173</sup> והוא ע\"י אות [ה]יו\"ד דישראל שהוא המחבר חו\"ג יחד, וכן פי' שי\"ר א\"ל<sup data-n=\"12004\">174</sup> היו\"ד ממתיק הגבורות<sup data-n=\"12005\">175</sup> מחסדים דא\"ל והיינו ע\"י תוקף החסדים והתגברותם על ה\"ג<sup data-n=\"12006\">176</sup>, כמ\"ש כי גבר עלינו חסדו<sup data-n=\"12007\">177</sup> כו' וכמ\"ש כי שרית עם אלקי'<sup data-n=\"12008\">178</sup> כו' שנשתרר ונתגבר על בחי' גבורות דשם אלקי'.\n<b>והענין</b> הוא כי בחי' הגבורות כאשר הם מתהפכי' לחסדי' הרי נעשי' בחי' גבו' שבחסד שהוא תוקף החסדי' והתגברותם עד שיש בכחם להמתיק לבחי' הגבורו' לחסדים, כי יש חסדים שאינם באים בגבו' ותוקף ואין בכחם להמתיק כו'. אבל בפי' ישראל א[מר] כי שרית עם אלקי', שנתגבר ונשתרר להמתיק לגבורו' דשם אלקי'<sup data-n=\"12009\">179</sup> שממנו מקבל שרו של עשו שהוא בחי' ז\"א דקליפה<sup data-n=\"12010\">180</sup> שנאחז [ב]בחי' אחוריי' [דשם אלקי'] שבז\"א דקדושה ולכך נא' עליו ויאבק איש עמו<sup data-n=\"12011\">181</sup> כו' וכמ\"ש במ\"א. וכמו גבורות גשמים<sup data-n=\"12012\">182</sup> שהן מ[י] חסדי' היורדי' בגבו' בתוקף גדול ולכך נא' בהם גשם נדבות תניף אלקי'<sup data-n=\"12013\">183</sup> שממתיקי' לבחי' גבורות דשם אלקי' כמ\"ש במ\"א. והנה סיבת תוקף החסדים<sup data-n=\"12014\">184</sup> בא מהארת אור אבא שבה<sup data-n=\"12015\">185</sup> מקור ההחסדים, והוא ענין היו\"ד דישראל שיגבור החסד על הדין עד שיוכל להתחבר יחד, כי כאשר הם שקולים כא'<sup data-n=\"12016\">186</sup> לא יתחברו כי כאו\"א יאיר בתוקפו ומנגד להיפוכו, אך כאשר יגבר א' ויכנע הב' תחתיו אזי יתחברו יחד. וכמ\"כ מ\"ש בס\"י טרף אש ומים ובללן יחד<sup data-n=\"12017\">187</sup> אין זה בא כ\"א בהתגברות החסד על הגבורות ומקור התגברות [זאת] הוא בא ממקור החסדי' שהוא בחי' אור אבא. וז\"ש באברהם איש החסד<sup data-n=\"12018\">188</sup> והוא יושב פתח האהל<sup data-n=\"12019\">189</sup> כחום היום דמל'<sup data-n=\"12020\">190</sup> או בינה<sup data-n=\"12021\">191</sup> בתגבורת אור החסד דז\"א שנמשכי' מהחסדים דאבא. אמנם מה",[["12000","170","<b>בתלת דוכתי נק' אתה</b>: זהר בלק קצג, ב ובמק\"מ שם. ראה סידור שחרית לט, ג. מאמרי אדה\"ז על מארז\"ל ע' שמג. ע' תכט. ע' תלד. תקס\"ו ע' שיט. פיה\"מ ס, א ואילך. וראה ביאוה\"ז לך י, רע\"ב."],["12001","171","<b>אתה כהן לעולם</b>: תהלים קי, ד."],["12002","172","<b>ז\"א רובו חסדים. . בע\"ח</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670441\" data-slug=\"torat-chaim\" data-id=\"2300670441\">תו\"ח וירא קד, ד</a> הערה 33."],["12003","173","<b>ישראל. . ש\"ר א\"ל</b>: ראה פע\"ח (שער הק\"ש) ש\"ח, פ\"ט. מאמרי אדה\"א דברים ח\"ב ע' תקנז. ח\"ג ע' א'פ. שמות ח\"ב ע' תמב. הנחות תקע\"ז ע' רעא ובהנסמן בהנ\"ל. שעה\"י קלג, ב."],["12004","174","<b>דישראל. . שי\"ר א\"ל</b>: ת\"ז בהקדמה (ג, סע\"א). ת\"י (כה, א). ע\"ח (שער פרצופי זו\"ן) של\"א, פ\"ה."],["12005","175","<b>הגבורות</b>: ז: ה\"ג."],["12006","176","<b>ה\"ג</b>: יד: הגבו'."],["12007","177","<b>כי גבר עלינו חסדו</b>: תהלים קיז, ב."],["12008","178","<b>כי שרית עם אלקי'</b>: וישלח לב, כט."],["12009","179","<b>לגבורו' דשם אלקי'</b>: נסמן לעיל פ' וארא סו, ב."],["12010","180","<b>עשו. . ז\"א דקליפה</b>: ראה ע\"ח (שער הקליפות) שמ\"ח, פ\"ג."],["12011","181","<b>ויאבק איש עמו</b>: וישלח לב, כה. ראה מאמרי אדה\"ז תקס\"ו ע' פה. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א וישלח כו, ב</a> ואילך."],["12012","182","<b>גבורות גשמים</b>: תענית ב, א. ראה גם סידור שחרית סא, ד. מאמרי אדה\"א דברים ח\"ד ע' א'תכח ואילך."],["12013","183","<b>גשם נדבות תניף אלקי'</b>: תהלים סח, י. ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ס\"ע תדשמ ואילך. ביאורי הזהר בחוקותי פד, ד. פיה\"מ י, סע\"ג ואילך. מאמרי אדה\"א ויקרא ח\"א ע' שצא."],["12014","184","<b>החסדים</b>: ז: ה\"ח."],["12015","185","<b>שבה</b>: זיד: ליתא."],["12016","186","<b>כא'</b>: ז: בכחם."],["12017","187","<b>טרף אש ומים ובללן יחד</b>: נסמן לעיל פ' שמות מה, ג."],["12018","188","<b>באברהם איש החסד</b>: נסמן לעיל נו, ג."],["12019","189","<b>והוא יושב פתח האהל</b>: וירא יח, א."],["12020","190","<b>פתח האהל. . דמל'</b>: ראה לעיל פ' בא צא, א. וש\"נ."],["12021","191","<b>האהל. . בינה</b>: ראה זהר תרומה קעה, ב (ע\"פ אוה\"ת בלק ע' א'לה). וישלח קסז, ב ובניצוצי אורות שם. אוה\"ת (יהל אור) תהלים ע' מג. מאו\"א מערכת אהל סמ\"ד."]]],[2300540556,"שיש בכח ה\"ח דאבא להגביר החסד על הדין או להפכו ג\"כ אינו אלא מצד בחי' גבורות שבחסדי' דאבא, והוא ענין היו\"ד דישראל שהוא ענין בחכ' אתברירו<sup data-n=\"12022\">192</sup> לאכללא שמאלא בימינא<sup data-n=\"12023\">193</sup> בחי' הבירורים לאהפכא חשוכא לנהורא כו', והוא מה שיש בכח<sup data-n=\"12024\">194</sup> חכ' שבתורה [דכתיב בה מימינו אש דת למו<sup data-n=\"12025\">195</sup> כו' אש שחורה ע\"ג אש לבנה<sup data-n=\"12026\">196</sup> אבל החסדים גוברין לאכללא שמאלא] בימינה כו' ונק' תורה של חסד<sup data-n=\"12027\">197</sup> כמ\"ש במ\"א בענין ותורת חסד על לשונה<sup data-n=\"12028\">198</sup> כו' וד\"ל (ומעתה לא יקשה פי' הפסוק כי שרית עם אלקים כו', דלכאו' טעם זה לקריאת שם ישראל הוא להיפך ממש כי ה[ל]א פי' שר שהוא לשון שררה הוא בחי' גבורות כנ\"ל, ומ\"ש הטעם כי שרית כוונתו התגברות החסדי' על הגבורות. אך לפי הנ\"ל יתורץ משום דהא בהא תליא שמצד היפך הגבורות להיות חסדים ע\"י הבירורים שביו\"ד דחכ' נעשה שר אל להיות משתרר באל דחסד על גבו' דאלקי' וזה כי שרית כו' וד\"ל). וזהו פי' בישראל<sup data-n=\"12029\">199</sup> דלעילא שהוא בחי' התיקון דהיינו בחי' התכללות חו\"ג שהוא חיבור האורות בכלים כנ\"ל (כי בחי' חיבור אורות בכלים הוא בא ג\"כ מבחי' חיבור והתכללות חו\"ג כי הכלי מגביל את האור שהוא בחי' צמצום ה\"ג והאור שרשו מבחי' חסד היורד מגבוה לנמוך כו' והתחברותם יחד בא ע\"י התכללו' חו\"ג בהתגברות החסדי' על הגבורו').\n<b>ומ\"ש</b> צדקת פרזונו בישראל בישראל<sup data-n=\"12030\">200</sup> דלעילא הנ\"ל, הנה פי' פרזונו לשון ערי הפרזי<sup data-n=\"12031\">201</sup> וכן פרזות תשב ירושלים<sup data-n=\"12032\">202</sup> כו', שהוא עיר הבלתי מוק[פת חומה] שהיא פתוחה ומפולשת מכל צד לפי שאין דבר שיגביל אותה וא\"כ הרי יכולה העיר להתיישב בבתים לאורך <span data-k=\"pg\">שנז</span> ּ ורוחב ימין ושמאל בלי שיעור כלל, אבל עיר המוקפת חומה מכל צד הרי יש בה גבול מד' צדדי' והחומה מקפת אותה שיגביל אותה מכל צד כמ\"ש על ירושלים פרזות תשב כו', דפי' הפשוט הוא מפני שישיבה של ירושלים יהי' בבתים בלתי מוגבלים כלל מרוב אדם כו' ע\"כ לא תהא מוקפת חומה להגביל יושבי' אלא פרזות תשב. והדוגמא בפי' פרזות למטה שהוא דבר בלתי מוגבל בקצוות, וכך יובן למשכיל למעלה<sup data-n=\"12033\">203</sup> שהוא אור הבלתי מוגבל בכלי, כי הכלי הוא המגביל את האור כידוע. אבל האור שאינו מתיישב בכלי ואין לו דבר המגביל אותו<sup data-n=\"12034\">204</sup> נק' פרזות שמתפשט בלי שיעור לאורך ורוחב ימין ושמאל ע\"ד מ\"ש ופרצת ימה וקדמה<sup data-n=\"12035\">206</sup> כו', ובלשון הגמ'",[["12022","192","<b>בחכ' אתברירו</b>: נסמן לעיל פ' שמות י, ג."],["12023","193","<b>לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח."],["12024","194","<b>מה שיש בכח</b>: זיד: שרש בחי'."],["12025","195","<b>מימינו אש דת למו</b>: ברכה לג, ב."],["12026","196","<b>אש שחורה ע\"ג אש לבנה</b>: נסמן לעיל רלח, ב."],["12027","197","<b>תורה של חסד</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' קכט. פרשיות התורה ח\"א ע' קיז. מאמרי אדה\"א דברים ח\"ד ע' א'תטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670444\" data-slug=\"torat-chaim\" data-id=\"2300670444\">תו\"ח בראשית טו, א</a> והערה 5. לקמן פ' תרומה שיז, א."],["12028","198","<b>ותורת חסד על לשונה</b>: משלי לא, כו."],["12029","199","<b>בישראל</b>: ז: הפסוק בישראל, בישראל."],["12030","200","<b>בישראל</b>: זיד: ליתא. וראה הערה שלפנ\"ז."],["12031","201","<b>ערי הפרזי</b>: דברים ג, ה [ושם: מערי]. לקמן רמה, ד. זיד: ערי הפרזות — אסתר ט, יט [ושם: בערי]."],["12032","202","<b>פרזות תשב ירושלים</b>: זכרי' ב, ח."],["12033","203","<b>למעלה. . האור</b>: כ\"ז נעתק בשינויים קלים באוה\"ת בשלח ע' תרפה. נ\"ך ע' יג."],["12034","204","<b>אותו</b>: באוה\"ת שם נמצאת הגהת הצ\"צ: (הג\"ה וכמו האור המקיף סוכ\"ע ולע\"ל שיומשך סוכ\"ע בגילוי זהו פרזות תשב עכ\"ה)."],["12035","206","<b>ופרצת ימה וקדמה</b>: ויצא כח, יד."]]],[2300540573,"נחלה בלי מצרים<sup data-n=\"12036\">207</sup> כו' כמ\"ש במ\"א<sup data-n=\"12037\">205</sup>. והיינו כמו בחי' אורות דתהו שהם בחי' אורות הבלתי מוגבלים בכלי', וזהו עיקר ההפרש בין בחי' התהו לבחי' התיקון שבחי' אורות דתהו הם למעלה מהתלבשות בכלים ובחי' התיקון האורות מתלבשים בכלים דוקא. והיינו מטעם שהאורות דתהו<sup data-n=\"12038\">208</sup> מיוחדים יותר בעצמות המאציל והם אורות תקיפים וחזקים ביותר<sup data-n=\"12039\">209</sup> ע\"כ לא יכלו הכלים לסבול את האור ולהגבילו בתוכו, ע\"ד דוגמא הנ\"ל שמרוב אדם לא יכילם בתי העיר אותם בהגבלת חומה כנ\"ל (וכמ\"ש בס\"י שהבתים נק' אותיות וכלים<sup data-n=\"12040\">210</sup> וכמ\"ש ה' אבנים<sup data-n=\"12041\">211</sup> בונות ק\"ך בתים כו'). וביאור הדברים ידוע עד\"מ מהארת אור שכל עמוק שבלתי מוגבל ומתיישב בכלי המוח אותיות המח', ועד\"ז<sup data-n=\"12042\">212</sup> רמזו באמרם לעתיד פרזות תשב ירושלים שלמעלה שהוא בחי' בנין המל' באו\"כ שנק' בתים ואותיות שמהם האור דמל' בלתי מוגבל בכלי כלל (כי הגבלת החומה הגם שנק' אור מקיף כמ\"ש ואני אהי' לה חומת אש<sup data-n=\"12043\">213</sup> כו' מ\"מ הוא המגביל לאור, כידוע שחומת אותיות חותם אותיות תחום<sup data-n=\"12044\">214</sup> כו', לפי שהמקיף מגביל לפנימי כמו הכלי שמגביל לאור כי שרש הכלי בבחי' מקיפי'<sup data-n=\"12045\">215</sup> כו' כידוע במ\"א וד\"ל). וזהו צדקת פרזונו בישראל פי' בחי' פרזון שהוא [בחי'] אור בלתי מוגבל בכלי יומשך ויתיישב בכלי<sup data-n=\"12046\">216</sup> שהוא בחי' התיקון שהוא חיבור האור בכלי דוקא, והיינו שיאיר בחי' אורות דתהו בתיקון שנק' ישראל כנ\"ל, כי מתחלה קודם שבאה דבורה חדלו פרזון בישראל עד שקמתי דבורה כו' דהיינו שלא האיר אור בלתי מוגבל רק בחי' אור המוגבל בלבד, אבל ע\"י דבורה נמשך צדקת פרזונו דתהו בישראל בבחי' כלים וע\"ד שיהי' לע\"ל דכתיב פרזות תשב ירושלים כו' וד\"ל.\n<b>ומ\"ש</b> צדקת פרזונו כו' ע\"י הצדקה דוקא, הנה כתי' צדקה תרומם גוי<sup data-n=\"12047\">217</sup> ופי' גוי הוא בחי' נה\"ב<sup data-n=\"12048\">218</sup> שבאדם ששרשה בבחי' נוגה דעשי' שנפלו בשבירה כו' כידוע בענין ז' מלכין קדמאין שמתו<sup data-n=\"12049\">219</sup> ונפלו בבחי' ב\"ן דבי\"ע כו'. והנה כשהאדם עוסק במו\"מ בכל יגיעת נפשו הבהמית הנק' יגיע כפו ומרויח ונותן מזה צדקה הנה בזה הוא מעלה נפשו הבהמית לשרשה בבחי' התהו שהי' קודם השבירה (ולזה רמזו רז\"ל יגיע כפיך<sup data-n=\"12050\">220</sup> כי תאכל אשריך בעוה\"ז בבחי' התיקון וטוב לך לעוה\"ב דוקא מפני טעם הבירורי' דרפ\"ח כו'). וז\"ש צדקה תרומם גוי שהוא נה\"ב",[["12036","207","<b>נחלה בלי מצרים</b>: נסמן לעיל רלג, ד."],["12037","205","<b>נק' פרזות. . במ\"א</b>: באוה\"ת שם: וזהו\"ע פרזות שאין לו חומה המגביל אותו."],["12038","208","<b>דתהו. . אורות תקיפים</b>: נסמן לעיל פ' שמות לט, ד."],["12039","209","<b>מיוחדים. . ביותר</b>: באוה\"ת שם: הן גבוהים ועליונים יותר."],["12040","210","<b>שהבתים. . וכלים</b>: יד: שהאותיות והתיבות נק' אבנים ובתים."],["12041","211","<b>ה' אבנים</b>: נסמן לעיל פ' וארא ס, ג."],["12042","212","<b>ועד\"ז</b>: זיד: וע\"ז."],["12043","213","<b>ואני אהי' לה חומת אש</b>: זכרי' ב, ט."],["12044","214","<b>שחומת אותיות חותם. . תחום</b>: נסמן לעיל רלג, א."],["12045","215","<b>שרש הכלי בבחי' מקיפי'</b>: ראה גם לעיל פ' שמות מו, א. וש\"נ."],["12046","216","<b>בכלי</b>: זיד: בישראל."],["12047","217","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["12048","218","<b>גוי. . נה\"ב</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תל."],["12049","219","<b>ז' מלכין קדמאין שמתו</b>: ראה זהר (אד\"ר) נשא קכח, א. קלה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680272\" data-slug=\"torat-chaim\" data-id=\"2300680272\">תו\"ח תולדות קנג, ב</a> הערה 39."],["12050","220","<b>יגיע כפיך</b>: תהלים קכח, ב. אבות פ\"ד, מ\"א."]]],[2300540589,"למעלה מעלה גם מבחי' התיקון <span data-k=\"pg\">716</span> ּ כמ\"ש לפני מלוך מלך לבנ\"י. וזהו הטעם שאמרו דר\"א יהיב פרוטה<sup data-n=\"12051\">221</sup> לעני והדר מצלי שנא' אני בצדק אחזה פניך<sup data-n=\"12052\">222</sup>, פי' בצדק לשרשו עולה בבחי' אורות דתהו שלמעלה מבחי' התיקון שהוא הנק' פניך בחי' יחוד פב\"פ דזו\"נ ואו\"א כו', וע\"כ א' דר\"א יהיב פרוטה לעני קודם התפלה כדי שעי\"ז יוכל להיות היחוד העליון דאו\"א וזו\"נ ע\"י התפלה (וכן מ\"ש והלך לפניך צדקיך<sup data-n=\"12053\">223</sup> כי הנשמה בעצמה היא מבחי' התיקון וע\"כ הצדקה שמיגיע כפו תלך לפניך כו', וכן ע\"י כל המצות שנק' צדקה כמ\"ש וצדקה תהי' לנו<sup data-n=\"12054\">224</sup> כו' ג\"כ מטעם בחי' הבירורים דתהו כו'). וז\"ש צדקת פרזונו בישראל ע\"י הצדקה ומעשה המצות נמשך פרזון דתהו בישראל (וגם מטעם כמו שהצדקה הוא להחיות רוח שפלים<sup data-n=\"12055\">225</sup> כך צדקת ה' להיות פרזון דתהו יורד ויתנו שם צדקת ה'<sup data-n=\"12056\">226</sup> כו'). ומזה הטעם יובן מארז\"ל דיפה<sup data-n=\"12057\">227</sup> שעה א'<sup data-n=\"12058\">228</sup> בתשובה ומע\"ט בעוה\"ז כו' דוקא תשו' ומע\"ט ודוקא בעוה\"ז, כי בעוה\"ז<sup data-n=\"12059\">229</sup> נשמות נהנין<sup data-n=\"12060\">230</sup> מזיו<sup data-n=\"12061\">231</sup> בבחי' אור המוגבל בכלי לבד, אבל ע\"י המצות שנק' צדקה נמשך אור הבלתי מוגבל. וגם ע\"י תשו' מעומקא דלבא כמ\"ש ממעמקי' קראתיך<sup data-n=\"12062\">232</sup> כו' נמשך אור הבלתי מוגבל כנ\"ל<sup data-n=\"12063\">233</sup>, כי בחי' אה\"ר שבעומק הלב הוא למעלה מן הדעת והוא בחי' הביטול שלמעלה מן החכ' שנק' למעלה בחי' בהמה רבה דתהו שלמעלה מבחי' אדם דתיקון, שהוא בחי' הדעת הנק' ישראל שכולל חו\"ג<sup data-n=\"12064\">234</sup> כו' דהיינו כמו בחי' הביטול שע\"י התבוננו' כו', ובעוה\"ז הוא זמן הבירור דתהו ע\"י תשו' ומע\"ט דאה\"ר שלמעלה מן הדעת עולה לבחי' התהו ומוריד אור דתהו בתיקון וכן ע\"י מע\"ט כנ\"ל. וע\"כ יפה שעה א' בתשו' ומע\"ט דוקא ובעוה\"ז דוקא מכל חיי העוה\"ב שהוא רק בחי' אור מוגבל בכלי. וזהו ג\"כ מ\"ש מקול מחצצים בין משאבים שם דוקא יתנו צדקות ה' צדקת פרזונו בישראל פי' דוקא מבחי' הבירורי' דתהו שנק' מחצצים בין משאבים כו' וד\"ל.",[["12051","221","<b>דר\"א יהיב פרוטה</b>: ב\"ב י, א. ראה גם אגה\"ק סי\"ב. סידור שער התפלה יט, ג. כב, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תתמז ואילך. ע' תתסד. וראה ג\"כ אגה\"ק ס\"ח. סידור שחרית נו, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291411\" data-slug=\"likkutei-sichot\" data-id=\"1300291411\">לקו\"ש עקב כרך כט ע' 396</a>."],["12052","222","<b>אני בצדק אחזה פניך</b>: תהלים יז, טו."],["12053","223","<b>והלך לפניך צדקיך</b>: ישעי' נח, ח."],["12054","224","<b>כל המצות. . וצדקה תהי' לנו</b>: נסמן לעיל פ' שמות יד, א."],["12055","225","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["12056","226","<b>ויתנו. . ה'</b>: יד: ומתיישב למטה בישראל."],["12057","227","<b>דיפה</b>: נסמן לעיל פ' שמות ט, א."],["12058","228","<b>דיפה שעה א'</b>: אבות פ\"ד, מי\"ז."],["12059","229","<b>בעוה\"ז</b>: זיד: בעוה\"ב."],["12060","230","<b>בעוה\"ב נשמות נהנין מזיו</b>: ראה ברכות יז, א."],["12061","231","<b>מזיו</b>: דיז: ליתא."],["12062","232","<b>ממעמקי' קראתיך</b>: תהלים קל, א."],["12063","233","<b>כנ\"ל</b>: יד: הנ\"ל."],["12064","234","<b>הדעת. . שכולל חו\"ג</b>: נסמן לעיל פ' וארא נז, ד."]]],[2300540080,"<b>ביאור א' ע\"פ צדקת פרזונו הנ\"ל</b>\n<b>ולהבין</b> בתוס' ביאור<sup data-n=\"12065\">1</sup> ענין צדקת פרזונו בישראל<sup data-n=\"12066\">2</sup>. וגם להבין מ\"ש דבורה על עצמה עד שקמתי [דבורה שקמתי] אם",[["12065","1","<b>ולהבין בתוס' ביאור</b>: ראה ע\"ד ביאור זה לקמן ברשימות הכת\"י [ברשימה לתחילת המאמר כאן שעליו קאי ביאור זה. ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["12066","2","<b>צדקת פרזונו בישראל</b>: ס' שופטים ה, יא."]]],[2300540118,"בישראל<sup data-n=\"12067\">3</sup> דמשמע דוקא ע\"י דבורה נמשך צדקת פרזונו כו', ומתחלה חדלו פרזון בישראל<sup data-n=\"12068\">4</sup> עד שקמתי דבורה. וגם ב' פעמים שקמתי לכאורה מיותר הוא, הל\"ל עד שקמתי אם בישראל<sup data-n=\"12069\">5</sup> למה כפל[ה] דבריה שקמתי דבורה שקמתי אם. אך הנה יש להקדים מ\"ש בר\"מ ע\"פ עולת תמיד<sup data-n=\"12070\">6</sup> כו' עולת שבת<sup data-n=\"12071\">7</sup> כו' כד איהי סלקא כולהו סלקי[ן] בגינה כו'. דהנה מבואר בע\"ח<sup data-n=\"12072\">8</sup> בבחי' אורות דתהו שמפני תוקף וגודל אור שלהם לא יכלו הכלים לסבול את האור ע\"כ נשברו הכלים ונפלו למטה והאורות נסתלקו למעלה מעלה דהיינו שנכללו בעצמו' המאציל שהוא למעלה הרבה ממדריגתן, וא\"כ בחי' האורות נתעלו בעילוי גדול למעלה הרבה מבחי' מדריגתן הראשונה ובחי' הכלים דתהו ירדו למטה מטה מאד כו'. וביאור דבר זה ידוע שהוא עד\"מ העומק של המושכל כש[הוא] עמוק יותר מכלי השגת כלי המקבל<sup data-n=\"12073\">9</sup> עד שלא יכילנו אזי יתבלבלו אותיות כלי השגתם ונפלו <span data-k=\"pg\">שנח</span> ּ ממדריגתם ואור השכל ההוא העומק יסתלק למעלה לשרשו בכח המשכיל, ונמצא עולה השכל [ב]מעלה יתירה וכלי השכל ירד למטה כו' וכמ\"ש במ\"א וד\"ל. והנה ידוע דבחי' המל' דאצי' יורדת למטה בבי\"ע לברר בירורי נוגה שהן רפ\"ח ניצוצי'<sup data-n=\"12074\">11</sup> שנפלו בשבה\"כ דתהו, וז\"ש ותקם בעוד לילה<sup data-n=\"12075\">12</sup> ותתן טרף כו' שהוא [גי'] רפ\"ח עם הכולל<sup data-n=\"12076\">13</sup> ובכל שחר המל' עולה<sup data-n=\"12077\">10</sup> מירידתה לברר בירורי נוגה ונק' עולת תמיד<sup data-n=\"12078\">14</sup> כו', ובכללות יותר הוא עליות המל' ב[כל] שבת אחר תשלום כל הבירורי' שביררה [ב]כל ו' ימי החול [ו]נק' עולת שבת<sup data-n=\"12079\">15</sup> כו' כידוע, וכאשר המל' עולה למעלה באצי' הנה היא עולה עד רום המעלות דהיינו עד<sup data-n=\"12080\">16</sup> עצמו' המאציל כי סוף מעשה [עלה] במח\"ת<sup data-n=\"12081\">17</sup> לפי שזה הי' כוונת המאציל במח' תחלה כידוע ומבואר במ\"א וד\"ל.\n<b>והנה</b> להיות שבעליות המל' מעלה היא עמה גם הבירורי' דרפ\"ח כו' עד שרשם בבחי' הכלים דתהו, ע\"כ מפני זה מעוררים וממשיכים בחי' אורות דתהו שיצאו מבחי' ההעלם ש[כבר] נתעלמו ונכללו בעצמו' המאציל שירדו למטה ויאירו בכלים שלהם כשבאים למעלה עם בחי' המל' לאחר הבירור. והנה לכאורה אין זה מובן דהלא ק\"ו הוא אם לא יכלו הכלים לסבול את האורות בהיותן רק במדריגותן העצמי' איך יוכלו",[["12067","3","<b>עד שקמתי. . בישראל</b>: ס' שופטים שם, ז."],["12068","4","<b>חדלו פרזון בישראל</b>: התחלת הכתוב עד שקמתי."],["12069","5","<b>בישראל</b>: זיד: כו'."],["12070","6","<b>בר\"מ ע\"פ עולת תמיד</b>: פינחס כח, ו. ראה רע\"מ שם רנו, ב."],["12071","7","<b>עולת שבת</b>: פינחס כח, י."],["12072","8","<b>מבואר בע\"ח</b>: ראה שם שער הכללים פ\"א. (שער שביה\"כ) ש\"ט, פ\"ו. מאמרי אדה\"א דברים ח\"ד ע' א'תעו. וש\"נ. לקמן פ' ויקהל שצ, א."],["12073","9","<b>כלי המקבל</b>: זיד: המשיגו."],["12074","11","<b>רפ\"ח ניצוצי'</b>: נסמן לעיל פ' שמות לו, ג."],["12075","12","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["12076","13","<b>טרף. . רפ\"ח עם הכולל</b>: נסמן לעיל לט, א."],["12077","10","<b>המל' דאצי' יורדת. . שחר המל' עולה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381259\" data-slug=\"likkutei-torah\" data-id=\"4001381259\">לקו\"ת שה\"ש לב, סע\"ג</a>. וש\"נ."],["12078","14","<b>המל'. . עולת תמיד</b>: ראה רע\"מ שבהערה 6. מאמרי אדה\"א דברים ח\"ד ע' א'תמז. קונטרסים ע' רפה ובהנסמן בהנ\"ל."],["12079","15","<b>המל'. . עולת שבת</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' נ."],["12080","16","<b>עד</b>: זיד: לבחי'."],["12081","17","<b>המל'. . סוף מעשה [עלה] במח\"ת</b>: ע\"פ פיוט לכה דודי. ראה גם מאמרי אדה\"ז תקס\"ט ע' רלז."]]],[2300540156,"הכלים לסבול אותם אחר שנתעלמו<sup data-n=\"12082\">18</sup> בעילוי גדול בעצמו' המאציל כנ\"ל. אך הענין הוא כידוע בע\"ח [ב]בחי' הכלים דתהו שקודם השבירה [והתיקון] שהי' במיעוט מאד ולפי שהאור הי' בריבוי גדול מהכיל בכלי מסיבה זו נשברו הכלים כי לא הי' ביכולתם לסבול<sup data-n=\"12083\">19</sup> את האור מצד קוטנם ומיעוטם, אבל בבחי' התיקון הרי האור בא במיעוט והכלי בריבוי כידוע שזהו עיקר סיבת התיקון וקיום האור בכלי<sup data-n=\"12084\">20</sup>. אמנם בחי' האור דתיקון הוא המברר לבחי' הכלים דתהו שירדו למטה בבי\"ע כידוע דבחכ' אתברירו<sup data-n=\"12085\">21</sup> והיינו בחי' שם מ\"ה דאצי' שמברר לבחי' ב\"ן<sup data-n=\"12086\">22</sup> דבריאה כו', אך לאחר הבירור עולה שם ב\"ן המתברר למעלה מבחי' שם מ\"ה<sup data-n=\"12087\">23</sup> המברר כמ\"ש א\"ח עט\"ב<sup data-n=\"12088\">24</sup>, דהיינו בחי' ב\"ן לאחר הבירור שנק' א\"ח דוקא אז נעשה בחי' עטרת וכתר לז\"א בעלה שהוא שם מ\"ה דתיקון כידוע, והטעם הוא לפי שבחי' הכלים דתהו המתבררים ע\"י שם מ\"ה דתיקון ששרשם בבחי' ס\"ג דבינה דתהו שלמעלה מבחי' מ\"ה<sup data-n=\"12089\">25</sup> כו' וכמ\"ש בע\"ח. אמנם זאת יתרון המעלה של בחי' הכלים ע\"י הבירור דשם מ\"ה דוקא מה שיש ביכולתם להכיל גם בחי' אורות דתהו שכבר עלו בעצמו' המאציל ונתרחבו יותר ממדריגתם כנ\"ל שלא הי' ביכולתם להכיל קודם שירדו למטה מצד קוטנם בערך לגבי האורות כנ\"ל. והטעם הוא לפי שע\"י בחי' התיקון נתרחבו הכלים בבחי' ריבוי גדול שזהו עיקר ענין התיקון לעשות התרחבות כלים כידוע, וזהו ענין ארץ טובה ורחבה<sup data-n=\"12090\">26</sup> כו' (שהוא בחי' המל' לאחר הבירור דהיינו בחי' א\"י שנק' ארץ הצבי<sup data-n=\"12091\">27</sup> מה צבי<sup data-n=\"12092\">28</sup> כו' וכמ\"ש רבב\"ח לדידי חזי לי<sup data-n=\"12093\">29</sup> כו'). וע\"כ בעלות המל' עם בירורי כלים דתהו למעלה מעלה [כנ\"ל], שאז מעוררים וממשיכי' בחי' גילוי אורות דתהו שיצאו מן ההעלם שיאירו ויתיישבו בהתרחבות הכלים דתהו לאחר הבירור דתיקון שיוכלו לסבול [את] האור מפני ריבוי התרחבות שלהם, וא\"כ הרי <span data-k=\"pg\">718</span> ּ נתחבר ריבוי האור דתהו עם ריבוי [ה]כלים שנעשה ע\"י התיקון, וזהו רק מחמת על[יי]ת המל' עם בירורי דרפ\"ח כנ\"ל וד\"ל.\n<b>וזהו</b> ענין המאמר כד איהי סלקא כולהו סליק[ין] בגינה כו', פי' איהי בחי' המל' בעלותה מבחי' הבירורי' דבי\"ע עד תחלת המח' שבעצמו' המאציל, כולהו סליק[ין] בגינה דהיינו כל בחי' הבירורי' דרפ\"ח כו' כולהו<sup data-n=\"12094\">30</sup> סליק[ין] ועולין לשרשם הקדום ודוקא בגינה משום דסוף מעשה עלה במח\"ת. וזהו ענין<sup data-n=\"12095\">31</sup> עולת תמיד כו' שתמיד היא עולה כדי להיות ריח ניחוח להוי'<sup data-n=\"12096\">32</sup> דתיקון, כי אחר בחי' העלאה שלה היא מעוררת בחי' המשכת אורות דתהו שכבר נתעלמו בעצמו' המאציל שירדו למטה להתלבש בכלי' שלהם שעלו אחר הבירור דשם מ\"ה דתיקון ש[מ]ברר לשם ב\"ן דתהו כנ\"ל, ולהיות כן בחי' אורות דתהו גבוהים הרבה מבחי' אור הוי' דתיקון ובפרט לאחר שנתעלו בבחי' העצמו' כנ\"ל ע\"כ נעשה מהם בחי' ריח ניחוח להוי'",[["12082","18","<b>שנתעלמו</b>: זיד: שנתעלו."],["12083","19","<b>לסבול</b>: שם: להכיל."],["12084","20","<b>התיקון. . בכלי</b>: שם: קיום האור בכלי בבחי' התיקון."],["12085","21","<b>דבחכ' אתברירו</b>: נסמן לעיל פ' שמות י, ג."],["12086","22","<b>מ\"ה. . שמברר לבחי' ב\"ן</b>: נסמן לעיל ד, ב."],["12087","23","<b>ב\"ן. . למעלה. . שם מ\"ה</b>: נסמן לעיל פ' וארא ע, ג."],["12088","24","<b>א\"ח עט\"ב</b>: משלי יב, ד."],["12089","25","<b>ס\"ג. . דתהו שלמעלה מבחי' מ\"ה</b>: נסמן לעיל פ' שמות מ, ד."],["12090","26","<b>ארץ טובה ורחבה</b>: שמות ג, ח. ראה גם לעיל פ' וארא עא, ד."],["12091","27","<b>א\"י שנק' ארץ הצבי</b>: ראה גם לעיל ע, א. וש\"נ."],["12092","28","<b>מה צבי</b>: גיטין נז, א. ראה מאמרי אדה\"א שמות ח\"א ע' סו."],["12093","29","<b>רבב\"ח לדידי חזי לי</b>: מגילה ו, א. כתובות קיא, סע\"ב."],["12094","30","<b>כולהו</b>: זיד: ליתא."],["12095","31","<b>ענין</b>: שם: שנק'."],["12096","32","<b>ריח ניחוח להוי'</b>: ויקרא א, ט. ראה גם מאמרי אדה\"ז תקס\"ב ע' כט. ביאוה\"ז ויקרא ס, ג."]]],[2300540193,"דתיקון כנ\"ל וכמ\"ש במ\"א באריכות<sup data-n=\"12097\">33</sup>. ונמצא מסיבת עלי' המל' יש כאן ב' דברים, הא' בחי' גילוי ההעלם אורות דתהו למטה והב' בחי' התרחבו' הכלים דתהו שנעשה אחר הבירור דוקא לקבל בחי' ריבוי האורות דתהו (וזהו ג\"כ מ\"ש ביעקב שהוא בחי' התיקון<sup data-n=\"12098\">34</sup> וישתחו ז' פעמים<sup data-n=\"12099\">35</sup> עד גשתו כו' וירץ עשו לקראתו ויחבקהו<sup data-n=\"12100\">36</sup> כו' כי שרש ענין עשו מבחי' התהו<sup data-n=\"12101\">37</sup> ע\"כ רץ לקראתו מלמעלה למטה והוא ע\"י העלאת מ\"ן דמנחת יעקב<sup data-n=\"12102\">38</sup> לגבי בחי' התהו כמ\"ש במ\"א [וד\"ל]).\n<b>וזהו</b> חדלו פרזון בישראל [חדלו] עד שקמתי דבורה כו', פי' קודם [מ]פלת סיסרא חדלו פרזון בישראל כו', כי ישראל הוא בחי' ז\"א<sup data-n=\"12103\">39</sup> דאצי' ששם האור במיעוט כו' ובחי' אורות דתהו שנק' פרזון<sup data-n=\"12104\">40</sup> כו' מלשון ערי הפרזי<sup data-n=\"12105\">42</sup> כו' כנ\"ל<sup data-n=\"12106\">41</sup> לא יכלו לירד ולהתגלות למטה כי לא יכולים<sup data-n=\"12107\">43</sup> הכלים דז\"א שנק' ישראל, וע\"כ חדלו פרזון בישראל פי' חדלו מלשון מניעה שנמנעו אור [ו]שפע דתהו מלבוא בישראל דתיקון מב' טעמים, הא' מפני שכבר נתעלו ונתעלמו בעצמו' המאציל כנ\"ל, והב' מפני קוטן וצמצום הכלי' שלא יוכלו להתלבש בהם כנ\"ל, וזהו שהזכיר ב' פעמים חדלו מתחלה חדלו מצד עליותם בעצמו', וחדלו הב' מסיבת מיעוט הכלים כו' וד\"ל. עד שקמתי דבורה [כו'] פי' דבורה [היינו] דבור ה'['א], והוא בחי' מל'<sup data-n=\"12108\">44</sup> דאצי' שנק' דבר ה'<sup data-n=\"12109\">45</sup> כמ\"ש בדבר ה' שמים<sup data-n=\"12110\">46</sup> נעשו והוא חלק<sup data-n=\"12111\">47</sup> עולם הדבור, והה'['א] היינו בחי' ה' מוצאות הפה שאין<sup data-n=\"12112\">48</sup> ה\"ג מנצפ\"ך<sup data-n=\"12113\">49</sup> שמחלקי' ומפרידי' את הבל הדבור שהוא מקור התחלקו' האותיות הדבור, וזהו הטעם שנק' דבורה. ופי' שקמתי דבורה הוא בחי' עליי' המל' שנק' דבורה, והוא ענין [בחי'] עליית הדבור לגבי תחילת המח' שבעצמו' המאציל כי סוף מעשה עלה במח\"ת כנ\"ל בפי' עולת תמיד ועולת שבת כו', וזהו שקמתי דבורה. ונכלל בקומה זה תחלת הקמתה מירידתה [ל]מטה מטה בסתר המדריגה בבי\"ע לברר רפ\"ח ניצוצי נוגה שנפל לשם כנ\"ל וכמ\"ש ותקם בעוד לילה כו', ודוקא בכח הקמה הזאת להיות עולה עם בחי' הבירורי' דרפ\"ח כנ\"ל עולה",[["12097","33","<b>באריכות</b>: זיד: וד\"ל."],["12098","34","<b>יעקב. . התיקון</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"א."],["12099","35","<b>וישתחו ז' פעמים</b>: וישלח לג, ג [בדילוג]."],["12100","36","<b>וירץ עשו לקראתו ויחבקהו</b>: שם לג, ד."],["12101","37","<b>עשו מבחי' התהו</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370113\" data-slug=\"torah-or\" data-id=\"3901370113\">תו\"א ר\"פ וישלח (כד, א</a>). מאמרי אדה\"ז תקס\"ה ח\"א ע' סד ואילך."],["12102","38","<b>העלאת מ\"ן דמנחת יעקב</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ס\"ע עו ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">תו\"א וישלח כו, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680331\" data-slug=\"torat-chaim\" data-id=\"2300680331\">תו\"ח שם קפו, סע\"א</a> ואילך."],["12103","39","<b>ישראל. . ז\"א</b>: נסמן לעיל קצח, ד. וראה לעיל רמד, א."],["12104","40","<b>אורות דתהו שנק' פרזון</b>: ראה גם לעיל רמד, ג ואילך."],["12105","42","<b>ערי הפרזי</b>: נסמן לעיל רמד, ג."],["12106","41","<b>כו'. . כו' כנ\"ל</b>: זיד: כו' כנ\"ל. . כו'."],["12107","43","<b>יכולים</b>: ז: יכילם. יד: יוכלו."],["12108","44","<b>דבורה. . מל'</b>: לקו\"ת להאריז\"ל ס' שופטים ד, ד. מאו\"א מערכת דבורה אות ב."],["12109","45","<b>מל'. . דבר ה'</b>: ראה מאורי אור מערכת דבר ה' אות ג וביאיר נתיב שם."],["12110","46","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["12111","47","<b>חלק</b>: זיד: הנק'."],["12112","48","<b>שאין</b>: שם: שהן."],["12113","49","<b>ה\"ג מנצפ\"ך</b>: נסמן לעיל פ' שמות יט, ג."]]],[2300540227,"היא בתכלית העילוי עד תחלת המח', כי לזה הי' כל עיקר כוונת תחלת המח' לברר ולהפך חשוכא לנהורא (ויש <span data-k=\"pg\">שנט</span> ּ בפי' שקמתי דבורה להקים ולרומם גם לבחי' בינה דאצי' שנק' ג\"כ דבורה, כי ה\"ג מנצפ\"ך דמל' נמשכים מה\"ג מנצפ\"ך דאימא<sup data-n=\"12114\">50</sup> עילאה כמ\"ש כאמה כבתה<sup data-n=\"12115\">51</sup> וכמאמר דאימא אוזיפת מנהא לברתא<sup data-n=\"12116\">52</sup> כמ\"ש בזהר תרין נוקבין פריש שלמה<sup data-n=\"12117\">53</sup> מלכא בשיר השירים אתי מלבנון כלה<sup data-n=\"12118\">54</sup> כו', והן ב' ההי\"ן דשם הוי'<sup data-n=\"12119\">55</sup> שנק' אימא עילאה ואימא תתאה או אלקים עילאה ואלקים תתאה כידוע. והיינו מטעם כי א\"ח דמלכא נעשה ע[ט]\"ב בבחי' ס\"ג דבינה לאחר הבירור כנ\"ל וכמ\"ש בזהר ע\"פ ביום ההוא יצאו מ\"ח<sup data-n=\"12120\">56</sup> מירושלים חצים כו' דמסגי אית<sup data-n=\"12121\">57</sup> חלבא כמ\"ש במ\"א, וא\"כ ממילא בהקמת המל' נעשה בחי' הקמת המח' אימא עילאה<sup data-n=\"12122\">58</sup> והקמתה ועליתה בבחי' אהי' [דכת\"ר]<sup data-n=\"12123\">59</sup> כמ\"ש אהי' אשר אהי'<sup data-n=\"12124\">60</sup> וד\"ל).\n<b>שקמתי</b> אם בישראל פי' שקמתי הב' לכאורה קאי על הקמת עצמה וא\"כ קשה למה לה לכפול דברי', אך באמת דשקמתי [זה] הב' קאי על הקמת אם בישראל ומילתא באפי נפשה היא, וה\"ק שקמתי דבורה, בעל[י]ות המל' לתחלת המח' שבעצמו' כנ\"ל ואז נמשך מדריגת העלאה זו מצד הבירורי' דרפ\"ח להיות הקמה שני' והיא הקמת אם בישראל. וענין הקמת אם כמ\"ש כי אם לבינה תקרא<sup data-n=\"12125\">61</sup> וכידוע שבחי' בינה נק' אם הבנים<sup data-n=\"12126\">62</sup> והיינו עד\"מ השכל וההתבוננו' שממנה [נולדו] המדות אהוי\"ר כידוע, אך ענין הקמת אם הבנים היא בחי' בינה שבכתר. כי הנה אנו רואי' בחוש שא\"א שיבא בהתפעלו' אהוי\"ר כמו שהוא בשכל עצמו רק [ב]בחי' מקיף חופפת על ההתפעלו' וז\"ש על גוזליו ירחף<sup data-n=\"12127\">63</sup> דאימא פריסת גדפהא<sup data-n=\"12128\">64</sup>, וזהו ופרוס עלינו את סוכת שלומך<sup data-n=\"12129\">65</sup>, ועד\"מ<sup data-n=\"12130\">66</sup> [בחי'] מקיפים דסכך כו'. ומה שבא ממנה בגילוי בהתפעלו' נק' [ש]די אמי<sup data-n=\"12131\">67</sup> כמ\"ש במ\"א<sup data-n=\"12132\">68</sup> בענין אלד\"ד ומיד\"ד<sup data-n=\"12133\">69</sup> והיינו בינה ליבא<sup data-n=\"12134\">70</sup> שע[ש]ה דדים במקום בינה<sup data-n=\"12135\">71</sup> כו', אך בחי' מקיף זה כשבא לידי גילוי זה<sup data-n=\"12136\">72</sup> זהו מ\"ש שקמתי אם בישראל, דהיינו כאשר בחי' בינה אם הבנים עולה בבחי' בינה שבכתר אזי גם ההתפעלו' של המדות מקבלים כל מרחב ההשגה בלי העלם כלל כו'. ויובן דבר זה [למטה] בעבודת ה' בהתפעלו'",[["12114","50","<b>מה\"ג מנצפ\"ך דאימא</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' א'כג ואילך."],["12115","51","<b>כאמה כבתה</b>: [ז: בתה] יחזקאל טז, מד."],["12116","52","<b>דאימא אוזיפת מנהא לברתא</b>: נסמן לעיל פ' בא קא, א."],["12117","53","<b>תרין נוקבין פריש שלמה</b>: נסמן לעיל קצז, א."],["12118","54","<b>אתי מלבנון כלה</b>: שה\"ש ד, ח."],["12119","55","<b>ב' ההי\"ן דשם הוי'</b>: ראה ת\"ז בהקדמה (ו, ב)."],["12120","56","<b>ביום ההוא יצאו מ\"ח</b>: זכרי' יד, ח. זהר שלח קעא, א. ביאוה\"ז שלח צב, ב."],["12121","57","<b>דמסגי אית</b>: זיד: דמסגיאות. בזהר שם: ומסגיאו."],["12122","58","<b>המח' אימא עילאה</b>: ד: הבינה. ז: המשכה. יד: ליתא."],["12123","59","<b>אהי' </b>[דכת\"ר]: ראה לעיל קיב, א. וש\"נ."],["12124","60","<b>אהי' אשר אהי'</b>: שמות ג, יד."],["12125","61","<b>כי אם לבינה תקרא</b>: נסמן לעיל פ' וארא סט, ב."],["12126","62","<b>בינה נק' אם הבנים</b>: נסמן לעיל פ' שמות יז, א."],["12127","63","<b>על גוזליו ירחף</b>: האזינו לב, יא."],["12128","64","<b>דאימא פריסת גדפהא</b>: ראה זהר (רע\"מ) פינחס רנו, סע\"א."],["12129","65","<b>ופרוס עלינו את סוכת שלומך</b>: נוסח ברכת השכיבנו [בהוספת תיבת ”את\" יד: ליתא — ראה מאמרי אדה\"א דברים ח\"ד ע' א'תקיב]."],["12130","66","<b>ועד\"מ</b>: ז: ועד\"ז."],["12131","67","<b>[ש]די אמי</b>: שה\"ש ח, א. ז: שדי יניקת אמו."],["12132","68","<b>במ\"א</b>: זיד: בע\"ח."],["12133","69","<b>אלד\"ד ומיד\"ד</b>: ראה בהנסמן לעיל נא, ב."],["12134","70","<b>בינה ליבא</b>: ת\"ז בהקדמה (יז, א)."],["12135","71","<b>שע[ש]ה דדים במקום בינה</b>: ברכות י, א."],["12136","72","<b>זה</b>: ז: ליתא."]]],[2300540259,"שבהתבוננו' באלק[ו]' שיש ב' מיני התפעלו', הא' התפעלות אהבה הנולדה מן [ה]השגה שההשגה נשארה בהעלם בבחי' מקיף כנ\"ל. והב' התפעלו' מ[ה]השגה עצמה, דהיינו שאין ההתפעלו' דבר נבדל [כלל אלא ההשגה עצמה היא התפעלות, כמו שאנו רואים שמתפעל אדם מהשגת שכל נפלא כידוע ואז לא נשאר כלל] מן ההשגה<sup data-n=\"12137\">73</sup> בהעלם המקיף, אלא אדרבה כולה כמו שהיא בא[ה] לידי גילוי [דהיינו] בבחי' התפעלו'. וזהו משל ודמיון להבין למעלה שבבחי' בינה דאצי' יש ג\"כ ב' מדריגות, [ה]א' הנק' אם המולידות אם<sup data-n=\"12138\">74</sup> הבנים כו'. והב' בחי' בינה שבכתר, והוא אהי' דכתר שפי' אנא זמין לאתגלאה לאולדא<sup data-n=\"12139\">75</sup>, ועדיין לא בא לכלל תולדה עד בחי' בינה שנק' השגה ושם מתרחב[ים] המדות לקבל כל הארת [ה]בינה בלי העלם כלל. וזהו שקמתי אם בישראל שהוקם אם ומשפיע לז\"א דאצי' שנק' ישראל להיות הארת המקיפי' בלתי העלם כלל, וכנ\"ל בענין פרזות תשב ירושלים<sup data-n=\"12140\">76</sup> שתשב בגילוי כל המקיף כו' ולא יהי' עוד המקיף לבחי' גבול<sup data-n=\"12141\">77</sup> כחומה לעיר שנק' חותם כו' <span data-k=\"pg\">720</span> ּ וכמ\"ש ולא יכנף עוד מוריך<sup data-n=\"12142\">78</sup> כו'. ולא כמו עכשיו דמקיפי' דבינה בהעלם וכמ\"ש ואני אהי' לה חומת אש<sup data-n=\"12143\">79</sup> כו', אלא פרזות תשב כו', והיינו שקמתי אם להיות [ב]תוך ישראל דוקא שהוא בחי' המשכת גילוי המקיפי' דאימא כנ\"ל וד\"ל.",[["12137","73","[כלל. . כלל]<b> מן ההשגה</b>: ניתוסף ע\"פ יד [ושם: ליתא התיבות: מן ההשגה]. ז: כלל מן ההשגה."],["12138","74","<b>המולידות אם</b>: זיד: המולדת."],["12139","75","<b>אנא זמין לאתגלאה </b>[זיד: ליתא]<b> לאולדא</b>: ראה זהר ויקרא יא, א. אחרי סה, ב."],["12140","76","<b>ירושלים</b>: זיד: ליתא."],["12141","77","<b>גבול</b>: שם: מגביל."],["12142","78","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["12143","79","<b>ואני אהי' לה חומת אש</b>: זכרי' ב, ט [בדילוג]."]]],[2300540081,"<b>בעז\"ה ביאור שני לדרוש דצדקת פרזונו הנ\"ל</b>\n<b>ולהבין</b> בתוס' ביאור<sup data-n=\"12144\">1</sup> ענין צדקת פרזונו בישראל<sup data-n=\"12145\">2</sup> הנ\"ל ובאופן אחר, הנה תחלה י\"ל שרש ענין [ב]ישראל מהו, בהיות מבואר למעלה בתיבת ישראל<sup data-n=\"12146\">3</sup> שהוא יש\"ר א\"ל<sup data-n=\"12147\">4</sup> כו' ואל הוא בחי' החסד<sup data-n=\"12148\">5</sup> כמ\"ש חסד אל<sup data-n=\"12149\">6</sup> כל היום<sup data-n=\"12150\">7</sup>, אך הנה צ\"ל הטעם למה נק' בשם אל דוקא. והענין הוא דהאות הא' שבאל הוא כמ\"ש בזהר בכמה דוכתי דאל הוא נהירו דחכמתא<sup data-n=\"12151\">8</sup> ואות הל' דאל הוא בחי' ז\"א, ואות הא' דחכ' הוא המאיר בתוך אות הל' דז\"א ואז נק' ישראל כו'.",[["12144","1","<b>ולהבין בתוס' ביאור</b>: ראה הנרשם לקמן ברשימת הכת\"י [בהרשימה לתחילת המאמר שעליו קאי ביאור זה. ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["12145","2","<b>צדקת פרזונו בישראל</b>: ס' שופטים ה, יא."],["12146","3","<b>מבואר למעלה בתיבת ישראל</b>: ראה לעיל רמד, א ואילך."],["12147","4","<b>ישראל. . יש\"ר א\"ל</b>: ראה פרדס (שער ערה\"כ) שכ\"ג מערכת ישראל. פי' הר\"מ בוטרי\"ל לס\"י פ\"א, מ\"א (ירושלים תשכ\"ב יד, סע\"ד ואילך). רמ\"ז לזח\"ג ר\"פ שמיני. סידור שער התפילין יא, ג. שע\"ת קיד, ד. מאמרי אדה\"א שמות ח\"ב ע' תסב. דברים ח\"ב ע' תעח."],["12148","5","<b>ואל הוא בחי' החסד</b>: ראה בהנסמן לעיל רמד, א הערה 168."],["12149","6","<b>חסד אל כל היום</b>: תהלים נב, ג."],["12150","7","<b>כל היום</b>: זיד: כו'."],["12151","8","<b>דאל הוא נהירו דחכמתא</b>: נסמן לעיל פ' בא צח, ד."]]],[2300540119,"<b>וביאור</b> הדברים הנה הטעם שבחי' ז\"א נרמז באות הל' לפי שידוע בע\"ח שעיקר בנין ז\"א היא רק ג' מדריגות בלבד שהם בחי' נה\"י<sup data-n=\"12152\">9</sup> דז\"א<sup data-n=\"12153\">10</sup>, וכאו\"א כלול מי\"ס בהעלם דהיינו חב\"ד חג\"ת נה\"י והיינו אות הל', וכמ\"ש בזהר דבבחי' עיבור ז\"א במעי אימא הוא תלת דכליל גו תלת<sup data-n=\"12154\">11</sup> כו', וכמארז\"ל הולד במעי אמו דומה לפנקס מקופל ראשו בין ברכיו<sup data-n=\"12155\">12</sup> כו' והיינו בחי' חב\"ד חג\"ת שהם נק' תלת גו תלת מפני שכלולי' בנה\"י (ולפי שגם ביניקה בחי' חב\"ד כלול בחג\"ת ונק' ג\"כ תלת גו תלת ע\"כ לעולם נק' בנין ז\"א בבחי' תלת בלבד. ואע\"פ שביניקה הוא [בעל] ו\"ק אבל העיקר הבא בו בגילוי הוא בחי' חג\"ת, וגם בבחי' הגדלו' הרי אין העיקר רק בחי' מוחי' שלו שהן חב\"ד והמדות חג\"ת כלולי' בו ונמשכו אחריו כידוע. ונמצא לעולם עיקר בנינו [הוא] רק תלת, ורק בהיותן בבחי' הגדלו' דוקא אז נק' באות הל' שג'<sup data-n=\"12156\">13</sup> ספי' דחב\"ד הם בגילוי, משא\"כ בעיבור בבחי' הנה\"י שהם בהעלם כו' וד\"ל). ואע\"פ שידוע שתכלית בנין ז\"א הוא בהיותו בעל ט\"ס חב\"ד חג\"ת נה\"י, הנה מ\"מ עיקרו אי[נו] רק תלת דנה\"י, והששה ספי' חב\"ד חג\"ת שבו הם באי' אח\"כ בבחי' התרחבו' והתפשטו' שלו בלבד ואינם התחלת מציאותו. ויובן דבר זה<sup data-n=\"12157\">14</sup> עד\"מ האילן הגדל וצומח [מן ה]ארץ, שתחלת התהוותו בשרשו בארץ קטן הוא ואח\"כ מתגדל ונצמח מעט מעט, דהיינו שמתפשט ועולה בגודל עד למעלה מעלה בגבהו וכמ\"ש כארז בלבנון ישגה<sup data-n=\"12158\">15</sup> כו', וכתי' כי האדם עץ השדה<sup data-n=\"12159\">16</sup> שהאדם נמשל בגידולו לעץ השדה שתחלת התהוות [עיקר מציאותו] בבטן אמו קטן הוא [ב]כמות מאד, דהיינו רק בחי' נה\"י כנ\"ל ואח\"כ מתגדל ומתפשט והוא בחי' היניקה ש[נ]גדלים אבריו וגם מדותיו מעט מעט מתגדלי' וצומחים וגם שכלו צומח אח\"כ ומתרחב, וכ\"ז אינו עיקר מציאותו רק בחי' התפשטו' והתרחבו' שלו בלבד הנק' גידול וצמיחה כדוגמת גידול וצמיחת האילן בלבד וד\"ל.\n<b>וכמו\"כ</b> יובן למשכיל למעלה בחי' אדה\"ע שנק' ז\"א<sup data-n=\"12160\">17</sup>, כידוע שעיקר [בנין] מציאותו הוא בחי' נה\"י שהם טבע המדות [טבעיי'] שלא ע\"פ שכל כלל ואח\"כ מתגדל[י'] המדות יותר ונק' חג\"ת ויש בהם קצת הארת השכל אבל בהעלם גדול כמו משל יניקת החלב<sup data-n=\"12161\">18</sup> ש[מ]גדל האברים כו' וכמ\"ש במ\"א, ואח\"כ מתגדלים המדות יותר להיות בהם גילוי השכל והטעם <span data-k=\"pg\">שס</span> ּ עיקר המנהיג כו' וכידוע, והיינו מפני גידול השכל וכמ\"ש לפי שכלו יהולל איש<sup data-n=\"12162\">19</sup> וכמ\"ש במ\"א. וכ\"ז אינו בא רק בבחי' גידול וצמיחה יתירה על תחלת עצם מציאותו כמובן ממשל הגדלת האילן הנ\"ל, וע\"כ לא נק' ז\"א רק באות הל' שהוא",[["12152","9","<b>שעיקר בנין ז\"א. . נה\"י</b>: ראה גם ע\"ח (שער הולדת או\"א וזו\"ן) שט\"ז, רפ\"א. (שער הפרצופים) שי\"ד, דרוש א. בסמוך הערה 11."],["12153","10","<b>דז\"א</b>: זיד: ליתא."],["12154","11","<b>תלת דכליל גו תלת</b>: נסמן לעיל פ' שמות לח, ד."],["12155","12","<b>הולד. . ראשו בין ברכיו</b>: נדה ל, ב."],["12156","13","<b>שג'</b>: זיד: שי'."],["12157","14","<b>ויובן דבר זה</b>: זיד: ליתא."],["12158","15","<b>כארז בלבנון ישגה</b>: תהלים צב, יג."],["12159","16","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["12160","17","<b>אדה\"ע שנק' ז\"א</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"ה."],["12161","18","<b>מתגדל[י'] המדות. . החלב</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קעז ואילך."],["12162","19","<b>לפי שכלו יהולל איש</b>: משלי יב, ח. ראה גם לעיל רמא, א. תו\"ח ח\"ש קכג, א."]]],[2300540157,"ג' פעמים י\"ס הכלולים בג' מדרגות בלבד<sup data-n=\"12163\">20</sup> שהן בחי' נה\"י. ואע\"פ שנתוסף אח\"כ חג\"ת חב\"ד אינו אלא בבחי' התפשטו' בלבד מג' מדות הראשונים. וגם להיות שהוספה עצמה כמו חב\"ד חג\"ת הן באים ג\"כ בתוס' ג' ג', וא\"כ הרי כל סדר ואופן בנינו הוא רק לג' [ג'] פרקי' חב\"ד חג\"ת נה\"י, ולעולם לא נבנה ביותר מג' בין בתוס' ובין בשרש כנ\"ל ע\"כ הוא באות הל' דוקא (ועוי\"ל בהיפך דדוקא על סוף בנינו במוחי' חב\"ד נק' באות הל' מטעם הנ\"ל [וד\"ל)]. וזה[ו] ענין אות ל' שהוא בחי' בנין<sup data-n=\"12164\">21</sup> ז\"א, ואות הא' דאל הוא בחי' אור אבא שנק' בזהר נהירו דחכמתא המאיר בז\"א שהוא אות הל' והיינו פי' אל כנ\"ל.\n<b>וביאור</b> הדבר הנה אלף פי' ידוע לשון לימוד<sup data-n=\"12165\">22</sup> כמ\"ש אאלפך חכ'<sup data-n=\"12166\">23</sup> הוא בחי' מוחין דאבא שנמשכי' במוחי' דז\"א, ולזה הטעם נא' ויקרא לו אל אלקי ישראל<sup data-n=\"12167\">24</sup> וארז\"ל מי קרא למי הקב\"ה קרא ליעקב אל<sup data-n=\"12168\">25</sup> כו'. דהנה יש להבין מארז\"ל בברכות של חכם הרזים<sup data-n=\"12169\">26</sup> שהוא על אוכלסא של ס\"ר דוקא כו', ולכאורה [י]פלא למה על ס\"ר דוקא, אם מפני הטעם שאמרו לפי שאין דעותיהם שוות ג\"כ על עשרה יש לברך כן שהרי יש עשרה דעות. וגם עיקר הטעם אינו מספיק לענין ברכת חכם הרזים דוקא דלמה יתגלה טעם ס\"ר מיני דיעות מענין חכם הרזים דוקא. אך הנה ידוע דשרש ס\"ר נש\"י<sup data-n=\"12170\">27</sup> הן בחי' ו\"ק דז\"א<sup data-n=\"12171\">28</sup> שנק' ישראל דלעילא שעליו נא' ויקרא לו אל אלקי ישראל כו' כנ\"ל, וע\"כ הקב\"ה קרא ליעקב אל כו'. להיות ידוע בע\"ח דו\"ק דז\"א מסתעפים לס\"ר מדרגות לפי שע\"י בחי' ה\"ח המגדילים לז\"א מתחלקי' המדות דז\"א ה' פעמים לי\"ס, דהיינו פעם [הא'] מתחלקים כאו\"א ליו\"ד, ופעם הב' מתחלק עוד כאו\"א [מה]יו\"ד ונעשה מאה, ופעם ג' מתחלק כאו\"א מהמאה ליו\"ד ונעשה אלף, ופעם הד' מתחלק כאו\"א מאלף ליו\"ד ונעשה רבבה, ופעם הה' כאו\"א מהרבבה מתחלק ליו\"ד ונעשה מאה אלף. ונמצא שו\"ק דז\"א עולה במספר ת\"ר א[ל]ף שהן ס\"ר, והם ס\"ר [שרשי] נש\"י למטה. [ו]ע\"כ יש ס\"ר דעות בישראל<sup data-n=\"12172\">29</sup> לפי שכאו\"א יש לו בחי' ומדרגה פרטי' ומיוחדת לפי אופן שרש נשמתו למעלה במדריגה פרטית שבת\"ר אלף מדרגות המסתעפי' מבחי' ו\"ק דז\"א ע\"כ אין דיעותיהם שוות וכמ\"ש ותוכן רוחות ה'<sup data-n=\"12173\">30</sup> כו'. שהרי אנו רואים בחוש שאין ב' בנ\"א דומים גם בדבר חכ' א' ששומעים מפי רב א' כמו ב\"ש אוסרים וב\"ה מתירים<sup data-n=\"12174\">31</sup> הגם ששמעו מרב א' שכל וטעם א', הנה זה השיג בשכלו השכל כך וזה השיג להיפך לפי שדיעה [והשגה] זו משונה מדיעה והשגה זו וא\"א שישיגו ב' בנ\"א באופן א' ממש מפני חילוקי מדריגות שרש מחצב נשמתם למעלה, שזה",[["12163","20","<b>בלבד</b>: זיד: ליתא."],["12164","21","<b>בחי' בנין</b>: שם: בבחי'."],["12165","22","<b>אלף. . לשון לימוד</b>: נסמן לעיל פ' וארא עח, ב."],["12166","23","<b>אאלפך חכ'</b>: נסמן לעיל טו, ב."],["12167","24","<b>ויקרא לו אל אלקי ישראל</b>: וישלח לג, כ."],["12168","25","<b>מי קרא למי הקב\"ה קרא ליעקב אל</b>: ראה מגילה יח, א. עטרת ישראל (לר' ישראל ב\"ר אברהם מבאהפלי) פ' ואתחנן נו, ב."],["12169","26","<b>בברכות של </b>[זיד: ליתא]<b> חכם הרזים</b>: ברכות נח, א."],["12170","27","<b>ס\"ר נש\"י</b>: נסמן לעיל קפג, ג."],["12171","28","<b>דשרש ס\"ר נש\"י. . ו\"ק דז\"א</b>: ראה גם לעיל רמג, ב. וש\"נ."],["12172","29","<b>ס\"ר דעות בישראל</b>: ראה תניא בהקדמה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670566\" data-slug=\"torat-chaim\" data-id=\"2300670566\">תו\"ח נח נז, ד</a> ובהערה 52."],["12173","30","<b>ותוכן רוחות ה'</b>: משלי טז, ב."],["12174","31","<b>ב\"ש אוסרים וב\"ה מתירים</b>: פסחים נה, א (במשנה)."]]],[2300540194,"שרש נשמתו ודעתו נחצבת מבחי' החסד שבו\"ק דז\"א המסתעף לק' אלף וזה שרש מחצב נשמתו<sup data-n=\"12175\">32</sup> מבחי' הגבורו' שבו\"ק דז\"א, ע\"כ בהכרח שזה יגזור ויתחייב שכלו לחסד וזה יגזור שכלו לדין והוא <span data-k=\"pg\">722</span> ּ ההפרש שבין ב\"ש וב\"ה בכלל. ובפרט גם באותן ששרשן מבחי' ומדרגה א' פרטי' [כמו] מבחי' החסד דו\"ק דז\"א, מ\"מ לא יהי' דע[ו]תיהן שוות לגמרי כי הרי גם בחי' חסד דז\"א מתחלק לק' אלף לפי שכלול מיו\"ד ויו\"ד מיו\"ד. וידוע שבחי' י\"ס המתחלק[י'] ה' פעמים כנ\"ל, היינו שהחסד בעצמותו מתחלק לכמה מדריגות כמו גבו' ות\"ת שבחסד ונצח והוד שבחסד וחוזר כאו\"א מהם להתחלק ליו\"ד פעם ב' וכן פעם ג' וד' ופ\"ה כנ\"ל. ועד\"ז כל הו\"ק דז\"א, א\"כ [הרי] גם בפרט מדרגה א' דחסד דז\"א ימצא כמה אלפים מדרגות חלוקות, ע\"ד דוגמא בבחי' נצח שבחסד המתחלק לי' פעמים<sup data-n=\"12176\">33</sup> בפעם הה' הרי נעשה ק' אלף מדרגות חלוקות וכולן בבחי' נצח כו', ואח\"כ ימצא למטה ג\"כ ק' אלף דיעות שונות גם בהיותן במדרגה א' פרטי'. ובזה יובן בכללות ענין ס\"ר נש\"י שהן ס\"ר דיעות בהכרח, מפני ס\"ר שרשים שלהם בבחי' ו\"ק דז\"א המתחלקי' כאו\"א בפ\"ע מאחר שגם בהתחלק[ות]ם בפ\"ה נחלק לי\"ס א\"כ כל שרש ושרש הוא נכלל בפ\"ע (אך מה שמצינו שיש כמה אנשים שנשמתם נמשך משרש א' ממש כמ\"ש בס' הגלגולים<sup data-n=\"12177\">34</sup> היותו מבחי' תוס' וריבוי<sup data-n=\"12178\">35</sup> מתולדות הנשמות שנמשך מס\"ר שרשים דוקא<sup data-n=\"12179\">36</sup> [דז\"א] כמ\"ש אור זרוע לצדיק<sup data-n=\"12180\">37</sup> כו' וכמ\"ש במ\"א בענין מספר כל זכר לגולגלותם<sup data-n=\"12181\">38</sup> כו' וד\"ל).\n<b>והנה</b> בחי' התחלקות ו\"ק דז\"א לת\"ר אלף מדריגות כנ\"ל הוא מפני בחי' התחלקו' המוחי' דמדות דז\"א, דהיינו בחי' השכל והטעם שבכל מדה ונק' חב\"ד דז\"א עד\"מ באדם התחתון שההתפעלו' המדה נולדה מפני הטעם והשכל אז מתחלקי' המדות לכמה מדריגות שונים כנ\"ל. כמו שאנו רואים בחוש שבתינוק שאין שכלו מאיר במדותיו לכן מדותיו בקטנות בלתי התחלקות [והסתעפות] כלל לכמה מדרגות, אלא כאשר יאהב לדבר מה ויתפעל בלבו לא יהי' בזה ריבוי חלקים רק בענין א' מצומצם להיות כמו שהוא, משא\"כ בגדול ששכלו מאיר במדותיו הנה יהי' התפעלו' באהבתו משכל וטעם ודעת בכמה אופנים וענינים חלוקים, וגם לא יתפעל לדבר קטן הערך כו', והוא הנק' גידול המדות והתפשטותם עד\"מ כנ\"ל בצמיחת וגידול האילן כו', והיינו לפי ששכלו גדול ביותר ומפני גודל השכל דוקא יגדלו המדות וכמ\"ש לפי שכלו יהולל איש כו' וד\"ל. ונמצא לפ\"ע גודל השכל והתפשטותו לחלקי' רבים כך יהי' ערך גידול המדות והתחלקותם והתפשטותם לכמה ענינים ואופנים שונים כו'. וא\"כ הרי מובן עכ\"פ דבחי' התחלקות השכל והטעם הוא",[["12175","32","<b>מחצב נשמתו</b>: ז: נשמתו ודעתו נחצבה."],["12176","33","<b>פעמים</b>: זיד: ליתא."],["12177","34","<b>כמה אנשים. . משרש א'. . בס' הגלגולים</b>: ראה שם פכ\"ח."],["12178","35","<b>היותו מבחי' תוס' וריבוי</b>: זיד: היינו ג\"כ בתוס' ריבוי."],["12179","36","<b>דוקא</b>: יד: דו\"ק."],["12180","37","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["12181","38","<b>מספר כל זכר לגולגלותם</b>: ראה במדבר ב, ב. מאמרי אדה\"ז תקס\"ו ס\"ע קצ ואילך."]]],[2300540228,"הסיבה להתחלקו' המדות ושניהם כא' יצמחו ויתפשטו (עד\"מ גידול האילן שנגדל פנימיותו וחיצוניותו כא' כו' כמ\"ש במ\"א וד\"ל). ולפ\"ז [הרי] ע\"ד דוגמא כשמתפעל באהבה פרטי' ויש בה כמה ענינים מכל אלו החלקים יש בטעם ושכל<sup data-n=\"12182\">39</sup> שבאהבה. וזהו בטל דבר בטל[ה] אהבה<sup data-n=\"12183\">40</sup> כי כל פרטי האהבה כבר נחלקו בשכל וטעם של האהבה שנק' דבר, ואם יבטל [דבר] הטעם לגמרי כל חלקי האהבה בטלים ממילא, ואמנם כל בחי' התחלקו'<sup data-n=\"12184\">41</sup> שכל וטעם [א'] ה[וא] מתחלק [לכמה מדרגו'] אח\"כ, הנה<sup data-n=\"12185\">42</sup> תחלת התהוותו ושרשו במוח החכ' שבראש הנק' כח השכל העצמי להשכיל כל שכל וטעם אינו אלא שכל וטעם א' <span data-k=\"pg\">שסא</span> ּ בלתי התחלקות, ע\"ד דוגמא השכל והטעם למדת האהבה בראשית התהוותה והתמשכותה ממוח החכ' כוללת כמה מיני שכלי' וטעמים פרטים ואח\"כ מתחלקת בבואה לבחי' התפשטו' בהתפעלות המדה כו'.\n<b>וכך</b> יובן הדוגמא למשכיל למעלה מכ\"ז [ש]בחי' המוחין דז\"א מתחלקי' לס\"ר מדרגות בבואם למדות דז\"א וממילא מתחלקי' המדות לס\"ר כו' כנ\"ל, וכמ\"ש לפי שכלו יהולל איש שלפי ערך גידול השכל כך גידול המדות כו', והיינו ע\"י בחי' ה\"ח המגדילי' ומחלקי' כל ספי' ליו\"ד ספי' ה\"פ כנ\"ל. אמנם שרש המשכת המוחין דז\"א כמו שהן נמשכי' מבחי' מוחי' דאו\"א כו' הרי הוא [ב]בחי' אור והמשכה כללית עדיין ואח\"כ מתחלקי' כנ\"ל, וא\"כ הרי מובן לפ\"ז שבחי' החכ' דאור אבא עצמו המאיר וממשיך למוחי' הכללי' דז\"א עד\"מ כח השכל העצמי שבאדם שמשכיל שכליים רבים כו' הרי הוא יותר בכללות והוא הנק' בשם חכם הרזים, לפי שהארת אור אבא [ל]המשיך אור כללות המוחין דז\"א הרי הוא כולל כל פרטי ס\"ר דיעות שנמשכו להתחלקות המוחין דו\"ק דז\"א אח\"כ ע\"כ נק' חכם הרזים להיות[ו] כוללם יחד (והיינו עד\"מ<sup data-n=\"12186\">43</sup> שאמרו ביהושע איש אשר רוח בו<sup data-n=\"12187\">44</sup> שיכול להלוך נגד רוחו של כאו\"א להיותו כולל כל ס\"ר דעות ישראל כו'). וזהו הטעם שאין מברכין ברכת חכם הרזים רק על אוכלסא של ס\"ר ולא בפחות מזה ואפי' א', כי גם בחסרון א' מס\"ר הרי נחסר פרט א' גם במקור שרש הכללי שהוא [בחי'] אור אבא הממשיך כללות המוחי' דז\"א [ו]אינו נק' חכם הרזים לפי שלא יאיר אור החכ' [ב]ו\"ק דז\"א כ\"א על התחלקות ס\"ר בשלימות כו'. ומה שאו' ברוך חכם הרזים כי [ב]בחי' המשכת אור החכ' בס\"ר מדרגות [ל]ו\"ק דז\"א נמשך ונגלה אור הברכה בחכ' שהוא הארת<sup data-n=\"12188\">45</sup> אוא\"ס שבכתר שנק' ברוך, כידוע בענין הברכה שהוא ע\"י [בחי'] גילוי אוא\"ס דוקא כמ\"ש ויקרא את שמם אדם ויברך אותם<sup data-n=\"12189\">46</sup> כו' שהוא ע\"י התכללות זו\"נ<sup data-n=\"12190\">47</sup> [ש]נמשך בחי' אור מקיף עליהם כמבואר במ\"א בענין החופה שהוא בחי'",[["12182","39","<b>מכל. . ושכל</b>: זיד: חלוקים, כל אלה יש בשכל וטעם."],["12183","40","<b>בטל דבר בטל[ה] אהבה</b>: אבות פ\"ה, מט\"ז."],["12184","41","<b>התחלקו'</b>: זיד: ליתא."],["12185","42","<b>הנה</b>: שם: אבל."],["12186","43","<b>עד\"מ</b>: שם: ע\"ד."],["12187","44","<b>איש אשר רוח בו</b>: פינחס כז, יח. ספרי שם. תניא בהקדמה."],["12188","45","<b>שהוא הארת</b>: זיד: מהארת."],["12189","46","<b>ויקרא את שמם אדם ויברך אותם</b>: בראשית ה, ב [בהיפך הסדר]."],["12190","47","<b>זו\"נ</b>: ז: דכר ונוק'. יד: ליתא."]]],[2300540260,"או\"מ<sup data-n=\"12191\">48</sup> על החתן וכלה כו'. וגם כאן בבחי' התחלקות מס\"ר נשמות נמשך תוס' גילוי אוא\"ס בחכ' שכלולי' יחד כנ\"ל וע\"כ או' ברוך חכם הרזים כו', ולכך אין מברכין [ברכה] זו רק על ס\"ר דוקא וד\"ל.\n<b>ובכ\"ז</b> יובן פי' אל בישראל דהל' הוא בבחי' ז\"א כנ\"ל והא' הוא בחי' המשכות אור אבא להיות מקור ושרש להמשכת מוחין דז\"א כנ\"ל בענין חכם הרזים כו', ולזה מורה אות א' אאלפך חכ' לשון לימוד כי הוא בחי' המשכת כח השכל וירידתו למטה במדות להתחלק לס\"ר דיעות כנ\"ל. וזהו הטעם שארז\"ל הקב\"ה קראו ליעקב אל כמ\"ש ויקרא לו אל כו' לפי שאותיות א' ל' הנ\"ל הוא הנמשך מאור אבא בז\"א ע\"כ נק' אל זה אלקי ישראל, והקב\"ה הוא עצמו' המאציל וקראו ליעקב שהוא בחי' ז\"א<sup data-n=\"12192\">49</sup> בשם אל להיותו מקבל מא' שבו שורה עצמו' אוא\"ס כנ\"ל. ומטעם זה לכללו' נשמות הנק' בשם יעקב וישראל למטה קראם הקב\"ה אל כי שרש נשמתם<sup data-n=\"12193\">50</sup> נמשך מאור אבא כו' כמ\"ש כי אתה אבינו<sup data-n=\"12194\">51</sup> כו' (היינו שא' מי קרא למי כו' דלפי האמת ב' הפי' יתכנו דיעקב קרא להקב\"ה שהוא ז\"א<sup data-n=\"12195\">52</sup>, אל <span data-k=\"pg\">724</span> ּ להיותו מקבל מאור אבא, וכן הקב\"ה שהוא ז\"א קרא ליעקב דלתתא אל, מצד ס\"ר נשמות שלהם למעלה באור אבא כו' וד\"ל).\n<b>אך</b> הנה כל הנ\"ל בפי' ישראל שהוא בחי' המשכת אור החכ' במדות כו' הוא הנק' בחי' התיקון דהיינו בחי' ריבוי התכללות של המדות בס\"ר חלקי מדרגות מצד התחלקות המוחין כנ\"ל, וגם ידוע שהתחלקות הזאת באה ג\"כ מצד ריבוי [הכלים] כלים מכלים שונים [שזהו כל עיקר התיקון שמתלבש האור בריבוי כלי'] וממילא יהי' בריבוי התחלקות<sup data-n=\"12196\">53</sup> וכמ\"ש במ\"א ביאור זה. אבל הנה בחי' התהו הם בחי' אור[ות] שבלתי מתלבש[ים] בכלים כלל וממילא אין בהם התחלקות ל[חלקי'] פרטים אלא הם בחי' אורות כללי' [דוקא כו']. וביאור זה הנה יש להקדים את הידוע שיש ב' [מיני] מדות, הא' בחי' המדות הטבעי' שלמטה מן השכל כמו טבע הרחמנות או טבע האכזריות שתלוים ברך הלבב בטבע או בקושי הלבב בטבע, [טבע] הקמצנות או טבע הפזרנות וכיוצא בהם, שלהם אין צריך שכל וטעם כלל אלא בלא טעם ושכל יתנהגו ע\"פ<sup data-n=\"12197\">54</sup> עצם טבעם כידוע. והב' בחי' המדות השכליים, דהיינו כמו המשכת החסד והטוב להטיב לטובים שלא מצד טבע הרחמנות<sup data-n=\"12198\">55</sup> אלא מפני שהשכל יגזור ע\"ז, וכן להיפך [ב]מדה\"ד לרעים כו' שלא מצד טבע האכזריות אלא מפני שהשכל [יגזור] על דבר הרע שעשה וכיוצא. והנה אע\"פ שהמדות הללו נמשכים ע\"פ השכל והטעם מ\"מ אין זה רק שהנהגתן הוא ע\"פ [ה]שכל בלבד, אבל לא שעיקר מציאותם מתהווה מן השכל רק שהשכל מנהיגם דהיינו שימשיך את",[["12191","48","<b>החופה. . או\"מ</b>: ראה גם ביאוה\"ז בחוקותי פד, סע\"א ואילך. מאמרי אדה\"ז תקס\"ז ע' קפט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381322\" data-slug=\"likkutei-torah\" data-id=\"4001381322\">לקו\"ת שה\"ש מח, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370217\" data-slug=\"torah-or\" data-id=\"3901370217\">תו\"א ויחי מח, א</a>."],["12192","49","<b>ליעקב. . ז\"א</b>: ראה ע\"ח (שער פרצופי זו\"ן) של\"א, פ\"א. (שער הקליפות) שמ\"ח, פ\"ג. שעה\"י כו, א ואילך."],["12193","50","<b>נשמתם</b>: ז: ס\"ר נשמות שלהם. וראה בסמוך בפנים שו\"ה ס\"ר."],["12194","51","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["12195","52","<b>להקב\"ה שהוא ז\"א</b>: ראה גם לעיל פ' וארא נד, ג. וש\"נ."],["12196","53","<b>האור בריבוי כלי'. . התחלקות</b>: ראה גם לעיל ריב, ד. פ' שמות מה, א ואילך."],["12197","54","<b>ע\"פ</b>: זיד: מצד."],["12198","55","<b>הרחמנות</b>: שם: הטוב."]]],[2300540289,"מציאותם מהעלם לגילוי, כי מדת החסד כבר ישנ[ה] במציאות בטבעה כו' כנ\"ל. אך ע\"י השכל והטעם אשר יגזור לטוב ולחסד הנ\"ל יעורר וימשיך למדת החסד והטוב להטיב כו'. וכן להיפך ע\"י השכל שיגזור לדין ועונש יעורר למדה\"ד שכבר ישנה במציאות בטבע ואין השכל רק כמו איש המראה לזולתו מקום שישכון בו, כך השכל אינו אלא מראה מקום למדה דהיינו באיזה אופן תתלבש ותצא ל[ידי] גילוי אם כך או כך. כי עצם הטוב והחסד שבטבע הטוב הוא [רק] כח פשוט וע\"י השכל יצוייר ויתלבש בכמה אופנים שונים לפי אופן הוראת הטעם והשכל, נמצא שאין בו חידוש בעיקר המציאות של המדות גם במדות השכלי' רק שמתנהגי' ע\"פ השכל כו'. וא\"כ בהכרח לומר שאין המדות נק' תולדות השכל כי התולדה בעצם הוא התהוות השפע מחדש כו', אלא צ\"ל שהמדות עוברות דרך השכל מן ההעלם לגילוי שהרי אנו רואים שהשכל מעביר אותם ממקום למקום לכל אשר יגזור, ונמצא שהשכל נק' מעביר של המדות מפני שהמדות עוברים דרך השכל אבל אין זה רק דרך מעביר בעלמא ולא שהשכל מחדש תחלה התהוות מציאותם כו' וד\"ל.\n<b>והנה</b> יש שני מיני מופתים לדבר זה הא' מה שאנו רואים שיש מדות לתינוק ולבהמות וחסרי דעת ושכל א\"כ בהכרח שיש למדות שרש מיוחד בעצם הנפש זולת השכל, וא\"כ גם בגדול שמדותיו מתנהגים ע\"פ השכל ודאי יש להם שרש מיוחד בעצם הנפש כנ\"ל. והב' הוא בהקדים שרש מהות המדות, והוא כמו מדת האהבה שהאדם אוהב איזה דבר מה הנה העיקר בזאת האהבה אינו אלא אהבה שאוהב א\"ע בלבד, והכולל לכל מיני אהבות הוא רק אהבת עצמו בלבד. כי הרי מה שאוהב <span data-k=\"pg\">שסב</span> ּ הדבר כמו הממון וכיוצא, עיקר ההתפעלו' האהבה אינה אלא שיהי' הממון שלו ויהי' מונח בכיסו אבל הממון של חבירו שלא יבוא לידו אינו מתפעל לאהוב אותו כלל, כי תאוות הממון להיות<sup data-n=\"12199\">56</sup> אצלו הוא לטובתו והאדם אוהב א\"ע אהבה כללי' ומכוון הכל לטובת עצמו, ע\"כ כ\"ז<sup data-n=\"12200\">57</sup> שיאהב אינו אלא כשהוא לטובת עצמו בלבד ולא בשביל דבר הנאהב מצד עצמו גם כשלא יהי' לטובתו כלל, וע\"כ לא יאהב דבר שיהי' רק לטובת אותו דבר בלתי שיתוף טובת עצמו. וכנראה בחוש הטבע שמטבע האדם לחפוץ ולאהוב כל דבר הנחמד למראה שיהי' אצלו דוקא, והיינו לפי שכללו' הסיבה לכל מיני אהבה הוא רק מה שאוהב א\"ע. והמופת לזה ממה שאנו רואים שכאשר ירגיז אדם על נפשו וימאס בחייו מצד איזה דבר חול[י] הנק' מרה שחורה וכיוצא לא ישתוקק לשום דבר, גם למאכל ערב או בגדים ואבנים טובות ולא יחפוץ אהבת אהובים לו כאשתו ובניו מפני שאינו אוהב א\"ע, וכל מה שיאהוב א\"ע יותר יהי' בעל תאוה להתאוות לדברים הטובים לו וכל שמופשט יותר מאהבת עצמו מופשט יותר מתאות דברים",[["12199","56","<b>תאוות הממון להיות</b>: שם: כל הממון."],["12200","57","<b>כ\"ז</b>: שם: כל מה."]]],[2300540317,"הטובים לו. וכן במדת השנאה [הרי] הוא רק מפני שכל דבר המזיק ורע לו<sup data-n=\"12201\">58</sup> לנפשו שונאו להרחיקו מעליו בתכלית, וזהו ג\"כ מצד שאוהב א\"ע וע\"כ מאד ירחיק כל דבר שיזיק לו והמנגד לו, וכל מי<sup data-n=\"12202\">59</sup> שאינו אוהב א\"ע כ\"כ יוכל לסבול לדבר המנגד ולא ישנאנו כ\"כ (ויש דברים שאדם אוהב שאינם נאהבים מצד עצמן כלל רק מפני שהן לטובתו כמו שאוהב את המאכל שיאכלנו אע\"פ שיבא לידי כיליון במעיו וכיוצא בהן). ונמצא מובן ממדת האהבה ומדת השנאה שאין זה רק אהבת עצמו, ואהבת עצמו הוא מה שהאדם אוהב חיי נפשו, וידוע שא\"א לומר ש[ב]גופו יאהב נפשו אחר שהגוף בלתי חיות כלל בלא הנפש אלא מוכרח [לומר] באהבת חייו שהוא ענין אהבת הנפש עצמה דהיינו מה שאוהבת א\"ע, וא\"כ מקור של המדות שתלויי' באהבת עצמו היינו שתלוים באהבת הנפש א\"ע. ולפ\"ז מובן ממילא שיש שרש למדות בעצם הנפש כנ\"ל דאל\"כ לא הי' תלוי' התהוות המדות באהבת עצמו דוקא, וזהו המופת הב' שגם המדות שמתנהגי' ע\"פ השכל יש להם שרש בעצם הנפש ואינם עוברים בשכל רק דרך מעביר כנ\"ל וד\"ל. וכנראה בחוש שכל מיני אהבות הטבעי' לדברים הטובים לנפשו וכל מיני שנאה לדברים הרעים לנפשו א\"צ כלל לשכל [ו]טעם להתבונן אם הם טובים או רעים כמו שא\"צ להתבונן בשכל וטעם למה יאהב [חיי] נפשו וכיוצא, וכמו מדת הטבעי' של הבהמה שתאהב מאכלים הערבים לה ותרחק מאכילת כל<sup data-n=\"12203\">60</sup> דבר המזיק לה בלי שכל וטעם כלל וכלל להיותם תלוי' באהבת עצמ[ה] כו'. וא\"כ גם שיגזור השכל ג\"כ לאהוב דבר הטוב מפני שמתבונן באיכות טובו ולשנוא דבר הרע מפני שהשיג באיכות רעתו, אין התבוננו' הזאת מחדשת לעיקר מציאת האהבה והשנאה הטבעי' רק שמברר יותר את הטוב ואת הרע ואינו אלא כמראה מקום כנ\"ל. ועד\"מ ההולך באישון חשך ואפילה<sup data-n=\"12204\">61</sup> שבסיבת הדלקת האור ישנא דבר הרואה למזיק ויחמוד ויאהב לדבר הטוב שרואה, שאין עצם החמדה והשנאה דבר חדש רק שבחשך לא ראה <span data-k=\"pg\">726</span> ּ לבחור ולברר בין טוב לרע וע\"י האור נתברר למראה עיניו בלבד, אבל מה שמואס ברע ובוחר בטוב כשנראה לו הוא ע\"פ הטבע מפני [אהבת] עצמו כנ\"ל וד\"ל. ונמצא שאין יתרון מעלה למדות האדם שהן ע\"פ השכל על מדות הבהמה רק בענין בירור והבחנת דברים טובים ודברים רעים בלבד שע\"פ השכל ישיג ויבחין יותר לדבר טוב יותר לנפשו וכמו השגת העושר והכבוד שאין זה בתינוק ובהמה וחסרי דעת, אבל מה שאחר הבירור<sup data-n=\"12205\">62</sup> יחפוץ לעושר ויאהבנו שהוא מפני אהבת עצמו בזה שוין האדם ובהמה כי בכללות ענין מואס ברע ובוחר בטוב שוין הן כו' וד\"ל.\n<b>אך</b> [הנה] אע\"פ שמובן מכל הנ\"ל שב' מיני מדות הנ\"ל השכלי' והטבעי' שוין הם בעצם במציאותן מצד שרשם בעצם הנפש דוקא ולא בשכל, עכ\"ז יש הפרש גדול בין מדות הטבעי' למדות",[["12201","58","<b>ורע לו</b>: שם: ליתא."],["12202","59","<b>מי</b>: שם: ליתא."],["12203","60","<b>ותרחק מאכילת כל</b>: שם: ותרחיק מאכל וכל."],["12204","61","<b>ואפילה</b>: שם: ליתא."],["12205","62","<b>הבירור</b>: שם: ההבחנה."]]],[2300540342,"השכלי' בענין התוקף וחוזק כחן שמדות הטבעי' חזקי' ותקיפי' בכחן הרבה יותר ממדות השכלי', אע\"פ שלכאורה דבר זה כפלא יחשב מאחר ששרש א' להן בעצם הנפש מפני אהבת עצמ[ו] כנ\"ל. אך הענין הוא לפי שכח השכל המתפשט במדות הטבעי' כמו שיגזור השכל לאהוב דבר מפני שהשיג[ו] באיכות טובו, הנה השכל הזה שולט ומושל על ההתפעלו' האהבה לדבר ההוא עד שלא יתפעל רק במדה הקצובה רק לפי אופן הוראת השכל בלבד ומה שישיג ויגזור השכל הפכו לשנוא הדבר ישנאנו וכן להיפך משנאה לאהבה כו'. ונמצא אין המדות גומרי'<sup data-n=\"12206\">63</sup> ונמשכי' אחר השכל בתוקף וחוזק כלל, כי עיקר תוקף ותגבורת הכח ההוא הוא כח העמדה על מקומו וטבעו בבל ישונה ולא יכוף א\"ע כמו האר[ז] שמושרש [בארץ] בעומק שלא יזיזוהו כל הרוחות שבעולם משא\"כ הקנה הרך כו'. אבל המדות הטבעי' הן תקיפי' וחזקים הרבה יותר עד שלא יחלשו כחן וטבען משום דבר, גם מפני השכל שיחייב היפוכו אין להשכל שליטה עליהן כלל וכלל, כידוע שטבע האכזריות או טבע הרחמנות לא יועיל כח השכל כלל לבטלם מעיקרם, כי גם שהשכל מחייב להכות ולענוש את הרשע מ\"מ טבע הרחמנות עושה פעול[תו] ולא יכול להכות[ו] כו', וכן מי שיתאוה מאכל ברעבותו<sup data-n=\"12207\">64</sup> אין השכל מועיל לבטל הרעבון וכיוצא (רק להשתיק כח התפשטותם יש בכח השכל כו' וזה נק' לאכפיי' כו' ולא לאתהפכא כו' כידוע). והיינו שאמרו לעולם יהא אדם רך כקנה<sup data-n=\"12208\">65</sup> רק<sup data-n=\"12209\">66</sup> במדותיו להכניעם תחת ממשלת השכל ולא יהא קשה כארז במדת הטבעי' כו', וא\"א לומר ששרש המדות הטבעי' יותר מגיעים בעצם הנפש משרש המדות השכלי' אחר שמבואר ומובן למעלה<sup data-n=\"12210\">67</sup> מכל הנ\"ל דשרש ב' המדות הללו תלוין באהבת עצמו, ואין השכל רק כח המברר ומבחין איזה דבר לאהוב ואיזה לשנוא כו'. אלא בהכרח לומר בטעם חיזוק ותוקף המדות הטבעי' ממדות השכלי' לפי שהתפעלות המדות הטבעי' הן התפעלו' הנפש בפנימיותו יותר ע\"כ אין בכח השכל להטותם מהיפך להיפך כלל כנ\"ל, משא\"כ המדות הנמשכי' ע\"פ השכל אע\"פ שהם ג\"כ מצד שרשם בעצם הנפש, אבל אין ההתפעלו' עצמו' הנפש כ\"כ ע\"כ יש בכח השכל להטותם כפי שיגזור כו'. וכנראה בחוש שכאשר השכל יחייב לאהוב דבר מה [ב]מהרה וב[נ]קל תבטל, אבל כשהטבע יחייבו לאהוב לא <span data-k=\"pg\">שסג</span> ּ תבטל לעולם, לפי שמה שהשכל יעורר את האהבה היא באה רק לפי כח השכל ולא בכח עצמי' טבעה, משא\"כ כשעצמי' הטבע מעורר לא יפול בה שינוי וביטול [כמו שאין שינוי וביטול ל]עצם הנפש. ומכ\"ז הוראה גמורה מה שיש הפרש בין מדות הטבעי' למדות השכלי' הגם שהשכלי' ג\"כ<sup data-n=\"12211\">68</sup> מפני אהבת עצמו היינו מפני שאין אהבת עצמו שבמדות השכלי' שנמשכה ונתעוררה ע\"פ השכל ערך כלל לגבי הארת עצמי'<sup data-n=\"12212\">69</sup> שמצד טבעי' העצמי' והוא ג\"כ ענין אהבה הטבעי' מפני שאוהב א\"ע כו' (כי גם באהבת עצמו יש ב' מדריגות, הא' מה שהשכל",[["12206","63","<b>גומרי'</b>: שם: נגררי'."],["12207","64","<b>ברעבותו</b>: שם: ברעב."],["12208","65","<b>לעולם יהא אדם רך כקנה</b>: תענית כ, סע\"א."],["12209","66","<b>רק</b>: ז: ליתא. יד: חסר. וכנצ\"ל: רך."],["12210","67","<b>למעלה</b>: שם: ליתא."],["12211","68","<b>שהשכלי' ג\"כ</b>: ז: חסר. יד: שהטבעי'."],["12212","69","<b>הארת עצמי'</b>: ז: חסר. יד: אהבת עצמו."]]],[2300540365,"יחייב לאהוב א\"ע. והב' אהבת עצמו מצד הטבע בלא שכל וטעם כלל כו' וכנ\"ל וד\"ל).\n<b>ומעתה</b> יש להבין [הנמשל למעלה] מכל פרטי הדברים המבוארים למעלה בענין ב' בחי'<sup data-n=\"12213\">70</sup> מיני מדות הנ\"ל, דהנה מבואר למעלה ענין בחי' מדות הטבעי' כמו מדת החסד מצד הטבע הטוב כו', כך למעלה בבחי' מדות דאצי' יש ג\"כ בחי' מדות טבעי' והוא כמ\"ש טוב ה' לכל<sup data-n=\"12214\">71</sup> כו' והוא סיבת התפעלות של<sup data-n=\"12215\">72</sup> חסד עליון מאצי' לבי\"ע (וכן ההשפעה מן המאציל לנאצלים הוא ג\"כ מצד טבע הטוב להטיב כמ\"ש כי חפץ חסד הוא<sup data-n=\"12216\">74</sup> וכמ\"ש בע\"ח<sup data-n=\"12217\">73</sup> וד\"ל) וזה נק' בחי' נה\"י שבמדות דז\"א והמה א\"צ למוחי' כלל (ובזה[ר] נק' בדי ערבות<sup data-n=\"12218\">75</sup> שאין בהם טעם וריח כו' כמ\"ש במ\"א באריכות), אלא מעצמם דוקא יתנהגו (וכמשארז\"ל בדורו של אנוש<sup data-n=\"12219\">76</sup> שהיו ניזונין בחסדו של הקב\"ה כו', ואע\"פ שעבדו ע\"ז) מאחר שלא מאיר הארת השכל והטעם לחסד זה רק מצד טבע הטוב כנ\"ל וד\"ל. ובחי' המדות שכליי' היינו שהשכל יגזור להטיב החסד ולא מצד [ה]טבע כו' כנ\"ל, כך למעלה במדות דז\"א שהוא נק' בחי' חג\"ת שהן מדות דאצי' שהם נמשכי' ונתהווי' ע\"פ טעם ומוחי' דוקא מבחי' הטעם והמוחי' שבמדות שנק' חב\"ד דז\"א, וכללות ג' אלה המדריגות חב\"ד חג\"ת נה\"י נק' מושכל מורגש מוטבע<sup data-n=\"12220\">77</sup> וכולם במדות כידוע ומבואר במ\"א וד\"ל.\n<b>והנה</b> מבואר למעלה דגם בחי' המדות השכליי' אין התהוו' עיקר מציאותם מן השכל רק שהשכל יעורר וימשיך את הטבע של המדות כך או כך כו', ואין המדות נק' תולדות של השכל רק שעוברים דרך השכל כו' כנ\"ל באורך. הנה למעלה מובן ג\"כ מזה דגם בחי' המדות חג\"ת דז\"א דאצי' הגם שמתנהגי' [רק] ע\"פ המוחי' חב\"ד דז\"א שנמשכו ממוחי' דאו\"א דאצי' עד\"מ הטעם והשכל של האהבה שנמשך ממוח החכ' שהיא כלל[ו]' כח השכל כו', מ\"מ אין עיקר התהוות מציאותם ממוחי' דאו\"א בדרך תולדה חדשה, אלא רק שבחי' מוחי' דאו\"א שנמשכו בבחי'<sup data-n=\"12221\">78</sup> חג\"ת הוא מנהיג אותם ומעורר אותם לצאת מן בחי' ההעלם עצמות שלה לידי גילוי באופנים שונים כפי אופן הוראת המוחין וכמו האיש המראה מקום כנ\"ל. כך הוא<sup data-n=\"12222\">79</sup> בחי' המוחי' דאו\"א שבז\"א מציירים ומלבישים את המדות בכמה אופנים שונים אבל לא שעיקר תחלת מציאותם מתחדשי' מן המוחי' דאו\"א. ומ\"ש",[["12213","70","<b>בחי'</b>: זיד: ליתא."],["12214","71","<b>טוב ה' לכל</b>: תהלים קמה, ט."],["12215","72","<b>התפעלות של</b>: זיד: השפעת כל."],["12216","74","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["12217","73","<b>טבע הטוב להטיב. . בע\"ח</b>: נסמן לעיל פ' שמות לד, ג."],["12218","75","<b>נה\"י. . בדי ערבות</b>: ראה זהר ויחי רכ, ב (ובאוה\"ח שם). שם (בהשמטות) רסב, א. בלק קצג, ב (ובמק\"מ שם). מאמרי אדה\"ז תקס\"ה ח\"א ע' תטז. תקס\"ח ח\"א ע' שטז. ביאורי הזהר בשלח מז, ד. שעה\"י קלג, ב ובהערה 45."],["12219","76","<b>בדורו של אנוש</b>: נסמן לעיל כד, ד."],["12220","77","<b>מושכל מורגש מוטבע</b>: ראה פי' הראב\"ד והרמב\"ן לס\"י פ\"א, מ\"ה. מאמרי אדה\"ז אתהלך ע' קמד. ביאוה\"ז בשלח מח, א. מאמרי אדה\"א נ\"ך ע' קיא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670092\" data-slug=\"torat-chaim\" data-id=\"2300670092\">תו\"ח נח מז, א</a>."],["12221","78","<b>בבחי'</b>: זיד: במדות."],["12222","79","<b>הוא</b>: שם: ליתא."]]],[2300540386,"בזהר דבינה דאצי' נק' אימא עילאה<sup data-n=\"12223\">80</sup> [ו]כמ\"ש אם <span data-k=\"pg\">728</span> ּ הבנים שמחה<sup data-n=\"12224\">81</sup> וכתיב כי אם לבינה תקרא<sup data-n=\"12225\">82</sup> כו', דמשמע שהמדות דז\"א נק' בנים שנולדים דרך תולדה מן הבינה, היינו מפני שבתחלה הי' בבחי' עיבור במעי אימ[ו] ועד\"מ הולד שבמעי אמו [ונולד לחוץ] שביציאתו לחוץ א\"צ לאמו כלל כי מדותיו מתנהגי' ע\"פ שכל עצמו ואז מה שבינתו מנהיג מדותיו לא נק' אם כלל כי רק מעביר בעלמא כנ\"ל וד\"ל (וכמדות שבאדם התחתון שעיקר מציאותם כבר נמצאו בטבע מעצם הנפש רק שהשכל בחי'<sup data-n=\"12226\">83</sup> מנהיג[ם] בלבד [כנ\"ל<sup data-n=\"12227\">84</sup>. ו]כך למעלה הרי אמרו באדר\"ז דז\"א בעתיקא עצמ[ו] אחיד<sup data-n=\"12228\">85</sup> [ו]הוא למעלה גם מבחי' או\"א, כי הרי בחי' מוחי' דאבא ואימא אינם נמשכים רק מבחי' המזלות<sup data-n=\"12229\">86</sup> דא\"א מזל<sup data-n=\"12230\">87</sup> ונוצר מזל ונקה כו'. וגם או\"א עצמ[ן] שנק' חו\"ב<sup data-n=\"12231\">89</sup> תרין<sup data-n=\"12232\">90</sup> כו'<sup data-n=\"12233\">88</sup> והוא כמו מוח ההבנה ומוח התפיסא כידוע<sup data-n=\"12234\">91</sup> אינם מקבלים רק מבחי' מו\"ס דא\"א<sup data-n=\"12235\">92</sup> ) שהוא כמו בחי' המשכיל ההיולי שבאדם כידוע<sup data-n=\"12236\">93</sup>. אבל ז\"א שהוא בחי' ו\"ק דז\"א מצד עצם טבעם ומהותם זולת הוראת השכל בבחי' ע\"י עצמו אחיד כו', והיינו בבחי' [ה]ג\"ר דע\"י שהן מתנשאים מימות עולם דא\"א ודז\"א ולכך נאמר ע\"י מלשון המעתיק הרים<sup data-n=\"12237\">94</sup> כו'. כי ידוע ההפרש במדות דא\"א שמתלבשי' בנאצלי' כידוע דאו\"א מלבישים לזרועות דא\"א<sup data-n=\"12238\">95</sup> ועז\"נ שאל נא לימים ראשונים<sup data-n=\"12239\">96</sup> כו', אבל בחי' ג\"ר דע\"י בלתי מתלבשים בנאצלי' ומתנשאי' מימות עולם דא\"א שנק' ו' ימי בראשית כו'. אך ו\"ק דז\"א למטה לכאורה שרשם רק במדות דא\"א שלמעלה מבחי' חו\"ב ונק' ימי קדם<sup data-n=\"12240\">97</sup> או הרי קדם<sup data-n=\"12241\">98</sup>, כידוע שהם המדות שלמעלה מן השכל אלא מצד טבע העצמי וכמו אה\"ר שברצון כו', אך באמת שרשם יותר למעלה והוא [ב]בחי' פנימי' דע\"י כנ\"ל. והטעם יובן ע\"פ הנ\"ל גם בשרש ענין המדות הטבעי' שהוא רק אהבת עצמו בלבד והמופת מחולי המ\"ש כו' כנ\"ל, ואהבת עצמו שהוא אהבת חיים היינו מה שהנפש אוהבת עצמה ע\"כ תאהוב כל [ה]דברים הטובי' [לה ולנפשה] ותשנא כל דברים המזיקי' לה ורע לה, ואין צריך שכל וטעם כלל למאוס ברע ולבחור בטוב כו' רק שהשכל מברר יותר את הטוב ואת הרע כו' כנ\"ל באריכות.\n<b>והנמשל</b> מזה יובן למעלה ג\"כ בשרש בחי' המדות הטבעי' שברצה\"ע שנק' א\"א שלמעלה מן השכל שנק' חכ' ובינה כו' שהוא ג\"כ בא מאהבת המאציל א\"ע כבי' עד\"מ שאדם אוהב חיי נפשו כו'. ולמעלה בחי' אהבה זו בחי' א\"ס ממש ולכך",[["12223","80","<b>דבינה. . אימא עילאה</b>: ראה ע\"ח (שער או\"א) שי\"ד, פ\"ח."],["12224","81","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["12225","82","<b>כי אם לבינה תקרא</b>: נסמן לעיל פ' וארא סט, ב."],["12226","83","<b>בחי'</b>: ז: חסר. יד: ליתא."],["12227","84","<b>כנ\"ל</b>: כנצ\"ל: כנ\"ל)."],["12228","85","<b>דז\"א בעתיקא. . אחיד</b>: נסמן לעיל פ' בא קל, ב."],["12229","86","<b>דאבא ואימא. . המזלות</b>: נסמן לעיל פ' שמות לו, א הערה 455."],["12230","87","<b>מזל</b>: זיד: ליתא."],["12231","89","<b>או\"א. . חו\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ\"ג</a>."],["12232","90","<b>או\"א. . תרין</b>: נסמן לעיל פ' בא קכ, א הערה 264."],["12233","88","<b>וגם. . כו'</b>: יד: (גם. . כו')."],["12234","91","<b>והוא. . התפיסא כידוע</b>: ז: (והוא. יד: והוא. . ז: התפיסא כידוע). יד: התפיסא) כידוע."],["12235","92","<b>דא\"א)</b>: זיד: דא\"א."],["12236","93","<b>שהוא. . כידוע</b>: יד: (שהוא. . כידוע)."],["12237","94","<b>ע\"י מלשון המעתיק הרים</b>: ראה גם לעיל קמב, ב. וש\"נ."],["12238","95","<b>דאו\"א מלבישים לזרועות דא\"א</b>: נסמן לעיל פ' בא פט, ב."],["12239","96","<b>שאל נא לימים ראשונים</b>: ואתחנן ד, לב."],["12240","97","<b>במדות דא\"א. . ימי קדם</b>: ראה גם מאמרי אדה\"ז תקס\"ט ע' טז. מאמרי אדה\"א דברים ח\"א ע' נה. וש\"נ. בהערה הבאה."],["12241","98","<b>במדות דא\"א. . הרי קדם</b>: נסמן לעיל פ' בא קכז, ג."]]],[2300540406,"אנו או' ואהבתך לא תסור ממנו<sup data-n=\"12242\">99</sup> שתאהוב אותנו כמו אהבה שתאהוב א\"ע שנק' אהבתך, עד\"מ בין אהבת<sup data-n=\"12243\">100</sup> איש לרעהו שעיקר האהבה הוא כשאוהבו כנפשו דהיינו כמו שאוהב א\"ע ונפשו כמ\"ש [ב]יהונתן [ו]דוד כאהבת נפשו אהבו<sup data-n=\"12244\">101</sup> כו', וממנה נמצא מקור כל המדות הטבעי' והעצמי' דהיינו כל דברים הטובי' לנפשו כו' כנ\"ל. ועל בחי' אהבה זו למעלה נא' הבן יקיר לי אפרים<sup data-n=\"12245\">102</sup> כו' המו מעי לו דוקא כי כל אשר לאיש יתן בעד נפשו<sup data-n=\"12246\">103</sup> שהן כנ\"י שנק' חפצי בה<sup data-n=\"12247\">104</sup> כידוע. וגם מלמטה למעלה מכנ\"י להקב\"ה יש בחי' אהבה זו הפשוטה [כ]אהבת עצמו והוא מ\"ש זכרתי לך חסד נעוריך<sup data-n=\"12248\">105</sup> [אהבת כלולותיך] כו' דוקא בחי' חסד ואהבת נעורי' שהוא למעלה מן השכל והטעם רק כמו בחי' אהבת עצמו וחייו בלא טעם <span data-k=\"pg\">שסד</span> ּ כי א\"א להיות<sup data-n=\"12249\">106</sup> שיתן אדם טעם למה אוהב חיי נפשו כנ\"ל, וזהו לכתך אחרי במדבר<sup data-n=\"12250\">107</sup> כו' וד\"ל. ולפ\"ז הרי מובן למשכיל למעלה בשרש בחי' המדות דז\"א שהן למעלה מבחי' המוחין שבהם, כי הרי שרש המוחין דז\"א נמשך מאו\"א אינן אלא בבחי' זרועות דא\"א דאו\"א מלבישים שם. וז\"ש באדר\"ז דרישא דמלכא<sup data-n=\"12251\">108</sup> בחו\"ג אתקין<sup data-n=\"12252\">109</sup>, פי' רישא דמלכא הוא בחי' חב\"ד דז\"א כידוע ועיקר מקור יניקתם הוא בחו\"ג דא\"א שמקבלים או\"א להמשיך מוחין לז\"א כנ\"ל. אבל ו\"ק דז\"א שרשם למעלה יותר והוא בחי' ג\"ר דע\"י ששם שורה בחי' מל' דא\"ס שנק' נפשו של עצמו' א\"ס כמ\"ש נשבע ה' בנפשו<sup data-n=\"12253\">110</sup> וכמ\"ש במ\"א [בפי'] ואולם חי אני<sup data-n=\"12254\">111</sup> כו', לפי שבחי' אהבת נפשו זאת שנק' אהבת עצמ[ו] למטה ממנה מקור ושרש המדות דע\"י וא\"א. והנה מובן מענין הנ\"ל בשרש מדות הטבעי' באריכות שגם הארת השכל הם בחי' מברר את הטוב כו' אינו אלא עד\"מ המדליק אור במקום חשך שמברר לו את הטוב כו' שאין כל חדש בבחירתו אח\"כ בטוב שהוא רק אהבת עצמו, וכך יובן למעלה בחי' חו\"ג דע\"י שמתלבשים בגולגלתא ומו\"ס<sup data-n=\"12255\">112</sup> ומכ\"ש התלבשות המדות דא\"א באו\"א דאצי' שאין בחי' החכ' רק [כ]מברר יותר באיזה אופן תתלבש המדה כו' וד\"ל.\n<b>והנה</b> מבואר עוד למעלה דאע\"פ ששרש ב' המדות הטבעי' והשכלי' הן בעצם הנפש שלמעלה מן השכל כו', מ\"מ יש הפרש גדול בענין החוזק והתוקף של המדות שלא ישונה ויכול להפכם שע\"י השכל שיגזור החסד ישתנה כו', משא\"כ טבע החסד והרחמים לא ישתנה לעולם ונק' קשה כארז כו' כנ\"ל. והנמשל מזה יובן למשכיל למעלה שזהו ההפרש בין בחי' המדות דז\"א שמתנהגים ע\"פ בחי' המוחי' דאו\"א שמשתנים",[["12242","99","<b>ואהבתך לא תסור ממנו</b>: ברכות ק\"ש (ערבית)."],["12243","100","<b>בין אהבת</b>: ז: אהבה שבין. יד: חסר."],["12244","101","<b>כאהבת נפשו אהבו</b>: שמו\"א כ, יז [ושם: כי אהבת — וכ\"ה בז. יד: כבפנים]."],["12245","102","<b>הבן יקיר לי אפרים</b>: ירמי' לא, יט."],["12246","103","<b>כל אשר לאיש יתן בעד נפשו</b>: איוב ב, ד."],["12247","104","<b>כנ\"י שנק' חפצי בה</b>: ישעי' סב, ד. ראה גם שע\"ת ס, ד ואילך ובהערה 14. לקמן פ' ויקהל תלה, ד."],["12248","105","<b>זכרתי לך חסד נעוריך</b>: ירמי' ב, ב."],["12249","106","<b>להיות</b>: זיד: ליתא."],["12250","107","<b>לכתך אחרי במדבר</b>: המשך הכתוב זכרתי לך חסד נעוריך."],["12251","108","<b>באדר\"ז דרישא דמלכא</b>: נסמן לעיל פ' בא צ, ד."],["12252","109","<b>אתקין</b>: זיד: אתתקן."],["12253","110","<b>נשבע ה' בנפשו</b>: ירמי' נא, יד [ושם: ה' צבאות]. עמוס ו, ח [ושם: אדני ה' אלקים]. ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרלב וע' תרלז. תקס\"ט ע' קפז וע' קצ. שע\"ת צו, ד. מאמרי אדה\"א בראשית ע' נט. וש\"נ. דברים ח\"ג ע' תתעא. וש\"נ. נ\"ך ע' צט. לעיל פ' וארא פג, ד."],["12254","111","<b>ואולם חי אני</b>: שלח יד, כא. ראה גם מאמרי אדה\"ז שבהערה שלפנ\"ז."],["12255","112","<b>חו\"ג דע\"י. . בגולגלתא ומו\"ס</b>: נסמן לעיל פט, ב."]]],[2300540426,"כמ\"ש וינחם ה'<sup data-n=\"12256\">113</sup> כו', אבל בבחי' המדות דע\"י וא\"א שלמעלה מחו\"ב לפי ששרשם בעצמו' המאציל לא ישתנו לעולם כמ\"ש נצח ישראל לא ישקר<sup data-n=\"12257\">114</sup> כו' כי לא אדם הוא להנחם כו', ולא יועיל כח החכ' לבטלם מעיקרם רק להשתיק כח התפשטותם בלבד, אבל לא שיבטל עצם מציאותן כנ\"ל. וז\"ש כי ההרים ימושו כו' וחסדי מאתך לא תמוש<sup data-n=\"12258\">115</sup> כו' (כי<sup data-n=\"12259\">116</sup> אע\"פ שההרים ימושו להיותן ע\"פ השכל אבל חסדי הטבע כמו מצד טבע הטוב כו' לא ימוש לעולם כו') משא\"כ בחי' המדות המתהוים ע\"פ החכ' שימושו ויתבטלו לגמרי כשהחכ' תגזור מחוב לזכות וכן להיפך וד\"ל.\n<b>ומ\"ש</b> למעלה בטעם תוקף המדות הטבעי' על השכלי' מפני שהתפעלו' הנפש בפנימיותו הוא יותר במדות הטבעי' מבשכלי' כנ\"ל ע\"כ אין בכח השכל להטותם כו', והנמשל מזה יובן [למשכיל] למעלה שבחי' אה\"ר או ר\"ר שבע\"י וא\"א יש יותר הארת מל' דא\"ס שבק\"ו כו' מבחי' הפנימי' יותר וע\"ד מ\"ש הבן יקיר לי כו' המו מעי לו ע\"כ רחם ארחמנו כו' עד שאין בכח החכ' גם [ב]בחי' ח\"ס לבטל ולגזור להיפך (וכמו בזמן קי\"ס שתבעה<sup data-n=\"12260\">117</sup> מדה\"ד מה נשתנו אלו מאלו<sup data-n=\"12261\">118</sup> כו' ואעפ\"כ לא הועיל כו'). ושרש הדברים מבואר למעלה דגם באהבת עצמו יש ב' מדריגות, הא' דאהבה הטבעי'. והב' מצד השכל [כו'], ובאהבה זאת שבאה מצד השכל אין כחה באה רק לפי כח השכל הממשיכה ואין לה ערך לגבי בחי' עצמי' כח הטבעי <span data-k=\"pg\">730</span> ּ כו' וע\"כ המדות הטבעי' תקיפי' וחזקים יותר ממדות השכלי' הגם שהם טבעי' ג\"כ כו'. והנמשל מזה יובן למשכיל למעלה שזה ההפרש בין בחי' חפץ חסד שבטבע הטוב מצד עצמו' אוא\"ס שבסיבת זה הי' [כל] עיקר ההשתלשלו' בין התעוררו' אותו החסד בעצמותו מצד מעשה התחתונים עכשיו כמ\"ש בע\"ח<sup data-n=\"12262\">119</sup> שהוא ע\"פ חכ' וטעם כמוס לרצון הפשוט שימשיך לחסד זה מחדש רק לפי כח החכ' ואין לה ערך לגבי עצמו' כח הטבע החסד כו' וד\"ל. וזהו ענין ההפרש בכלל בין בחי' אורות דתהו לבחי' אורות דתיקון שבחי' אורות דתהו תקיפי' וחזקי' הרבה מבחי' אורות דתיקון ואינם מתלבשים ובאין ע\"פ כח החכ' כאורות דתיקון והוא הנק' קשה כארז כנ\"ל וד\"ל.\n<b>וזהו</b> שרש ענין צדקת פרזונו כו' דהנה לעתיד נא' פרזות תשב ירושלים<sup data-n=\"12263\">120</sup> מרוב אדם כו' דהיינו מחמת ריבוי אורות שנק' רוב אדם לא יכולים<sup data-n=\"12264\">121</sup> בחי' הכלים, ואע\"פ שהכלי מגביל",[["12256","113","<b>וינחם ה'</b>: בראשית ו, ו. תשא לב, יד."],["12257","114","<b>נצח ישראל לא ישקר</b>: שמו\"א טו, כט."],["12258","115","<b>כי ההרים. . תמוש</b>: ישעי' נד, י [ושם: ימוש. וכ\"ה בזיד. — ראה שע\"ת קלט, ג ובהערה 15]."],["12259","116","<b>כי</b>: ז: פי'. יד: ליתא."],["12260","117","<b>שתבעה</b>: שם: שטענה."],["12261","118","<b>מה נשתנו אלו מאלו</b>: נסמן לעיל פח, ד."],["12262","119","<b>התעוררו'. . מעשה התחתונים. . בע\"ח</b>: נסמן לעיל קנב, ג."],["12263","120","<b>פרזות תשב ירושלים</b>: זכרי' ב, ח."],["12264","121","<b>יכולים</b>: זיד: יכילם."]]],[2300540446,"את האור, אך מפני תוקף וריבוי האור לא יכול להיות הג[ב]לת הכלי וע\"כ ממילא פרזות תשב ירושלים מבלי חומה מוגבלת לעיר כנ\"ל. וביאור ענין<sup data-n=\"12265\">122</sup> הלא יובן היטב ע\"פ כל הנ\"ל בב' מיני מדות, שבחי' המדות שלמטה מן השכל המה נכנעים תחת השכל וממילא יש להם גבול ושיעור בכלים מכלים שונים המגבילים את האור שיהי' באופן כך וכך ולא יותר, וגם המה מתחלקי' לחלקים [בכלים] רבים [ו]שונים [הכל] ע\"פ הוראת השכל. וזהו ענין הנ\"ל [ב]בחי' התיקון שהוא בחי' המשכת [ה]חכ' במדות לחלקם לס\"ר חלקי' והוא מפני התחלקו' המוחין של המדות לס\"ר מדרגות כו' וכנ\"ל באריכות בענין חכם הרזים, וזהו [כל] עיקר ענין התיקון להתלבש בריבוי כלים וממילא הוא ריבוי התחלקות כו', וגם בחי' אורות דתיקון שנק' ישראל אינם תקיפים וחזקים כ\"כ מפני שהשכל שולט עליהם להטות[ם] מהיפך להיפך כנ\"ל. והנה הגם שמבואר למעלה דגם מדות השכלי' שרשם בעצם הנפש ואין השכל רק כמראה מקום למדות כו', מ\"מ יהי' איך שיהי' השכל מטה אותם ומציירם בכמה מיני כלים מכלים שונים והוא עיקר בחי' התיקון דהיינו ע\"י בחי' הארת חו\"ב בז\"א כנ\"ל. אבל בחי' אורות דתהו היינו כמו בחי' מדות הטבעי' הנ\"ל שלמעלה מן השכל לגמרי דהיינו שאין בכח השכל להטותם כלל ממקומן ונק' קשה כארז כנ\"ל, והוא מפני אהבת עצמו הטבעי' כו' כנ\"ל באריכות, והן היפך מאורות דתיקון בג' דברים הנ\"ל, הא' שחזקים ותקיפי' הרבה מאורות דתיקון מפני שתלוי' בטבע אהבת עצמו כנ\"ל. והב' שאין באים בהתלבשו' בריבוי כלים לפי שמפני תוק[פן] וחזק[ן] לא יגבילם הכלי' כלל (וכמ\"ש בע\"ח<sup data-n=\"12266\">124</sup> דמחמת זה הי' השבירה בכלים לפי שלא יכלו לסבול את האור[ות)]<sup data-n=\"12267\">123</sup>, כענין המאמר לאו כל מוחא סביל דא<sup data-n=\"12268\">126</sup> כשאין כלי המוח סובל ומחזיק לאור עומק השכל כידוע אלא הן אורות בלא כלים כלל (והוא<sup data-n=\"12269\">125</sup> כמו בחי' העקודים שי\"ס עקודים בכל[י] א'<sup data-n=\"12270\">127</sup> ואינם נחלקי' ליו\"ד חלקים<sup data-n=\"12271\">128</sup> ). והג' שאינן באי' בבחי' התחלקות כלל אלא המה אורות פשוטי' וכללי' בלתי מתחלקי'. והכל שרש וענין א' דמשום גודל ותוקף המה בלתי מוגבלים ובלתי מתחלקי', כי הגבלה והתחלקו' ענין א' הוא<sup data-n=\"12272\">129</sup> כידוע ומבואר במ\"א וד\"ל.\n<b>אך</b> הנה [מ\"ש] צדקת פרזונו בישראל היינו <span data-k=\"pg\">שסה</span> ּ שע\"י הצדקה נמשך בחי' פרזונו שהם בחי' אורות דתהו הבלתי מוגבלים<sup data-n=\"12273\">130</sup> ובלתי מתחלקים<sup data-n=\"12274\">131</sup> בכלים בישראל בבחי' הכלים דתיקון. ויש להבין לכאורה ב' דברים, הא' מאחר שבחי' אורות",[["12265","122","<b>ענין</b>: שם: הדברים."],["12266","124","<b>וכמ\"ש בע\"ח</b>: נסמן לעיל רמה, ב הערה 8."],["12267","123","<b>(וכמ\"ש. . האור[ות)]</b>: ז: וכמ\"ש. . האור."],["12268","126","<b>לאו כל מוחא סביל דא</b>: ראה גם של\"ה ב, א. רנא, ב (בהגה). רנז, א. רסג, ב. תו\"ח ויצא קסט, ב ובהערה 14. ש\"א פט, ב."],["12269","125","<b>כענין. . (והוא</b>: ז: (כענין. . והוא."],["12270","127","<b>עקודים בכל[י] א'</b>: נסמן לעיל פ' וארא נב, ד."],["12271","128","<b>חלקים</b>: זיד: כלים."],["12272","129","<b>הגבלה והתחלקו' ענין א' הוא</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקכז."],["12273","130","<b>הבלתי מוגבלים</b>: יד: פשוטים ותקיפים שלא יכילנו. וראה בסמוך בפנים שו\"ה דתהו."],["12274","131","<b>ובלתי מתחלקים</b>: ז: ליתא."]]]]});
